class PersonIdentityUnavailable(RuntimeError):
    """Expected fail-closed signal when identity reconciliation exceeds its bound."""


def preference_identity_part(value: object) -> str:
    return unicodedata.normalize("NFKC", str(value or "").strip()).casefold()


def skill_identity_part(value: object) -> str:
    return unicodedata.normalize("NFKC", str(value or "").strip()).casefold()


def person_identity_part(value: object) -> str:
    normalized = unicodedata.normalize("NFKC", str(value or ""))
    return " ".join(normalized.strip().split()).casefold()


def normalized_task_identity(value: object) -> str:
    """Canonical task identity shared by imports and task-producing workflows."""
    normalized = unicodedata.normalize("NFKC", str(value or ""))
    return " ".join(normalized.strip().split()).casefold()


def _scheduled_job_run_event(value: object) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise TypeError("scheduled job run event must be a mapping")
    occurrence_key = value.get("occurrence_key")
    event_date = value.get("date")
    ran_at = value.get("ran_at")
    status = value.get("status")
    job_type = value.get("job_type")
    schedule_identity_revision = value.get("schedule_identity_revision")
    if (
        type(occurrence_key) is not str
        or SCHEDULED_JOB_RUN_OCCURRENCE_RE.fullmatch(occurrence_key) is None
    ):
        raise ValueError("scheduled job run occurrence key is invalid")
    if type(event_date) is not str or type(ran_at) is not str:
        raise ValueError("scheduled job run timestamps are invalid")
    try:
        parsed_ran_at = datetime.fromisoformat(ran_at)
        parsed_date = date.fromisoformat(event_date)
    except ValueError as exc:
        raise ValueError("scheduled job run timestamps are invalid") from exc
    if parsed_ran_at.date() != parsed_date:
        raise ValueError("scheduled job run date does not match its timestamp")
    if type(status) is not str or status not in SCHEDULED_JOB_RUN_HISTORY_STATUSES:
        raise ValueError("scheduled job run status is invalid")
    if type(job_type) is not str or SCHEDULED_JOB_TYPE_RE.fullmatch(job_type) is None:
        raise ValueError("scheduled job run type is invalid")
    revision_is_legacy_sentinel = (
        job_type == LEGACY_UNKNOWN_SCHEDULED_JOB_TYPE and schedule_identity_revision == -1
    )
    if (
        type(schedule_identity_revision) is not int
        or (
            not revision_is_legacy_sentinel
            and (schedule_identity_revision < 0 or schedule_identity_revision > 9223372036854775807)
        )
    ):
        raise ValueError("scheduled job run identity revision is invalid")
    return {
        "occurrence_key": occurrence_key,
        "date": event_date,
        "ran_at": ran_at,
        "status": status,
        "job_type": job_type,
        "schedule_identity_revision": schedule_identity_revision,
    }


def _legacy_scheduled_job_run_event(value: object) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    event_date = value.get("date")
    ran_at = value.get("ran_at")
    status = value.get("status")
    if type(status) is not str:
        return None
    normalized_status = {"reconciled": "skipped", "held": "failed"}.get(status, status)
    material = {
        "date": event_date,
        "ran_at": ran_at,
        "status": normalized_status,
        "job_type": value.get("job_type"),
        "schedule_identity_revision": value.get("schedule_identity_revision"),
    }
    occurrence_key = value.get("occurrence_key")
    if (
        type(occurrence_key) is not str
        or SCHEDULED_JOB_RUN_OCCURRENCE_RE.fullmatch(occurrence_key) is None
    ):
        digest = hashlib.sha256(
            json.dumps(material, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
        ).hexdigest()
        occurrence_key = f"legacy:{digest}"
    try:
        return _scheduled_job_run_event({"occurrence_key": occurrence_key, **material})
    except (TypeError, ValueError):
        return None


def _untyped_scheduled_job_run_event(value: object) -> dict[str, str] | None:
    """Sanitize pre-schema-3 history for audit retention, never proof."""
    if not isinstance(value, dict):
        return None
    event_date = value.get("date")
    ran_at = value.get("ran_at")
    status = value.get("status")
    if type(event_date) is not str or type(ran_at) is not str or type(status) is not str:
        return None
    normalized_status = {"reconciled": "skipped", "held": "failed"}.get(status, status)
    if normalized_status not in SCHEDULED_JOB_RUN_HISTORY_STATUSES:
        return None
    try:
        parsed_date = date.fromisoformat(event_date)
        parsed_ran_at = datetime.fromisoformat(ran_at)
    except ValueError:
        return None
    if parsed_ran_at.date() != parsed_date:
        return None
    material = {"date": event_date, "ran_at": ran_at, "status": normalized_status}
    occurrence_key = value.get("occurrence_key")
    if (
        type(occurrence_key) is not str
        or SCHEDULED_JOB_RUN_OCCURRENCE_RE.fullmatch(occurrence_key) is None
    ):
        digest = hashlib.sha256(
            json.dumps(material, sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest()
        occurrence_key = f"legacy:{digest}"
    return {"occurrence_key": occurrence_key, **material}


def _job_metadata_with_run_event(
    raw_metadata: object,
    event: object,
    *,
    updates: dict[str, Any] | None = None,
    limit: int = MAX_SCHEDULED_JOB_RUN_HISTORY,
) -> dict[str, Any]:
    normalized_event = _scheduled_job_run_event(event)
    try:
        parsed = json.loads(raw_metadata or "{}")
    except (TypeError, ValueError, json.JSONDecodeError):
        parsed = {}
    metadata = parsed if isinstance(parsed, dict) else {}
    history: list[dict[str, Any]] = []
    seen: set[str] = set()
    raw_history = metadata.get("run_history")
    if metadata.get("run_history_schema") == 3:
        for item in raw_history if isinstance(raw_history, list) else []:
            normalized = _legacy_scheduled_job_run_event(item)
            if normalized is None:
                continue
            key = normalized["occurrence_key"]
            if key == normalized_event["occurrence_key"] or key in seen:
                continue
            seen.add(key)
            history.append(normalized)
    legacy_history: list[dict[str, str]] = []
    legacy_seen: set[str] = set()
    legacy_sources: list[object] = []
    existing_legacy = metadata.get("run_history_legacy")
    if isinstance(existing_legacy, list):
        legacy_sources.extend(existing_legacy)
    if metadata.get("run_history_schema") != 3 and isinstance(raw_history, list):
        legacy_sources.extend(raw_history)
    for item in legacy_sources:
        normalized_legacy = _untyped_scheduled_job_run_event(item)
        if normalized_legacy is None:
            continue
        key = normalized_legacy["occurrence_key"]
        if key in legacy_seen:
            continue
        legacy_seen.add(key)
        legacy_history.append(normalized_legacy)
    history.append(normalized_event)
    bounded_limit = max(1, min(int(limit), MAX_SCHEDULED_JOB_RUN_HISTORY))
    metadata.update(updates or {})
    metadata.update(
        {
            "last_run_status": normalized_event["status"],
            "last_run_status_at": normalized_event["ran_at"],
            "run_history_schema": 3,
            "run_history": history[-bounded_limit:],
        }
    )
    if legacy_history:
        metadata["run_history_legacy_schema"] = 2
        metadata["run_history_legacy"] = legacy_history[-MAX_SCHEDULED_JOB_RUN_HISTORY:]
    else:
        metadata.pop("run_history_legacy_schema", None)
        metadata.pop("run_history_legacy", None)
    return metadata


def _history_positive_int(value: object, *, field: str) -> int:
    if type(value) is not int or value < 1 or value > 9223372036854775807:
        raise ValueError(f"history provenance {field} must be a positive integer")
    return value


def _history_nonnegative_int(value: object, *, field: str) -> int:
    if type(value) is not int or value < 0 or value > MAX_HISTORY_PROVENANCE_SOURCES:
        raise ValueError(f"history provenance {field} must be a bounded non-negative integer")
    return value


def _history_generation(value: object) -> int:
    if type(value) is not int or value < 0 or value > 9223372036854775807:
        raise ValueError("history provenance session generation must be a non-negative integer")
    return value


def _history_opaque_id(value: object, *, field: str) -> str:
    if type(value) is not str or re.fullmatch(r"[0-9a-f]{64}", value) is None:
        raise ValueError(f"history provenance {field} must be an opaque 64-hex identifier")
    return value


def _history_digest(value: object, *, field: str = "digest") -> str:
    if type(value) is not str or re.fullmatch(r"[0-9a-f]{64}", value) is None:
        raise ValueError(f"history provenance {field} is malformed")
    return value


def _history_code(value: object, *, field: str) -> str:
    if (
        type(value) is not str
        or len(value) > MAX_HISTORY_PROVENANCE_CODE_CHARS
        or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]*", value) is None
    ):
        raise ValueError(f"history provenance {field} must be a bounded identifier")
    return value


def _history_destination(value: object) -> str:
    destination = _history_code(value, field="destination class")
    if any(marker in destination for marker in ("*", "?", "[", "]")):
        raise ValueError("history provenance destination class cannot contain wildcards")
    return destination


def _history_role(value: object) -> str:
    if type(value) is not str or value not in {"user", "assistant"}:
        raise ValueError("history provenance role must be exactly user or assistant")
    return value


def _history_remote_eligible(value: object) -> bool:
    if type(value) is not bool:
        raise TypeError("history provenance remote eligibility must be an exact boolean")
    return value


def _history_policy_values(
    policy_fingerprint: object,
    provider: object,
    model_identifier: object,
    destination_class: object,
    session_generation: object,
    explicit_consent_satisfied: object,
) -> tuple[str, str, str, str, int, bool]:
    fingerprint = _history_digest(policy_fingerprint, field="policy fingerprint")
    checked_provider = _history_code(provider, field="provider")
    checked_model = _history_code(model_identifier, field="model identifier")
    checked_destination = _history_destination(destination_class)
    checked_generation = _history_generation(session_generation)
    if type(explicit_consent_satisfied) is not bool:
        raise TypeError("history provenance explicit consent must be an exact boolean")
    return (
        fingerprint,
        checked_provider,
        checked_model,
        checked_destination,
        checked_generation,
        explicit_consent_satisfied,
    )


def _history_message_lineage(
    role: str,
    provenance: dict[str, Any],
) -> tuple[str, int, str | None, bool]:
    if "lineage_state" not in provenance:
        lineage_state = "direct_current" if role == "user" else "mixed_restricted"
    else:
        state_value = provenance["lineage_state"]
        if type(state_value) is not str or state_value not in HISTORY_MESSAGE_LINEAGE_STATES:
            raise ValueError("message provenance lineage state is invalid")
        lineage_state = state_value

    source_count = _history_nonnegative_int(
        provenance.get("source_count", 0), field="message source count"
    )
    digest_value = provenance.get("source_digest")
    source_digest = (
        None
        if digest_value is None
        else _history_digest(digest_value, field="message source digest")
    )
    direct_complete = (
        lineage_state == "direct_current" and source_count == 0 and source_digest is None
    )
    derived_complete = (
        lineage_state in {"personal_derived", "tool_derived"}
        and source_count > 0
        and source_digest is not None
    )
    mixed_complete = (
        lineage_state == "mixed_restricted"
        and source_count > 0
        and source_digest is not None
    )
    mixed_incomplete = (
        lineage_state == "mixed_restricted"
        and source_count == 0
        and source_digest is None
    )
    if not (direct_complete or derived_complete or mixed_complete or mixed_incomplete):
        raise ValueError("message provenance lineage facts are inconsistent")
    return lineage_state, source_count, source_digest, not mixed_incomplete


def history_message_content_digest(role: object, content: object) -> str:
    """Hash one exact message without retaining its role or content in provenance."""
    checked_role = _history_role(role)
    if type(content) is not str:
        raise TypeError("history provenance message content must be a string")
    payload = json.dumps(
        {
            "domain": "jarvis-history-message-content-v1",
            "role": checked_role,
            "content": content,
        },
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("ascii")
    return hashlib.sha256(payload).hexdigest()


def history_memory_content_digest(title: object, body: object) -> str:
    """Hash the exact user-visible content of one derived memory."""
    if type(title) is not str or type(body) is not str:
        raise TypeError("history provenance memory title and body must be strings")
    payload = json.dumps(
        {
            "domain": "jarvis-history-memory-content-v1",
            "title": title,
            "body": body,
        },
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("ascii")
    return hashlib.sha256(payload).hexdigest()


def history_source_digest(
    source_ids: Iterable[int] | Iterable[tuple[int, str, str]],
    lineage_tokens: Iterable[str] | None = None,
    content_digests: Iterable[str] | None = None,
) -> str:
    """Digest source identities, lineage tokens, and exact role/content hashes."""
    try:
        raw_sources = tuple(source_ids)
    except TypeError as exc:
        raise TypeError("history provenance sources must be iterable") from exc
    if lineage_tokens is None and content_digests is None:
        triples: list[tuple[object, object, object]] = []
        for source in raw_sources:
            if type(source) not in {tuple, list} or len(source) != 3:
                raise ValueError(
                    "history provenance sources must bind ids, lineage tokens, and content digests"
                )
            triples.append((source[0], source[1], source[2]))
    else:
        if lineage_tokens is None or content_digests is None:
            raise ValueError(
                "history provenance lineage tokens and content digests must be supplied together"
            )
        try:
            tokens = tuple(lineage_tokens)
            digests = tuple(content_digests)
        except TypeError as exc:
            raise TypeError("history provenance lineage evidence must be iterable") from exc
        if len(raw_sources) != len(tokens) or len(raw_sources) != len(digests):
            raise ValueError("history provenance source evidence must align")
        triples = list(zip(raw_sources, tokens, digests))
    if not triples or len(triples) > MAX_HISTORY_PROVENANCE_SOURCES:
        raise ValueError("history provenance sources must be non-empty and bounded")
    canonical: list[tuple[int, str, str]] = []
    seen_ids: set[int] = set()
    for source_id, lineage_token, content_digest in triples:
        checked_id = _history_positive_int(source_id, field="source id")
        if checked_id in seen_ids:
            raise ValueError("history provenance source ids must be unique")
        seen_ids.add(checked_id)
        canonical.append(
            (
                checked_id,
                _history_opaque_id(lineage_token, field="lineage token"),
                _history_digest(content_digest, field="content digest"),
            )
        )
    payload = json.dumps(
        {
            "domain": "jarvis-history-source-provenance-v2",
            "sources": sorted(canonical),
        },
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("ascii")
    return hashlib.sha256(payload).hexdigest()


source_provenance_digest = history_source_digest


