def approval_action_digest(tool_name: str, planned_args: dict[str, Any]) -> str:
    payload = json.dumps(
        {"tool_name": str(tool_name), "planned_args": planned_args},
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("ascii")
    return hashlib.sha256(payload).hexdigest()


def auto_mutation_request_digest(request_token: str) -> str:
    if not isinstance(request_token, str) or not request_token:
        raise ValueError("auto mutation request token must be a non-empty string")
    payload = json.dumps(
        {"request_token": request_token},
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("ascii")
    return hashlib.sha256(payload).hexdigest()


def auto_mutation_action_digest(tool_name: str, args: dict[str, Any]) -> str:
    if not isinstance(tool_name, str) or not tool_name.strip():
        raise ValueError("auto mutation tool name must be a non-empty string")
    if len(tool_name) > MAX_AUTO_MUTATION_TOOL_NAME_CHARS:
        raise ValueError("auto mutation tool name is too long")
    if not isinstance(args, dict):
        raise TypeError("auto mutation arguments must be a dictionary")
    return approval_action_digest(tool_name, args)


