def _bootstrap_target_date(value: object) -> str:
    if type(value) is not str or re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", value) is None:
        raise ValueError("invalid bootstrap summary target date")
    try:
        parsed = datetime.strptime(value, "%Y-%m-%d")
    except ValueError as exc:
        raise ValueError("invalid bootstrap summary target date") from exc
    if parsed.strftime("%Y-%m-%d") != value:
        raise ValueError("invalid bootstrap summary target date")
    return value


def memory_projection_source_digest(
    memory_id: int,
    revision: int,
    category: str,
    title: str,
    body: str,
    source: str,
    confidence: float,
    created_at: str,
    operation: str,
) -> str:
    """Hash an exact memory mutation without retaining its body in the job."""
    memory_id = _memory_projection_positive_int(memory_id, field="memory id")
    revision = _memory_projection_positive_int(revision, field="revision")
    operation = _memory_projection_operation(operation)
    fields = {
        "category": category,
        "title": title,
        "body": body,
        "source": source,
        "created_at": created_at,
    }
    if any(type(value) is not str for value in fields.values()):
        raise ValueError("memory projection source fields must be strings")
    if isinstance(confidence, bool) or not isinstance(confidence, (int, float)):
        raise ValueError("memory projection confidence must be numeric")
    confidence_value = float(confidence)
    if not math.isfinite(confidence_value):
        raise ValueError("memory projection confidence must be finite")
    payload = json.dumps(
        {
            "body": body,
            "category": category,
            "confidence": confidence_value,
            "created_at": created_at,
            "memory_id": memory_id,
            "operation": operation,
            "revision": revision,
            "source": source,
            "title": title,
        },
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        allow_nan=False,
    ).encode("ascii")
    return hashlib.sha256(payload).hexdigest()


