def person_projection_source_digest(
    person_id: int,
    revision: int,
    name: str,
    relation: str,
    notes: str,
    last_contact_at: str | None,
    created_at: str,
    updated_at: str,
    interaction_high_watermark: int,
    rendered_interactions: Iterable[str],
) -> str:
    """Hash one exact person row and its bounded rendered interaction snapshot."""
    person_id = _person_projection_positive_int(person_id, field="person id")
    revision = _person_projection_nonnegative_int(revision, field="revision")
    interaction_high_watermark = _person_projection_nonnegative_int(
        interaction_high_watermark, field="interaction high watermark"
    )
    fields = (name, relation, notes, created_at, updated_at)
    if any(type(value) is not str for value in fields):
        raise ValueError("person projection source fields must be strings")
    if last_contact_at is not None and type(last_contact_at) is not str:
        raise ValueError("person projection last contact must be a string or null")
    interactions = tuple(rendered_interactions)
    if not interactions or len(interactions) > MAX_PERSON_PROJECTION_INTERACTIONS:
        raise ValueError("person projection interaction snapshot is invalid")
    if any(type(value) is not str for value in interactions):
        raise ValueError("person projection rendered interactions must be strings")
    payload = json.dumps(
        {
            "created_at": created_at,
            "interaction_high_watermark": interaction_high_watermark,
            "interactions": interactions,
            "last_contact_at": last_contact_at,
            "name": name,
            "notes": notes,
            "person_id": person_id,
            "relation": relation,
            "revision": revision,
            "updated_at": updated_at,
        },
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("ascii")
    return hashlib.sha256(payload).hexdigest()


def decision_projection_source_digest(
    decision_id: int,
    revision: int,
    title: str,
    rationale: str,
    impact: str,
    status: str,
    created_at: str,
    updated_at: str,
    outcomes: Iterable[Any] = (),
) -> str:
    decision_id = _person_projection_positive_int(decision_id, field="decision id")
    revision = _person_projection_positive_int(revision, field="decision revision")
    fields = (title, rationale, impact, status, created_at, updated_at)
    if any(type(value) is not str for value in fields):
        raise ValueError("decision projection source fields must be strings")
    rendered_outcomes: list[dict[str, Any]] = []
    seen_ids: set[int] = set()
    seen_revisions: set[int] = set()
    for index, outcome in enumerate(outcomes):
        if index >= MAX_DECISION_PROJECTION_OUTCOMES:
            raise ValueError("decision projection outcome snapshot exceeds its bound")
        try:
            item = {
                "created_at": outcome["created_at"],
                "decision_id": outcome["decision_id"],
                "decision_revision": outcome["decision_revision"],
                "id": outcome["id"],
                "provenance": outcome["provenance"],
                "summary": outcome["summary"],
            }
        except (KeyError, IndexError, TypeError) as exc:
            raise ValueError("decision projection outcome row is malformed") from exc
        if (
            type(item["id"]) is not int
            or item["id"] < 1
            or type(item["decision_id"]) is not int
            or item["decision_id"] != decision_id
            or type(item["decision_revision"]) is not int
            or item["decision_revision"] < 1
            or item["decision_revision"] > revision
            or type(item["created_at"]) is not str
            or type(item["provenance"]) is not str
            or item["provenance"] != "user_reported"
        ):
            raise ValueError("decision projection outcome row is malformed")
        _validate_decision_outcome_summary(item["summary"])
        if item["id"] in seen_ids or item["decision_revision"] in seen_revisions:
            raise ValueError("decision projection outcome identity is duplicated")
        seen_ids.add(item["id"])
        seen_revisions.add(item["decision_revision"])
        rendered_outcomes.append(item)
    rendered_outcomes.sort(key=lambda item: (item["decision_revision"], item["id"]))
    source: dict[str, Any] = {
        "created_at": created_at,
        "decision_id": decision_id,
        "impact": impact,
        "rationale": rationale,
        "revision": revision,
        "status": status,
        "title": title,
        "updated_at": updated_at,
    }
    if rendered_outcomes:
        source["outcomes"] = rendered_outcomes
    payload = json.dumps(
        source,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("ascii")
    return hashlib.sha256(payload).hexdigest()


