def _goal_projection_digest_history(value: object) -> tuple[str, ...]:
    if type(value) is not str or not 2 <= len(value) <= 18_000:
        raise ValueError("invalid goal projection prepared digest history")
    try:
        decoded = json.loads(value)
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise ValueError("invalid goal projection prepared digest history") from exc
    if (
        type(decoded) is not list
        or len(decoded) > MAX_GOAL_PROJECTION_PREPARED_DIGESTS
        or any(
            type(item) is not str or re.fullmatch(r"[0-9a-f]{64}", item) is None
            for item in decoded
        )
        or len(set(decoded)) != len(decoded)
        or value
        != json.dumps(decoded, separators=(",", ":"), ensure_ascii=True)
    ):
        raise ValueError("invalid goal projection prepared digest history")
    return tuple(decoded)


