def goal_projection_source_digest(
    goal_id: int,
    revision: int,
    title: str,
    purpose: str,
    horizon: str,
    status: str,
    created_at: str,
    updated_at: str,
    steps: Iterable[Any] = (),
) -> str:
    """Hash one exact goal row and every step in canonical id order."""
    goal_id = _goal_projection_positive_int(goal_id, field="goal id")
    revision = _goal_projection_positive_int(revision, field="goal revision")
    if any(
        type(value) is not str
        for value in (title, purpose, horizon, status, created_at, updated_at)
    ):
        raise ValueError("goal projection source fields must be strings")

    ordered_steps: list[dict[str, Any]] = []
    seen_ids: set[int] = set()
    for step in steps:
        try:
            item = {
                "body": step["body"],
                "completed_at": step["completed_at"],
                "created_at": step["created_at"],
                "goal_id": step["goal_id"],
                "id": step["id"],
                "status": step["status"],
                "updated_at": step["updated_at"],
            }
        except (KeyError, IndexError, TypeError) as exc:
            raise ValueError("goal projection step row is malformed") from exc
        step_id = item["id"]
        if (
            type(step_id) is not int
            or step_id < 1
            or step_id > 9223372036854775807
            or step_id in seen_ids
            or type(item["goal_id"]) is not int
            or item["goal_id"] != goal_id
            or any(
                type(item[field]) is not str
                for field in ("body", "created_at", "status", "updated_at")
            )
            or (
                item["completed_at"] is not None
                and type(item["completed_at"]) is not str
            )
        ):
            raise ValueError("goal projection step row is malformed")
        seen_ids.add(step_id)
        ordered_steps.append(item)
    ordered_steps.sort(key=lambda item: item["id"])

    payload = json.dumps(
        {
            "created_at": created_at,
            "goal_id": goal_id,
            "horizon": horizon,
            "purpose": purpose,
            "revision": revision,
            "status": status,
            "steps": ordered_steps,
            "title": title,
            "updated_at": updated_at,
        },
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("ascii")
    return hashlib.sha256(payload).hexdigest()


def normalize_decision_outcome_summary(value: object) -> str:
    if type(value) is not str:
        return ""
    normalized = unicodedata.normalize("NFKC", value)
    return normalized.replace("\r\n", "\n").replace("\r", "\n").strip()


def profile_note_source_key(heading: object, body: object, category: object) -> str:
    if any(type(value) is not str for value in (heading, body, category)):
        raise TypeError("profile note identity fields must be strings")
    material = json.dumps(
        {"heading": heading, "body": body, "category": category},
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    )
    return "profile-note:v1:" + hashlib.sha256(material.encode("utf-8")).hexdigest()


def decision_outcome_summary_safety_reason(value: object) -> str | None:
    if type(value) is not str:
        return "invalid_summary_type"
    if not value:
        return "missing_summary"
    if len(value) > MAX_DECISION_OUTCOME_SUMMARY_CHARS:
        return "oversized_summary"
    if value != normalize_decision_outcome_summary(value):
        return "noncanonical_summary"
    try:
        value.encode("utf-8")
    except UnicodeEncodeError:
        return "unsafe_unicode"
    if any(
        unicodedata.category(character) in {"Cc", "Cf", "Cs", "Zl", "Zp"}
        for character in value
    ):
        return "unsafe_unicode"
    if DECISION_OUTCOME_ACTIVE_RENDER_RE.search(value):
        return "active_render_content"
    if DECISION_OUTCOME_RESERVED_MARKER_RE.search(value):
        return "reserved_projection_marker"
    if DECISION_OUTCOME_PATH_RE.search(value) or DECISION_OUTCOME_RELATIVE_PATH_RE.search(value):
        return "path_shaped_summary"
    return None


def _validate_decision_outcome_summary(value: object) -> str:
    reason = decision_outcome_summary_safety_reason(value)
    if reason is not None:
        raise ValueError(f"decision outcome summary is invalid: {reason}")
    assert isinstance(value, str)
    return value


def preference_projection_source_digest(generation: int, rows: Iterable[Any]) -> str:
    generation = _person_projection_nonnegative_int(
        generation, field="preference generation"
    )
    rendered: list[dict[str, Any]] = []
    for row in rows:
        try:
            item = {
                "category": row["category"],
                "created_at": row["created_at"],
                "id": row["id"],
                "key": row["key"],
                "revision": row["revision"],
                "status": row["status"],
                "updated_at": row["updated_at"],
                "value": row["value"],
            }
        except (KeyError, IndexError, TypeError) as exc:
            raise ValueError("preference projection source row is malformed") from exc
        if (
            type(item["id"]) is not int
            or item["id"] < 1
            or type(item["revision"]) is not int
            or item["revision"] < 1
            or any(
                type(item[key]) is not str
                for key in (
                    "category",
                    "created_at",
                    "key",
                    "status",
                    "updated_at",
                    "value",
                )
            )
        ):
            raise ValueError("preference projection source row is malformed")
        rendered.append(item)
    payload = json.dumps(
        {"generation": generation, "rows": rendered},
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("ascii")
    return hashlib.sha256(payload).hexdigest()


def _preference_promotion_source_integrity_binding(
    store_identity: str,
    preference_id: int,
    memory_id: int,
    preference_target: "PreferenceProjectionTarget",
    memory_target: "MemoryProjectionTarget",
) -> str:
    if (
        type(store_identity) is not str
        or re.fullmatch(r"[0-9a-f]{32}", store_identity) is None
        or type(preference_id) is not int
        or preference_id < 1
        or type(memory_id) is not int
        or memory_id < 1
        or not isinstance(preference_target, PreferenceProjectionTarget)
        or not isinstance(memory_target, MemoryProjectionTarget)
    ):
        raise ValueError("preference promotion integrity evidence is malformed")
    payload = json.dumps(
        {
            "memory_id": memory_id,
            "memory_operation": memory_target.operation,
            "memory_revision": memory_target.revision,
            "memory_source_digest": memory_target.source_digest,
            "preference_generation": preference_target.generation,
            "preference_id": preference_id,
            "preference_source_digest": preference_target.source_digest,
            "store_identity": store_identity,
        },
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("ascii")
    return hashlib.sha256(payload).hexdigest()


def _skill_projection_positive_int(value: object, *, field: str) -> int:
    if type(value) is not int or value < 1 or value > 9223372036854775807:
        raise ValueError(f"skill projection {field} must be a positive integer")
    return value


def _skill_projection_digest(value: object, *, field: str) -> str:
    if type(value) is not str or re.fullmatch(r"[0-9a-f]{64}", value) is None:
        raise ValueError(f"invalid skill projection {field}")
    return value


def _skill_projection_operation(value: object) -> str:
    if type(value) is not str or value not in {"publish", "delete"}:
        raise ValueError("invalid skill projection operation")
    return value


def _skill_projection_path_display(value: object, *, nullable: bool) -> str | None:
    if value is None and nullable:
        return None
    if (
        type(value) is not str
        or not value
        or len(value) > MAX_SKILL_PROJECTION_PATH_DISPLAY_CHARS
    ):
        raise ValueError("invalid skill projection path display")
    return value


def _skill_projection_error_code(value: object) -> str:
    if (
        type(value) is not str
        or not value
        or len(value) > MAX_SKILL_PROJECTION_ERROR_CODE_CHARS
        or re.fullmatch(r"[A-Za-z0-9_.:-]+", value) is None
    ):
        raise ValueError("invalid skill projection error code")
    return value


def _startup_recovery_run_id(value: object) -> int:
    if type(value) is not int or value < 1 or value > 9223372036854775807:
        raise ValueError("startup recovery run id must be a positive integer")
    return value


def _startup_recovery_runtime_session_id(value: object) -> str:
    if (
        type(value) is not str
        or re.fullmatch(r"[0-9a-f]{8}", value) is None
    ):
        raise ValueError("startup recovery runtime session id must be an opaque hex identifier")
    return value


def _startup_recovery_exception_type(value: object) -> str:
    if (
        type(value) is not str
        or value not in STARTUP_RECOVERY_EXCEPTION_TYPES
    ):
        raise ValueError("startup recovery exception type is not in the safe diagnostic vocabulary")
    return value


def _startup_recovery_timestamp(value: object) -> str:
    if (
        type(value) is not str
        or re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z", value)
        is None
    ):
        raise ValueError("startup recovery timestamp is invalid")
    try:
        datetime.strptime(value, "%Y-%m-%dT%H:%M:%SZ")
    except ValueError:
        raise ValueError("startup recovery timestamp is invalid") from None
    return value


def _startup_recovery_component(value: object) -> str:
    if type(value) is not str or value not in STARTUP_RECOVERY_COMPONENTS:
        raise ValueError("startup recovery component is invalid")
    return value


def _startup_recovery_summary(summary: object) -> dict[str, Any]:
    if type(summary) is not dict:
        raise TypeError("startup recovery component summary must be an exact dictionary")
    allowed = {
        "status",
        "attempted",
        "completed",
        "pending",
        "custody_backfilled",
        "custody_conflicts",
        "exception_type",
    }
    if any(type(key) is not str for key in summary):
        raise TypeError("startup recovery component summary keys must be exact strings")
    keys = set(summary)
    if "status" not in keys or keys - allowed:
        raise ValueError("startup recovery component summary fields are invalid")
    status = summary["status"]
    if type(status) is not str or status not in STARTUP_RECOVERY_COMPONENT_STATES:
        raise ValueError("startup recovery component status is invalid")
    checked: dict[str, Any] = {"status": status}
    for field in (
        "attempted",
        "completed",
        "pending",
        "custody_backfilled",
        "custody_conflicts",
    ):
        if field not in summary:
            continue
        count = summary[field]
        if type(count) is not int or count < 0 or count > MAX_STARTUP_RECOVERY_COUNT:
            raise ValueError(f"startup recovery {field} must be a bounded non-negative integer")
        checked[field] = count
    if "exception_type" in summary:
        checked["exception_type"] = _startup_recovery_exception_type(
            summary["exception_type"]
        )
    if status == "failed" and "exception_type" not in checked:
        raise ValueError("failed startup recovery component requires an exception type")
    if status != "failed" and "exception_type" in checked:
        raise ValueError("non-failed startup recovery component cannot carry an exception type")
    count_fields = {"attempted", "completed", "pending"}
    if status == "failed" and keys & (count_fields | {"custody_backfilled", "custody_conflicts"}):
        raise ValueError("failed startup recovery component cannot carry recovery counts")
    if status != "failed" and not count_fields <= keys:
        raise ValueError("non-failed startup recovery component requires complete recovery counts")
    if checked.get("completed", 0) > checked.get("attempted", 0):
        raise ValueError("startup recovery completed count cannot exceed attempted count")
    if status == "completed" and (
        checked.get("pending", 0) != 0
        or checked.get("custody_conflicts", 0) != 0
    ):
        raise ValueError("completed startup recovery component cannot have unresolved work")
    if status == "partial" and (
        checked.get("pending", 0) == 0
        and checked.get("custody_conflicts", 0) == 0
    ):
        raise ValueError("partial startup recovery component needs pending or conflict evidence")
    return checked


def _startup_recovery_summaries_json(summaries: object) -> str:
    if type(summaries) is not dict:
        raise RuntimeError("startup recovery component summaries are invalid")
    checked: dict[str, dict[str, Any]] = {}
    for component, summary in summaries.items():
        try:
            checked_component = _startup_recovery_component(component)
            checked[checked_component] = _startup_recovery_summary(summary)
        except (TypeError, ValueError) as exc:
            raise RuntimeError("startup recovery component summaries are invalid") from exc
    payload = json.dumps(
        checked,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        allow_nan=False,
    )
    if len(payload) > MAX_STARTUP_RECOVERY_SUMMARIES_CHARS:
        raise RuntimeError("startup recovery component summaries are too large")
    return payload


def _startup_recovery_parse_summaries(value: object) -> dict[str, dict[str, Any]]:
    if type(value) is not str or len(value) > MAX_STARTUP_RECOVERY_SUMMARIES_CHARS:
        raise RuntimeError("startup recovery component summaries are invalid")
    try:
        parsed = json.loads(value)
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise RuntimeError("startup recovery component summaries are invalid") from exc
    canonical = _startup_recovery_summaries_json(parsed)
    if canonical != value:
        raise RuntimeError("startup recovery component summaries are not canonical")
    return parsed


def _validate_startup_recovery_row(row: sqlite3.Row) -> None:
    try:
        _startup_recovery_run_id(row["run_id"])
        _startup_recovery_runtime_session_id(row["runtime_session_id"])
        state = row["state"]
        if type(state) is not str or state not in STARTUP_RECOVERY_RUN_STATES:
            raise ValueError("startup recovery run state is invalid")
        summaries = _startup_recovery_parse_summaries(row["details"])
        revision = row["revision"]
        if type(revision) is not int or not 0 <= revision <= MAX_STARTUP_RECOVERY_COUNT:
            raise ValueError("startup recovery revision is invalid")
        started_at = _startup_recovery_timestamp(row["started_at"])
        updated_at = _startup_recovery_timestamp(row["updated_at"])
        finished_at_value = row["finished_at"]
        finished_at = (
            None
            if finished_at_value is None
            else _startup_recovery_timestamp(finished_at_value)
        )
        if updated_at < started_at or (finished_at is not None and finished_at < started_at):
            raise ValueError("startup recovery timestamp order is invalid")
        exception_type = row["exception_type"]
        if state == "failed":
            _startup_recovery_exception_type(exception_type)
        elif exception_type is not None:
            raise ValueError("non-failed startup recovery run cannot carry an exception type")
        if state == "running" and finished_at is not None:
            raise ValueError("running startup recovery run cannot be finished")
        if state != "running" and finished_at is None:
            raise ValueError("terminal startup recovery run requires a finish timestamp")
        if state in {"completed", "partial"}:
            if set(summaries) != set(STARTUP_RECOVERY_COMPONENTS):
                raise ValueError("finalized startup recovery run is missing component summaries")
            all_completed = all(
                summaries[component]["status"] == "completed"
                for component in STARTUP_RECOVERY_COMPONENTS
            )
            if (state == "completed") != all_completed:
                raise ValueError("startup recovery run state contradicts component evidence")
    except (IndexError, KeyError, TypeError, ValueError, RuntimeError) as exc:
        raise RuntimeError("startup recovery durable row is invalid") from None


def _startup_recovery_mutation_timestamp(row: sqlite3.Row) -> str:
    candidate = _startup_recovery_timestamp(utc_now())
    started_at = _startup_recovery_timestamp(row["started_at"])
    updated_at = _startup_recovery_timestamp(row["updated_at"])
    return max(candidate, started_at, updated_at)


def _validate_startup_recovery_schema_sql(value: object) -> None:
    if type(value) is not str:
        raise RuntimeError("startup recovery ledger schema is incompatible")
    normalized = " ".join(value.strip().rstrip(";").split())
    expected = " ".join(STARTUP_RECOVERY_TABLE_SQL.split())
    if normalized != expected:
        raise RuntimeError("startup recovery ledger schema is incompatible")


def skill_projection_source_digest(
    skill_id: int,
    revision: int,
    name: str,
    trigger: str,
    body: str,
    tags: str,
    operation: str,
) -> str:
    """Hash the canonical skill mutation without retaining its content in the job."""
    skill_id = _skill_projection_positive_int(skill_id, field="skill id")
    revision = _skill_projection_positive_int(revision, field="revision")
    operation = _skill_projection_operation(operation)
    fields = {
        "name": name,
        "trigger": trigger,
        "body": body,
        "tags": tags,
    }
    if any(type(value) is not str for value in fields.values()):
        raise ValueError("skill projection source fields must be strings")
    payload = json.dumps(
        {
            "body": body,
            "name": name,
            "operation": operation,
            "revision": revision,
            "skill_id": skill_id,
            "tags": tags,
            "trigger": trigger,
        },
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("ascii")
    return hashlib.sha256(payload).hexdigest()


def _is_proven_generated_session_skill_draft(tags: object, body: object) -> bool:
    if type(tags) is not str or type(body) is not str:
        return False
    tag_parts = tuple(part.strip() for part in tags.split(","))
    if len(tag_parts) != len(SESSION_SKILL_DRAFT_TAGS):
        return False
    if frozenset(tag_parts) != SESSION_SKILL_DRAFT_TAGS:
        return False
    return all(marker in body for marker in SESSION_SKILL_DRAFT_BODY_MARKERS)


def _new_skill_origin(tags: object, body: object) -> str:
    """Classify new skill custody once; later rewrites never weaken it."""
    if type(tags) is not str or type(body) is not str:
        return "user_authored"
    normalized_tags = {
        part
        for part in re.split(r"[,;\s]+", unicodedata.normalize("NFKC", tags).casefold())
        if part
    }
    history_tags = {
        "session-derived",
        "history-derived",
        "source-session",
        "source-history",
        "session_history",
        "chat-history-derived",
    }
    normalized_body = unicodedata.normalize("NFKC", body).casefold()
    history_markers = (
        "this is a reviewable skill draft inferred from a jarvis session",
        "## source session signals",
        "[session-derived]",
        "[history-derived]",
        "lineage: session-derived",
        "lineage: history-derived",
    )
    if (
        _is_proven_generated_session_skill_draft(tags, body)
        or bool(normalized_tags & history_tags)
        or ("session" in normalized_tags and {"draft", "human-review-required"} & normalized_tags)
        or any(marker in normalized_body for marker in history_markers)
    ):
        return "session_history"
    return "user_authored"


def subagent_lease_digest(lease_token: str) -> str:
    if not isinstance(lease_token, str) or not lease_token:
        raise ValueError("subagent lease token must be non-empty")
    return hashlib.sha256(lease_token.encode("utf-8")).hexdigest()


def _subagent_epoch_ms(value: int | None = None) -> int:
    if value is None:
        return time.time_ns() // 1_000_000
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError("subagent timestamp must be a non-negative integer")
    return value


def _subagent_bounded_code(value: object, *, field: str) -> str:
    if type(value) is not str:
        raise ValueError(f"subagent {field} must be a string")
    text = value.strip()
    if not text or len(text) > MAX_SUBAGENT_CODE_CHARS or re.fullmatch(r"[A-Za-z0-9_.:-]+", text) is None:
        raise ValueError(f"invalid subagent {field}")
    return text


def _subagent_digest(value: object, *, field: str) -> str:
    if type(value) is not str or re.fullmatch(r"[0-9a-f]{64}", value) is None:
        raise ValueError(f"invalid subagent {field}")
    return value


def _subagent_result_retention_ms(value: int | None) -> int | None:
    if value is None:
        return None
    if (
        isinstance(value, bool)
        or not isinstance(value, int)
        or value < 100
        or value > MAX_SUBAGENT_RESULT_RETENTION_MS
    ):
        raise ValueError("subagent result retention duration is invalid")
    return value


def _subagent_result_batch_limit(value: int) -> int:
    if (
        isinstance(value, bool)
        or not isinstance(value, int)
        or value < 1
        or value > MAX_SUBAGENT_RESULT_BATCH
    ):
        raise ValueError("subagent result batch limit is invalid")
    return value


def _valid_utc_timestamp(value: object) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    try:
        datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return False
    return True


def _strict_utc_timestamp(value: object) -> datetime | None:
    if type(value) is not str or value != value.strip() or "T" not in value:
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None or parsed.utcoffset() != timedelta(0):
        return None
    return parsed.astimezone(timezone.utc)


def _knowledge_promotion_timestamps_are_valid(row: sqlite3.Row) -> bool:
    created_at = _strict_utc_timestamp(row["created_at"])
    updated_at = _strict_utc_timestamp(row["updated_at"])
    return created_at is not None and updated_at is not None and updated_at >= created_at


def _history_disclosure_prepared_at_is_fresh(
    value: object,
    *,
    now: datetime | None = None,
) -> bool:
    """Treat only bounded, timezone-aware receipt timestamps as egress authority."""
    if type(value) is not str or not value.strip():
        return False
    try:
        prepared_at = datetime.fromisoformat(value.replace("Z", "+00:00"))
        if prepared_at.tzinfo is None or prepared_at.utcoffset() is None:
            return False
        prepared_at = prepared_at.astimezone(timezone.utc)
    except (OverflowError, TypeError, ValueError):
        return False
    checked_now = now or datetime.now(timezone.utc)
    if checked_now.tzinfo is None or checked_now.utcoffset() is None:
        return False
    age_seconds = (checked_now.astimezone(timezone.utc) - prepared_at).total_seconds()
    return 0 <= age_seconds < HISTORY_DISCLOSURE_STALE_AFTER_SECONDS


def _migration_thread_lock(db_path: Path) -> tuple[str, threading.Lock]:
    db_key = str(db_path.resolve())
    with _MIGRATION_THREAD_LOCKS_GUARD:
        return db_key, _MIGRATION_THREAD_LOCKS.setdefault(db_key, threading.Lock())


@contextmanager
def _migration_lock(db_path: Path) -> Generator[None, None, None]:
    """Bound schema upgrades across threads and local Unix processes."""
    db_key, thread_lock = _migration_thread_lock(db_path)
    lock_path = Path(f"{db_key}.migration.lock")
    deadline = time.monotonic() + MIGRATION_LOCK_TIMEOUT_SECONDS
    if not thread_lock.acquire(timeout=MIGRATION_LOCK_TIMEOUT_SECONDS):
        raise TimeoutError(
            f"timed out after {MIGRATION_LOCK_TIMEOUT_SECONDS:.1f}s waiting for "
            f"database migration lock: {lock_path}"
        )

    fd = -1
    file_locked = False
    try:
        flags = os.O_RDWR | os.O_CREAT
        flags |= getattr(os, "O_CLOEXEC", 0)
        nofollow = getattr(os, "O_NOFOLLOW", 0)
        flags |= nofollow
        try:
            if not nofollow and lock_path.is_symlink():
                raise OSError(errno.ELOOP, "symbolic link refused", str(lock_path))
            fd = os.open(lock_path, flags, 0o600)
            os.fchmod(fd, 0o600)
        except OSError as exc:
            raise RuntimeError(f"could not open database migration lock {lock_path}: {exc}") from exc

        while True:
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                file_locked = True
                break
            except OSError as exc:
                if exc.errno == errno.EINTR:
                    continue
                if exc.errno not in (errno.EACCES, errno.EAGAIN):
                    raise RuntimeError(
                        f"could not acquire database migration lock {lock_path}: {exc}"
                    ) from exc
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise TimeoutError(
                        f"timed out after {MIGRATION_LOCK_TIMEOUT_SECONDS:.1f}s waiting for "
                        f"database migration lock: {lock_path}"
                    ) from exc
                time.sleep(min(MIGRATION_LOCK_POLL_SECONDS, remaining))

        yield
    finally:
        body_failed = sys.exc_info()[0] is not None
        cleanup_error: OSError | None = None
        if file_locked and fd >= 0:
            try:
                fcntl.flock(fd, fcntl.LOCK_UN)
            except OSError as exc:
                cleanup_error = exc
        if fd >= 0:
            try:
                os.close(fd)
            except OSError as exc:
                cleanup_error = cleanup_error or exc
        thread_lock.release()
        if cleanup_error is not None and not body_failed:
            raise RuntimeError(
                f"could not release database migration lock {lock_path}: {cleanup_error}"
            ) from cleanup_error


def _history_authority_thread_lock(db_path: Path) -> tuple[str, threading.RLock]:
    db_key = str(db_path.resolve())
    with _HISTORY_AUTHORITY_THREAD_LOCKS_GUARD:
        return db_key, _HISTORY_AUTHORITY_THREAD_LOCKS.setdefault(
            db_key, threading.RLock()
        )


