@contextmanager
def _history_authority_fence(db_path: Path) -> Generator[None, None, None]:
    """Serialize history authority changes and egress across threads and processes."""
    db_key, thread_lock = _history_authority_thread_lock(db_path)
    lock_path = Path(f"{db_key}.history-authority.lock")
    deadline = time.monotonic() + HISTORY_AUTHORITY_FENCE_TIMEOUT_SECONDS
    if not thread_lock.acquire(timeout=HISTORY_AUTHORITY_FENCE_TIMEOUT_SECONDS):
        raise TimeoutError("timed out waiting for the history authority fence")

    entries = _history_authority_local_entries()
    nested = entries.get(db_key)
    if nested is not None:
        nested["depth"] += 1
        try:
            yield
        finally:
            nested["depth"] -= 1
            thread_lock.release()
        return

    fd = -1
    file_locked = False
    try:
        flags = os.O_RDWR | os.O_CREAT
        flags |= getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        try:
            fd = os.open(lock_path, flags, 0o600)
            _HISTORY_AUTHORITY_OPEN_FDS.add(fd)
            os.fchmod(fd, 0o600)
        except OSError as exc:
            raise RuntimeError("could not open the history authority fence") from exc

        while True:
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                file_locked = True
                break
            except OSError as exc:
                if exc.errno == errno.EINTR:
                    continue
                if exc.errno not in (errno.EACCES, errno.EAGAIN):
                    raise RuntimeError("could not acquire the history authority fence") from exc
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise TimeoutError("timed out waiting for the history authority fence") from exc
                time.sleep(min(HISTORY_AUTHORITY_FENCE_POLL_SECONDS, remaining))

        entries[db_key] = {"depth": 1, "egress_depth": 0, "fd": fd}
        yield
    finally:
        body_failed = sys.exc_info()[0] is not None
        entries.pop(db_key, None)
        cleanup_error: OSError | None = None
        if file_locked and fd >= 0:
            try:
                fcntl.flock(fd, fcntl.LOCK_UN)
            except OSError as exc:
                cleanup_error = exc
        if fd >= 0:
            try:
                os.close(fd)
            except OSError as exc:
                cleanup_error = cleanup_error or exc
            finally:
                _HISTORY_AUTHORITY_OPEN_FDS.discard(fd)
        thread_lock.release()
        if cleanup_error is not None and not body_failed:
            raise RuntimeError("could not release the history authority fence") from cleanup_error


