@contextmanager
def _goal_source_authority_fence(db_path: Path) -> Generator[None, None, None]:
    """Serialize goal mutations with source-bound publication effects."""
    db_key, thread_lock = _goal_source_authority_thread_lock(db_path)
    lock_path = Path(f"{db_key}.goal-source-authority.lock")
