@contextmanager
def _profile_memory_ownership_fence(db_path: Path) -> Generator[None, None, None]:
    """Serialize durable profile ownership changes and remote egress checks."""
    db_key, thread_lock = _profile_ownership_thread_lock(db_path)
    lock_path = Path(f"{db_key}.profile-ownership.lock")
    thread_lock.acquire()

    entries = _profile_ownership_local_entries()
    nested = entries.get(db_key)
    if nested is not None:
        nested["depth"] += 1
        try:
            yield
        finally:
            nested["depth"] -= 1
            thread_lock.release()
        return

    fd = -1
    file_locked = False
    try:
        flags = os.O_RDWR | os.O_CREAT
        flags |= getattr(os, "O_CLOEXEC", 0)
        nofollow = getattr(os, "O_NOFOLLOW", 0)
        flags |= nofollow
        try:
            if not nofollow and lock_path.is_symlink():
                raise OSError(errno.ELOOP, "symbolic link refused", str(lock_path))
            fd = os.open(lock_path, flags, 0o600)
            _PROFILE_OWNERSHIP_OPEN_FDS.add(fd)
            os.fchmod(fd, 0o600)
        except OSError as exc:
            raise RuntimeError("could not open the profile ownership fence") from exc

        while True:
            try:
                fcntl.flock(fd, fcntl.LOCK_EX)
                file_locked = True
                break
            except OSError as exc:
                if exc.errno != errno.EINTR:
                    raise RuntimeError(
                        "could not acquire the profile ownership fence"
                    ) from exc

        entries[db_key] = {"depth": 1, "fd": fd}
        yield
    finally:
        body_failed = sys.exc_info()[0] is not None
        entries.pop(db_key, None)
        cleanup_error: OSError | None = None
        if file_locked and fd >= 0:
            try:
                fcntl.flock(fd, fcntl.LOCK_UN)
            except OSError as exc:
                cleanup_error = exc
        if fd >= 0:
            try:
                os.close(fd)
            except OSError as exc:
                cleanup_error = cleanup_error or exc
            finally:
                _PROFILE_OWNERSHIP_OPEN_FDS.discard(fd)
        thread_lock.release()
        if cleanup_error is not None and not body_failed:
            raise RuntimeError("could not release the profile ownership fence") from cleanup_error


def _bounded_fts_query(value: object) -> str:
    """Normalize and cap input before it reaches SQLite FTS."""
    try:
        text = str(value or "").strip()
    except Exception:
        return ""
    return re.sub(r"\s+", " ", text)[:MAX_FTS_QUERY_CHARS].strip()


def _literal_fts_query(value: object) -> str:
    """Turn malformed FTS syntax into a bounded literal phrase query."""
    text = _bounded_fts_query(value)
    if not text:
        return ""
    return '"' + text.replace('"', '""') + '"'


def utc_now() -> str:
    return datetime.utcnow().replace(microsecond=0).isoformat() + "Z"


def _task_completion_text_is_visible(value: str) -> bool:
    try:
        value.encode("utf-8", errors="strict")
        normalized = unicodedata.normalize("NFKC", value)
    except UnicodeError:
        return False
    allowed_controls = {"\t", "\r", "\n"}
    for text in (value, normalized):
        for char in text:
            category = unicodedata.category(char)
            if category in {"Cf", "Cs", "Zl", "Zp"} or (
                category == "Cc" and char not in allowed_controls
            ):
                return False
    return any(
        not char.isspace()
        and unicodedata.category(char) not in {"Cc", "Cf", "Cs", "Zl", "Zp"}
        for char in normalized
    )


def _task_completion_run_metadata(row: Any) -> dict[str, Any]:
    try:
        value = json.loads(str(row["metadata"] or "{}"))
    except (KeyError, TypeError, ValueError, json.JSONDecodeError):
        return {}
    return value if isinstance(value, dict) else {}


def _task_completion_run_approval_ids(row: Any) -> tuple[int, ...]:
    candidates: list[Any] = []
    try:
        candidates.append(row["approval_id"])
    except (KeyError, TypeError, IndexError):
        pass
    metadata = _task_completion_run_metadata(row)
    candidates.append(metadata.get("approval_id"))
    try:
        output = str(row["output"] or "")
    except (KeyError, TypeError, IndexError):
        output = ""
    candidates.extend(
        match.group(1)
        for match in re.finditer(
            r"\b(?:queued\s+as\s+)?approval(?:\s+id)?\s*#?\s*(\d+)\b",
            output,
            re.IGNORECASE,
        )
    )
    result: list[int] = []
    for candidate in candidates:
        if isinstance(candidate, bool):
            continue
        try:
            approval_id = int(candidate)
        except (TypeError, ValueError):
            continue
        if 0 < approval_id <= 9223372036854775807 and approval_id not in result:
            result.append(approval_id)
    return tuple(result)


def _task_completion_recovery_proof_fence(rows: Iterable[Any]) -> str:
    payload = [
        {
            "id": int(row["id"]),
            "tool_name": str(row["tool_name"]),
            "ok": int(row["ok"]),
            "metadata": str(row["metadata"] or ""),
        }
        for row in rows
    ]
    return hashlib.sha256(
        json.dumps(
            payload,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("ascii")
    ).hexdigest()


def _task_completion_evidence_digest(
    evidence: str,
    verification_run_id: str,
) -> str:
    return hashlib.sha256(
        json.dumps(
            {
                "evidence": evidence,
                "verification_run_id": verification_run_id,
            },
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _task_completion_body_digest(task_body: str) -> str:
    return hashlib.sha256(task_body.encode("utf-8")).hexdigest()


def _prepare_task_completion_evidence_schema(conn: sqlite3.Connection) -> None:
    columns = tuple(
        str(row["name"])
        for row in conn.execute("PRAGMA table_info(task_completion_evidence)")
    )
    current_columns = (
        "id",
        "task_id",
        "task_body",
        "task_body_digest",
        "evidence",
        "verification_run_id",
        "evidence_digest",
        "created_at",
    )
    if not columns:
        conn.execute(TASK_COMPLETION_EVIDENCE_TABLE_SQL)
        return
    if columns == current_columns:
        return
    legacy_columns = (
        "id",
        "task_id",
        "evidence",
        "verification_run_id",
        "evidence_digest",
        "created_at",
    )
    if columns != legacy_columns:
        raise RuntimeError("task completion evidence schema is incompatible")
    indexes = list(conn.execute("PRAGMA index_list(task_completion_evidence)"))
    unique_indexes = [row for row in indexes if int(row["unique"]) == 1]
    unique_columns = {
        tuple(
            str(column["name"])
            for column in conn.execute(f'PRAGMA index_info("{str(row["name"]).replace(chr(34), chr(34) * 2)}")')
        )
        for row in unique_indexes
    }
    if unique_columns != {("task_id", "evidence_digest")}:
        raise RuntimeError("task completion evidence legacy schema is incompatible")
    legacy_rows = list(
        conn.execute(
            "SELECT evidence.id, evidence.task_id, tasks.body AS task_body, "
            "evidence.evidence, evidence.verification_run_id, "
            "evidence.evidence_digest, evidence.created_at "
            "FROM task_completion_evidence AS evidence "
            "JOIN tasks ON tasks.id = evidence.task_id ORDER BY evidence.id"
        )
    )
    row_count = int(
        conn.execute("SELECT COUNT(*) FROM task_completion_evidence").fetchone()[0]
    )
    if len(legacy_rows) != row_count:
        raise RuntimeError("task completion evidence legacy ownership is incompatible")
    for row in legacy_rows:
        evidence = row["evidence"]
        verification_run_id = row["verification_run_id"]
        task_body = row["task_body"]
        if (
            type(task_body) is not str
            or type(evidence) is not str
            or type(verification_run_id) is not str
            or (not evidence and not verification_run_id)
            or (evidence and not _task_completion_text_is_visible(evidence))
            or (
                verification_run_id
                and not _task_completion_text_is_visible(verification_run_id)
            )
            or len(evidence) > MAX_TASK_COMPLETION_EVIDENCE_CHARS
            or len(verification_run_id) > MAX_TASK_COMPLETION_RUN_ID_CHARS
            or row["evidence_digest"]
            != _task_completion_evidence_digest(evidence, verification_run_id)
        ):
            raise RuntimeError("task completion evidence legacy data is incompatible")
    conn.execute("DROP TRIGGER IF EXISTS task_completion_evidence_immutable_update")
    conn.execute("DROP TRIGGER IF EXISTS task_completion_evidence_immutable_delete")
    conn.execute("DROP INDEX IF EXISTS task_completion_evidence_task_created_idx")
    conn.execute(
        "ALTER TABLE task_completion_evidence "
        "RENAME TO task_completion_evidence_legacy_v1"
    )
    conn.execute(TASK_COMPLETION_EVIDENCE_TABLE_SQL)
    for row in legacy_rows:
        conn.execute(
            "INSERT INTO task_completion_evidence("
            "id, task_id, task_body, task_body_digest, evidence, "
            "verification_run_id, evidence_digest, created_at"
            ") VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            (
                row["id"],
                row["task_id"],
                row["task_body"],
                _task_completion_body_digest(row["task_body"]),
                row["evidence"],
                row["verification_run_id"],
                row["evidence_digest"],
                row["created_at"],
            ),
        )
    conn.execute("DROP TABLE task_completion_evidence_legacy_v1")


def _validate_task_completion_evidence_schema(conn: sqlite3.Connection) -> None:
    expected_columns = (
        ("id", "INTEGER", 0, None, 1),
        ("task_id", "INTEGER", 1, None, 0),
        ("task_body", "TEXT", 1, None, 0),
        ("task_body_digest", "TEXT", 1, None, 0),
        ("evidence", "TEXT", 1, "''", 0),
        ("verification_run_id", "TEXT", 1, "''", 0),
        ("evidence_digest", "TEXT", 1, None, 0),
        ("created_at", "TEXT", 1, None, 0),
    )
    actual_columns = tuple(
        (
            str(row["name"]),
            str(row["type"]),
            int(row["notnull"]),
            row["dflt_value"],
            int(row["pk"]),
        )
        for row in conn.execute("PRAGMA table_info(task_completion_evidence)")
    )
    if actual_columns != expected_columns:
        raise RuntimeError("task completion evidence schema is incompatible")
    foreign_keys = tuple(
        (
            str(row["table"]),
            str(row["from"]),
            str(row["to"]),
            str(row["on_delete"]),
        )
        for row in conn.execute("PRAGMA foreign_key_list(task_completion_evidence)")
    )
    if foreign_keys != (("tasks", "task_id", "id", "RESTRICT"),):
        raise RuntimeError("task completion evidence ownership schema is incompatible")
    indexes = list(conn.execute("PRAGMA index_list(task_completion_evidence)"))
    if any(int(row["unique"]) != 0 for row in indexes):
        raise RuntimeError("task completion evidence must remain an append-only event ledger")
    index_row = next(
        (
            row
            for row in indexes
            if row["name"] == "task_completion_evidence_task_created_idx"
        ),
        None,
    )
    if index_row is None:
        raise RuntimeError("task completion evidence index is missing")
    index_columns = tuple(
        str(row["name"])
        for row in conn.execute(
            "PRAGMA index_info(task_completion_evidence_task_created_idx)"
        )
    )
    if index_columns != ("task_id", "created_at", "id"):
        raise RuntimeError("task completion evidence index is incompatible")
    table_row = conn.execute(
        "SELECT sql FROM sqlite_master WHERE type = 'table' "
        "AND name = 'task_completion_evidence'"
    ).fetchone()
    normalized_sql = re.sub(r"\s+", "", str(table_row["sql"] if table_row else "").lower())
    required_markers = (
        "length(evidence)<=800",
        "length(verification_run_id)<=80",
        "length(task_body_digest)=64",
        "task_body_digestnotglob'*[^0-9a-f]*'",
        "length(evidence_digest)=64",
        "evidence_digestnotglob'*[^0-9a-f]*'",
        "length(evidence)>0orlength(verification_run_id)>0",
    )
    if any(marker not in normalized_sql for marker in required_markers):
        raise RuntimeError("task completion evidence constraints are incompatible")
    trigger_names = {
        str(row["name"])
        for row in conn.execute(
            "SELECT name FROM sqlite_master WHERE type = 'trigger' "
            "AND tbl_name = 'task_completion_evidence'"
        )
    }
    if trigger_names != {
        "task_completion_evidence_immutable_update",
        "task_completion_evidence_immutable_delete",
    }:
        raise RuntimeError("task completion evidence immutability guards are incompatible")


def _person_projection_completed_audit_tail_time(conn: sqlite3.Connection) -> str:
    row = conn.execute(
        "SELECT updated_at AS tail FROM person_projection_jobs "
        "WHERE state = 'completed' ORDER BY updated_at DESC, person_id DESC LIMIT 1"
    ).fetchone()
    now = datetime.utcnow().replace(microsecond=0)
    try:
        tail = datetime.fromisoformat(str(row["tail"] or "").removesuffix("Z"))
    except (TypeError, ValueError):
        tail = now - timedelta(seconds=1)
    return max(now, tail + timedelta(seconds=1)).isoformat() + "Z"


def _goal_projection_completed_audit_tail_time(conn: sqlite3.Connection) -> str:
    row = conn.execute(
        "SELECT updated_at AS tail FROM goal_projection_jobs "
        "WHERE state = 'completed' AND updated_at GLOB "
        "'[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]"
        "T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' "
        "ORDER BY updated_at DESC, goal_id DESC LIMIT 1"
    ).fetchone()
    now = datetime.utcnow().replace(microsecond=0)
    try:
        tail = datetime.fromisoformat(str(row["tail"] or "").removesuffix("Z"))
        next_tail = tail + timedelta(seconds=1)
    except (OverflowError, TypeError, ValueError):
        tail = now - timedelta(seconds=1)
        next_tail = now
    return max(now, next_tail).isoformat() + "Z"


