def bootstrap_memory_occurrence_source_key(
    record: MemoryRecord,
    duplicate_ordinal: int,
) -> str:
    """Derive the content-addressed key enforced by bootstrap custody."""
    if not isinstance(record, MemoryRecord):
        raise TypeError("bootstrap memory record is invalid")
    if type(duplicate_ordinal) is not int:
        raise TypeError("bootstrap duplicate ordinal must be an integer")
    if duplicate_ordinal < 0:
        raise ValueError("bootstrap duplicate ordinal must not be negative")
    if any(
        type(value) is not str
        for value in (record.category, record.title, record.body, record.source)
    ):
        raise ValueError("bootstrap memory fields must be strings")
    if (
        isinstance(record.confidence, bool)
        or not isinstance(record.confidence, (int, float))
        or not math.isfinite(float(record.confidence))
    ):
        raise ValueError("bootstrap memory confidence must be finite")
    payload = json.dumps(
        {
            "body": record.body,
            "category": record.category,
            "confidence": record.confidence,
            "duplicate_ordinal": duplicate_ordinal,
            "source": record.source,
            "title": record.title,
        },
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    ).encode("utf-8")
    return BOOTSTRAP_MEMORY_SOURCE_KEY_PREFIX + hashlib.sha256(payload).hexdigest()


