def _subagent_ephemeral_fields(row: sqlite3.Row) -> dict[str, Any]:
    return {
        "task_id": str(row["task_id"]),
        "state": str(row["state"]),
        "request_digest": str(row["request_digest"]),
        "kind": str(row["kind"]),
        "priority": int(row["priority"]),
        "replay_policy": str(row["replay_policy"]),
        "max_attempts": int(row["max_attempts"]),
        "result_digest": str(row["result_digest"] or ""),
        "result_type": str(row["result_type"] or ""),
        "error_code": str(row["error_code"] or ""),
        "result_state": str(row["result_state"]),
        "result_expires_ms": (
            int(row["result_expires_ms"]) if row["result_expires_ms"] is not None else None
        ),
        "result_released_ms": (
            int(row["result_released_ms"]) if row["result_released_ms"] is not None else None
        ),
    }


def _subagent_ephemeral_status(
    status: str,
    row: sqlite3.Row,
) -> SubagentTaskEphemeralStatus:
    return SubagentTaskEphemeralStatus(status=status, **_subagent_ephemeral_fields(row))


def _subagent_result_transition(
    status: str,
    row: sqlite3.Row,
) -> SubagentResultRetentionTransition:
    return SubagentResultRetentionTransition(status=status, **_subagent_ephemeral_fields(row))


def _subagent_result_identity_matches(
    row: sqlite3.Row,
    request_digest: str,
    result_digest: str,
) -> bool:
    return row["request_digest"] == request_digest and row["result_digest"] == result_digest


