    def get_skill_by_id(self, skill_id: int) -> sqlite3.Row | None:
        skill_id = _skill_projection_positive_int(skill_id, field="skill id")
        with self.connect() as conn:
            return conn.execute(
                "SELECT * FROM skills WHERE id = ?", (skill_id,)
            ).fetchone()

    def get_skill_by_identity(self, name: str) -> sqlite3.Row | None:
        with self.connect() as conn:
            matches = self._skill_identity_matches(conn, name)
        if len(matches) > 1:
            raise ValueError("skill name identity is ambiguous")
        return matches[0] if matches else None

    def resolve_skill_delete_target(self, query: str) -> SkillDeleteResolution:
        """Resolve a user query to an immutable skill identity without choosing among ties."""
        if not isinstance(query, str):
            raise TypeError("skill deletion query must be a string")
        query = query.strip()

        with self.connect() as conn:
            exact_row = conn.execute(
                "SELECT id, revision, name FROM skills WHERE name = ?",
                (query,),
            ).fetchone()
            if exact_row is not None:
                return SkillDeleteResolution(
                    status="resolved",
                    skill_id=int(exact_row["id"]),
                    revision=int(exact_row["revision"]),
                    name=str(exact_row["name"]),
                )
            rows = list(conn.execute("SELECT id, revision, name FROM skills ORDER BY id"))

        normalized_query = unicodedata.normalize("NFKC", query.strip()).casefold()
        normalized_rows = [
            (
                unicodedata.normalize("NFKC", str(row["name"]).strip()).casefold(),
                str(row["name"]),
                int(row["id"]),
                int(row["revision"]),
            )
            for row in rows
        ]
        normalized_rows.sort(key=lambda item: (item[0], item[1], item[2]))

        casefold_matches = [item for item in normalized_rows if item[0] == normalized_query]
        if casefold_matches:
            return self._skill_delete_resolution(casefold_matches)
        if not normalized_query:
            return SkillDeleteResolution(status="not_found")

        fuzzy_matches = [item for item in normalized_rows if normalized_query in item[0]]
        if fuzzy_matches:
            return self._skill_delete_resolution(fuzzy_matches)
        return SkillDeleteResolution(status="not_found")

    @staticmethod
    def _skill_delete_resolution(
        matches: list[tuple[str, str, int, int]],
    ) -> SkillDeleteResolution:
        if len(matches) == 1:
            _, name, skill_id, revision = matches[0]
            return SkillDeleteResolution(
                status="resolved",
                skill_id=skill_id,
                revision=revision,
                name=name,
            )
        candidates = tuple(
            SkillDeleteCandidate(skill_id=skill_id, revision=revision, name=name)
            for _, name, skill_id, revision in matches[:MAX_SKILL_DELETE_CANDIDATES]
        )
        return SkillDeleteResolution(status="ambiguous", candidates=candidates)

    def delete_skill_exact(
        self,
        target_skill_id: int,
        target_skill_revision: int,
        target_skill_name: str,
    ) -> SkillDeleteResult:
        """Delete only the exact immutable target produced by the resolver."""
        if (
            isinstance(target_skill_id, bool)
            or not isinstance(target_skill_id, int)
            or target_skill_id < 1
        ):
            raise ValueError("skill id must be a positive integer")
        if (
            isinstance(target_skill_revision, bool)
            or not isinstance(target_skill_revision, int)
            or target_skill_revision < 1
        ):
            raise ValueError("skill revision must be a positive integer")
        if not isinstance(target_skill_name, str):
            raise TypeError("canonical skill name must be a string")

        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                "SELECT * FROM skills WHERE id = ?", (target_skill_id,)
            ).fetchone()
            if row is None:
                return SkillDeleteResult(status="not_found")
            if (
                int(row["revision"]) != target_skill_revision
                or row["name"] != target_skill_name
            ):
                return SkillDeleteResult(status="stale")
            deleted = conn.execute(
                "DELETE FROM skills WHERE id = ? AND revision = ? AND name = ?",
                (target_skill_id, target_skill_revision, target_skill_name),
            )
            if deleted.rowcount != 1:
                return SkillDeleteResult(status="stale")
            self._upsert_skill_projection_job(conn, row, operation="delete", now=utc_now())
            return SkillDeleteResult(status="deleted", deleted_row=row)

    def delete_skill_record(self, name: str) -> sqlite3.Row | None:
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                "SELECT * FROM skills WHERE lower(name) = lower(?)",
                (name,),
            ).fetchone()
            if row is None:
                row = conn.execute(
                    """
                    SELECT * FROM skills
                    WHERE lower(name) LIKE lower(?)
                    ORDER BY updated_at DESC
                    LIMIT 1
                    """,
                    (f"%{name}%",),
                ).fetchone()
            if not row:
                return None
            deleted = conn.execute("DELETE FROM skills WHERE id = ?", (row["id"],))
            if deleted.rowcount != 1:
                return None
            self._upsert_skill_projection_job(conn, row, operation="delete", now=utc_now())
            return row

    def delete_skill(self, name: str) -> bool:
        return self.delete_skill_record(name) is not None

    def upsert_job(self, name: str, interval_minutes: int, job_type: str, next_run_at: str) -> int:
        now = utc_now()
        with self.connect() as conn:
            conn.execute(
                f"""
                INSERT INTO scheduled_jobs(name, interval_minutes, job_type, next_run_at, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?)
                ON CONFLICT(name) DO UPDATE SET
                    interval_minutes=excluded.interval_minutes,
                    job_type=excluded.job_type,
                    next_run_at=excluded.next_run_at,
                    enabled=1,
                    schedule_revision=scheduled_jobs.schedule_revision + 1,
                    schedule_identity_revision={_SCHEDULE_IDENTITY_MUTATION_SQL},
                    updated_at=excluded.updated_at
                """,
                (name, interval_minutes, job_type, next_run_at, now, now),
            )
            row = conn.execute("SELECT id FROM scheduled_jobs WHERE name = ?", (name,)).fetchone()
            return int(row["id"])

    def create_job_if_missing(
        self,
        name: str,
        interval_minutes: int,
        job_type: str,
        next_run_at: str,
    ) -> tuple[sqlite3.Row, bool]:
        """Create one named job without changing any existing operator state."""
        now = utc_now()
        if type(name) is not str or not name:
            raise ValueError("scheduled job name must be a non-empty string")
        name_identity = unicodedata.normalize("NFKC", name).casefold()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            existing_id = None
            for candidate in conn.execute(
                "SELECT id, name FROM scheduled_jobs ORDER BY id"
            ):
                candidate_name = candidate["name"]
                if (
                    type(candidate_name) is str
                    and unicodedata.normalize("NFKC", candidate_name).casefold()
                    == name_identity
                ):
                    existing_id = int(candidate["id"])
                    break
            if existing_id is not None:
                existing = conn.execute(
                    "SELECT * FROM scheduled_jobs WHERE id = ?",
                    (existing_id,),
                ).fetchone()
                if existing is None:
                    raise RuntimeError("scheduled job disappeared during create-only lookup")
                return existing, False
            cursor = conn.execute(
                """
                INSERT INTO scheduled_jobs(
                    name, interval_minutes, job_type, next_run_at, created_at, updated_at
                )
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (name, interval_minutes, job_type, next_run_at, now, now),
            )
            created = conn.execute(
                "SELECT * FROM scheduled_jobs WHERE id = ?",
                (int(cursor.lastrowid),),
            ).fetchone()
            if created is None:
                raise RuntimeError("scheduled job create did not return its committed row")
            return created, True

    def upsert_job_with_metadata(
        self,
        name: str,
        interval_minutes: int,
        job_type: str,
        next_run_at: str,
        metadata_updates: dict[str, Any],
    ) -> sqlite3.Row:
        """Atomically bind a job schedule and its descriptive metadata."""
        if type(metadata_updates) is not dict:
            raise TypeError("scheduled job metadata updates must be a dictionary")
        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            existing = conn.execute(
                "SELECT metadata FROM scheduled_jobs WHERE name = ?",
                (name,),
            ).fetchone()
            try:
                parsed = json.loads(existing["metadata"] or "{}") if existing is not None else {}
            except (TypeError, ValueError, json.JSONDecodeError):
                parsed = {}
            metadata = parsed if isinstance(parsed, dict) else {}
            metadata.update(metadata_updates)
            metadata_json = json.dumps(metadata, sort_keys=True)
            conn.execute(
                f"""
                INSERT INTO scheduled_jobs(
                    name, interval_minutes, job_type, next_run_at, metadata, created_at, updated_at
                )
                VALUES (?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(name) DO UPDATE SET
                    interval_minutes=excluded.interval_minutes,
                    job_type=excluded.job_type,
                    next_run_at=excluded.next_run_at,
                    metadata=excluded.metadata,
                    enabled=1,
                    schedule_revision=scheduled_jobs.schedule_revision + 1,
                    schedule_identity_revision={_SCHEDULE_IDENTITY_MUTATION_SQL},
                    updated_at=excluded.updated_at
                """,
                (name, interval_minutes, job_type, next_run_at, metadata_json, now, now),
            )
            row = conn.execute("SELECT * FROM scheduled_jobs WHERE name = ?", (name,)).fetchone()
            if row is None:
                raise RuntimeError("scheduled job upsert did not return its committed row")
            return row

    def reconcile_job_schedule_if_revision(
        self,
        job_id: int,
        expected_schedule_revision: int,
        interval_minutes: int,
        job_type: str,
        next_run_at: str,
        metadata_updates: dict[str, Any],
        *,
        allow_disabled: bool = False,
    ) -> bool:
        """Refresh one schedule only if concurrent operator intent has not changed it."""
        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                "SELECT enabled, schedule_revision, metadata FROM scheduled_jobs WHERE id = ?",
                (job_id,),
            ).fetchone()
            if row is None or row["schedule_revision"] != expected_schedule_revision:
                return False
            enabled = row["enabled"]
            if isinstance(enabled, int) and not isinstance(enabled, bool) and enabled == 0 and not allow_disabled:
                return False
            try:
                parsed = json.loads(row["metadata"] or "{}")
            except (TypeError, ValueError, json.JSONDecodeError):
                parsed = {}
            metadata = parsed if isinstance(parsed, dict) else {}
            metadata.update(metadata_updates)
            cur = conn.execute(
                f"""
                UPDATE scheduled_jobs
                SET interval_minutes = ?, job_type = ?, next_run_at = ?, metadata = ?,
                    enabled = 1, schedule_revision = schedule_revision + 1,
                    schedule_identity_revision = {_SCHEDULE_IDENTITY_MUTATION_SQL}, updated_at = ?
                WHERE id = ? AND schedule_revision = ?
                """,
                (
                    interval_minutes,
                    job_type,
                    next_run_at,
                    json.dumps(metadata, sort_keys=True),
                    now,
                    job_id,
                    expected_schedule_revision,
                ),
            )
            return cur.rowcount == 1

    def list_jobs(self) -> list[sqlite3.Row]:
        with self.connect() as conn:
            return list(conn.execute("SELECT * FROM scheduled_jobs ORDER BY next_run_at ASC"))

    def due_jobs(self, now: str) -> list[sqlite3.Row]:
        with self.connect() as conn:
            return list(
                conn.execute(
                    "SELECT * FROM scheduled_jobs WHERE enabled = 1 AND next_run_at <= ? ORDER BY next_run_at ASC",
                    (now,),
                )
            )

    @staticmethod
    def _validate_scheduled_delivery_input(
        delivery_key: str,
        occurrence_key: str,
        payload: str,
        payload_sha256: str,
        chunk_index: int,
        chunk_count: int,
    ) -> tuple[str, str, str, str, int, int]:
        if not delivery_key or not occurrence_key:
            raise ValueError("scheduled delivery keys must not be empty")
        if not isinstance(payload, str):
            raise TypeError("scheduled delivery payload must be text")
        try:
            normalized_chunk_index = int(chunk_index)
            normalized_chunk_count = int(chunk_count)
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValueError("scheduled delivery chunk coordinates are invalid") from exc
        if (
            normalized_chunk_index < 0
            or normalized_chunk_count <= 0
            or normalized_chunk_index >= normalized_chunk_count
        ):
            raise ValueError("scheduled delivery chunk coordinates are invalid")
        normalized_sha256 = str(payload_sha256).lower()
        actual_sha256 = hashlib.sha256(payload.encode("utf-8")).hexdigest()
        if normalized_sha256 != actual_sha256:
            raise ValueError("scheduled delivery payload hash mismatch")
        return (
            str(delivery_key),
            str(occurrence_key),
            payload,
            normalized_sha256,
            normalized_chunk_index,
            normalized_chunk_count,
        )

    @staticmethod
    def _validate_scheduled_note_publication_plan(
        plan: dict[str, Any],
    ) -> dict[str, Any]:
        if not isinstance(plan, dict):
            raise TypeError("scheduled note publication plan must be a mapping")
        required = {
            "publication_key",
            "occurrence_key",
            "effect_index",
            "delivery_occurrence_key",
            "source_job_id",
            "job_id",
            "job_name",
            "job_type",
            "target_kind",
            "target_date",
            "title",
            "payload",
            "payload_sha256",
            "allow_disabled",
        }
        if not required.issubset(plan):
            raise ValueError("scheduled note publication plan is missing a required field")

        publication_key = plan["publication_key"]
        occurrence_key = plan["occurrence_key"]
        if (
            type(publication_key) is not str
            or SCHEDULED_NOTE_PUBLICATION_KEY_RE.fullmatch(publication_key) is None
        ):
            raise ValueError("scheduled note publication key is invalid")
        if (
            type(occurrence_key) is not str
            or SCHEDULED_NOTE_OCCURRENCE_KEY_RE.fullmatch(occurrence_key) is None
        ):
            raise ValueError("scheduled note occurrence key is invalid")
        effect_index = plan["effect_index"]
        if type(effect_index) is not int or not 0 <= effect_index <= 31:
            raise ValueError("scheduled note effect index is invalid")

        delivery_occurrence_key = plan["delivery_occurrence_key"]
        if delivery_occurrence_key in (None, ""):
            delivery_occurrence_key = None
        elif (
            type(delivery_occurrence_key) is not str
            or len(delivery_occurrence_key) > MAX_SCHEDULED_NOTE_IDENTITY_CHARS
            or SCHEDULED_JOB_RUN_OCCURRENCE_RE.fullmatch(delivery_occurrence_key) is None
        ):
            raise ValueError("scheduled note delivery occurrence key is invalid")

        source_job_id = plan["source_job_id"]
        job_id = plan["job_id"]
        if (
            type(source_job_id) is not int
            or source_job_id <= 0
            or type(job_id) is not int
            or job_id != source_job_id
        ):
            raise ValueError("scheduled note source job identity is invalid")
        job_name = plan["job_name"]
        job_type = plan["job_type"]
        if any(
            type(value) is not str
            or not value
            or value != value.strip()
            or "\x00" in value
            or len(value) > MAX_SCHEDULED_NOTE_IDENTITY_CHARS
            for value in (job_name, job_type)
        ):
            raise ValueError("scheduled note source job identity is invalid")
        if SCHEDULED_JOB_TYPE_RE.fullmatch(job_type) is None:
            raise ValueError("scheduled note source job type is invalid")

        target_kind = plan["target_kind"]
        if target_kind not in {"daily", "reflection"}:
            raise ValueError("scheduled note target kind is invalid")
        target_date = plan["target_date"]
        if type(target_date) is not str or len(target_date) != 10:
            raise ValueError("scheduled note target date is invalid")
        try:
            if datetime.fromisoformat(target_date).date().isoformat() != target_date:
                raise ValueError
        except (TypeError, ValueError) as exc:
            raise ValueError("scheduled note target date is invalid") from exc

        title = plan["title"]
        payload = plan["payload"]
        if (
            type(title) is not str
            or not title
            or title != title.strip()
            or "\x00" in title
            or len(title) > 200
        ):
            raise ValueError("scheduled note title is invalid")
        if (
            type(payload) is not str
            or not payload
            or "\x00" in payload
            or len(payload) > MAX_SCHEDULED_NOTE_PAYLOAD_CHARS
        ):
            raise ValueError("scheduled note payload is invalid")
        payload_sha256 = plan["payload_sha256"]
        actual_sha256 = hashlib.sha256(payload.encode("utf-8")).hexdigest()
        if (
            type(payload_sha256) is not str
            or SCHEDULED_NOTE_PUBLICATION_KEY_RE.fullmatch(payload_sha256) is None
            or not secrets.compare_digest(payload_sha256, actual_sha256)
        ):
            raise ValueError("scheduled note payload hash mismatch")

        source_manifest_kind = plan.get("source_manifest_kind", "")
        source_manifest_digest = plan.get("source_manifest_digest", "")
        if (
            type(source_manifest_kind) is not str
            or type(source_manifest_digest) is not str
            or bool(source_manifest_kind) != bool(source_manifest_digest)
        ):
            raise ValueError("scheduled note source manifest is invalid")
        has_valid_goal_nudge_manifest = (
            source_manifest_kind == GOAL_NUDGE_SOURCE_MANIFEST_KIND
            and SCHEDULED_NOTE_PUBLICATION_KEY_RE.fullmatch(source_manifest_digest)
            is not None
        )
        if (job_type == "goal_nudge") != has_valid_goal_nudge_manifest:
            raise ValueError("scheduled note source manifest is invalid")

        allow_disabled = plan["allow_disabled"]
        if type(allow_disabled) is bool:
            normalized_allow_disabled = int(allow_disabled)
        elif type(allow_disabled) is int and allow_disabled in (0, 1):
            normalized_allow_disabled = allow_disabled
        else:
            raise ValueError("scheduled note disabled-job policy is invalid")
        return {
            "publication_key": publication_key,
            "occurrence_key": occurrence_key,
            "effect_index": effect_index,
            "delivery_occurrence_key": delivery_occurrence_key,
            "source_job_id": source_job_id,
            "job_id": job_id,
            "job_name": job_name,
            "job_type": job_type,
            "target_kind": target_kind,
            "target_date": target_date,
            "title": title,
            "payload": payload,
            "payload_sha256": payload_sha256,
            "source_manifest_kind": source_manifest_kind,
            "source_manifest_digest": source_manifest_digest,
            "allow_disabled": normalized_allow_disabled,
        }

    @classmethod
    def _validate_scheduled_note_publication_plans(
        cls,
        plans: list[dict[str, Any]] | None,
    ) -> list[dict[str, Any]]:
        if plans is None:
            return []
        if type(plans) is not list:
            raise TypeError("scheduled note publication plans must be a list")
        if len(plans) > 32:
            raise ValueError("scheduled note publication plan has too many effects")
        normalized = [cls._validate_scheduled_note_publication_plan(plan) for plan in plans]
        if (
            len({plan["publication_key"] for plan in normalized}) != len(normalized)
            or len({(plan["occurrence_key"], plan["effect_index"]) for plan in normalized})
            != len(normalized)
        ):
            raise ValueError("scheduled note publication plan contains duplicate effects")
        return normalized

    @staticmethod
    def _prepare_scheduled_note_publication_on_connection(
        conn: sqlite3.Connection,
        plan: dict[str, Any],
        *,
        now: str,
    ) -> sqlite3.Row:
        existing = conn.execute(
            """
            SELECT * FROM scheduled_note_publications
            WHERE publication_key = ?
               OR (occurrence_key = ? AND effect_index = ?)
            LIMIT 1
            """,
            (plan["publication_key"], plan["occurrence_key"], plan["effect_index"]),
        ).fetchone()
        if existing is not None:
            same_identity = (
                existing["publication_key"] == plan["publication_key"]
                and existing["occurrence_key"] == plan["occurrence_key"]
                and int(existing["effect_index"]) == plan["effect_index"]
                and existing["delivery_occurrence_key"] == plan["delivery_occurrence_key"]
                and existing["job_id"] is not None
                and int(existing["job_id"]) == plan["job_id"]
                and int(existing["source_job_id"]) == plan["source_job_id"]
                and existing["job_name"] == plan["job_name"]
                and existing["job_type"] == plan["job_type"]
                and existing["target_kind"] == plan["target_kind"]
                and existing["target_date"] == plan["target_date"]
                and existing["title"] == plan["title"]
                and existing["payload_sha256"] == plan["payload_sha256"]
                and existing["source_manifest_kind"] == plan["source_manifest_kind"]
                and existing["source_manifest_digest"] == plan["source_manifest_digest"]
                and int(existing["allow_disabled"]) == plan["allow_disabled"]
                and (existing["payload"] is None or existing["payload"] == plan["payload"])
            )
            if not same_identity:
                raise ValueError("scheduled note publication key collision")
            return existing

        occurrence = conn.execute(
            """
            SELECT source_job_id, job_name, job_type, delivery_occurrence_key,
                   source_manifest_kind, source_manifest_digest, allow_disabled
            FROM scheduled_note_publications
            WHERE occurrence_key = ?
            LIMIT 1
            """,
            (plan["occurrence_key"],),
        ).fetchone()
        if occurrence is not None and (
            int(occurrence["source_job_id"]) != plan["source_job_id"]
            or occurrence["job_name"] != plan["job_name"]
            or occurrence["job_type"] != plan["job_type"]
            or occurrence["delivery_occurrence_key"] != plan["delivery_occurrence_key"]
            or occurrence["source_manifest_kind"] != plan["source_manifest_kind"]
            or occurrence["source_manifest_digest"] != plan["source_manifest_digest"]
            or int(occurrence["allow_disabled"]) != plan["allow_disabled"]
        ):
            raise ValueError("scheduled note publication occurrence collision")

        conn.execute(
            """
            INSERT INTO scheduled_note_publications(
                publication_key, occurrence_key, effect_index, delivery_occurrence_key,
                job_id, source_job_id, job_name, job_type, target_kind, target_date,
                title, payload, payload_sha256, source_manifest_kind,
                source_manifest_digest, state, allow_disabled, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'prepared', ?, ?, ?)
            """,
            (
                plan["publication_key"],
                plan["occurrence_key"],
                plan["effect_index"],
                plan["delivery_occurrence_key"],
                plan["job_id"],
                plan["source_job_id"],
                plan["job_name"],
                plan["job_type"],
                plan["target_kind"],
                plan["target_date"],
                plan["title"],
                plan["payload"],
                plan["payload_sha256"],
                plan["source_manifest_kind"],
                plan["source_manifest_digest"],
                plan["allow_disabled"],
                now,
                now,
            ),
        )
        row = conn.execute(
            "SELECT * FROM scheduled_note_publications WHERE publication_key = ?",
            (plan["publication_key"],),
        ).fetchone()
        if row is None:
            raise RuntimeError("scheduled note publication insert was lost")
        return row

    @staticmethod
    def _prepare_scheduled_delivery_on_connection(
        conn: sqlite3.Connection,
        *,
        delivery_key: str,
        occurrence_key: str,
        chunk_index: int,
        chunk_count: int,
        job_id: int,
        job_name: str,
        job_type: str,
        payload: str,
        payload_sha256: str,
        now: str,
    ) -> sqlite3.Row:
        existing = conn.execute(
            """
            SELECT * FROM scheduled_deliveries
            WHERE delivery_key = ?
               OR (occurrence_key = ? AND chunk_index = ?)
            LIMIT 1
            """,
            (delivery_key, occurrence_key, chunk_index),
        ).fetchone()
        if existing is not None:
            same_identity = (
                existing["delivery_key"] == delivery_key
                and existing["occurrence_key"] == occurrence_key
                and int(existing["chunk_index"]) == chunk_index
                and int(existing["chunk_count"]) == chunk_count
                and int(existing["source_job_id"]) == job_id
                and existing["job_name"] == job_name
                and existing["job_type"] == job_type
                and existing["payload_sha256"] == payload_sha256
                and (existing["payload"] is None or existing["payload"] == payload)
            )
            if not same_identity:
                raise ValueError("scheduled delivery key collision")
            return existing

        occurrence = conn.execute(
            """
            SELECT source_job_id, job_name, job_type, chunk_count
            FROM scheduled_deliveries
            WHERE occurrence_key = ?
            LIMIT 1
            """,
            (occurrence_key,),
        ).fetchone()
        if occurrence is not None and (
            int(occurrence["source_job_id"]) != job_id
            or occurrence["job_name"] != job_name
            or occurrence["job_type"] != job_type
            or int(occurrence["chunk_count"]) != chunk_count
        ):
            raise ValueError("scheduled delivery occurrence collision")

        conn.execute(
            """
            INSERT INTO scheduled_deliveries(
                delivery_key, occurrence_key, chunk_index, chunk_count,
                job_id, source_job_id, job_name, job_type, payload,
                payload_sha256, state, next_attempt_at, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'prepared', ?, ?, ?)
            """,
            (
                delivery_key,
                occurrence_key,
                chunk_index,
                chunk_count,
                job_id,
                job_id,
                job_name,
                job_type,
                payload,
                payload_sha256,
                now,
                now,
                now,
            ),
        )
        row = conn.execute(
            "SELECT * FROM scheduled_deliveries WHERE delivery_key = ?",
            (delivery_key,),
        ).fetchone()
        if row is None:
            raise RuntimeError("scheduled delivery insert was lost")
        return row

    def prepare_scheduled_delivery(
        self,
        delivery_key: str,
        job_id: int,
        job_name: str,
        job_type: str,
        payload: str,
        payload_sha256: str,
        *,
        occurrence_key: str | None = None,
        chunk_index: int = 0,
        chunk_count: int = 1,
    ) -> sqlite3.Row:
        """Create one Telegram API-call ledger row or return its exact match.

        Chunk indexes are zero-based. A reused delivery key or occurrence/chunk
        coordinate must match the immutable job, chunk, payload, and hash identity.
        """
        resolved_occurrence_key = occurrence_key if occurrence_key is not None else delivery_key
        if not job_name or not job_type or not payload_sha256:
            raise ValueError("scheduled delivery identity fields must not be empty")
        (
            delivery_key,
            resolved_occurrence_key,
            payload,
            payload_sha256,
            chunk_index,
            chunk_count,
        ) = self._validate_scheduled_delivery_input(
            delivery_key,
            resolved_occurrence_key,
            payload,
            payload_sha256,
            chunk_index,
            chunk_count,
        )
        if chunk_count != 1 or chunk_index != 0:
            raise ValueError("multi-chunk occurrences must be prepared atomically")
        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            return self._prepare_scheduled_delivery_on_connection(
                conn,
                delivery_key=delivery_key,
                occurrence_key=resolved_occurrence_key,
                chunk_index=chunk_index,
                chunk_count=chunk_count,
                job_id=int(job_id),
                job_name=job_name,
                job_type=job_type,
                payload=payload,
                payload_sha256=payload_sha256,
                now=now,
            )

    def prepare_scheduled_delivery_occurrence(
        self,
        job_id: int,
        job_name: str,
        job_type: str,
        occurrence_key: str,
        chunks: list[dict[str, Any]],
    ) -> list[sqlite3.Row]:
        """Prepare a complete occurrence atomically without advancing a job lease."""
        if not job_name or not job_type or not occurrence_key or not chunks:
            raise ValueError("scheduled delivery occurrence identity must be complete")
        if len(chunks) > MAX_SCHEDULED_DELIVERY_CHUNKS:
            raise ValueError("scheduled delivery occurrence has too many chunks")
        normalized: list[tuple[str, str, str, str, int, int]] = []
        for chunk in chunks:
            if not isinstance(chunk, dict):
                raise TypeError("scheduled delivery chunks must be mappings")
            try:
                normalized.append(
                    self._validate_scheduled_delivery_input(
                        chunk["delivery_key"],
                        occurrence_key,
                        chunk["payload"],
                        chunk["payload_sha256"],
                        chunk["chunk_index"],
                        chunk["chunk_count"],
                    )
                )
            except KeyError as exc:
                raise ValueError("scheduled delivery chunk is missing a required field") from exc
        chunk_counts = {item[5] for item in normalized}
        chunk_indexes = {item[4] for item in normalized}
        if (
            len(chunk_counts) != 1
            or next(iter(chunk_counts)) != len(normalized)
            or chunk_indexes != set(range(len(normalized)))
            or len({item[0] for item in normalized}) != len(normalized)
        ):
            raise ValueError("scheduled delivery occurrence chunk set is incomplete")
        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            rows: list[sqlite3.Row] = []
            for delivery_key, resolved_occurrence, payload, payload_sha256, index, count in normalized:
                rows.append(
                    self._prepare_scheduled_delivery_on_connection(
                        conn,
                        delivery_key=delivery_key,
                        occurrence_key=resolved_occurrence,
                        chunk_index=index,
                        chunk_count=count,
                        job_id=int(job_id),
                        job_name=job_name,
                        job_type=job_type,
                        payload=payload,
                        payload_sha256=payload_sha256,
                        now=now,
                    )
                )
            return rows

    def complete_claimed_job_with_scheduled_deliveries(
        self,
        job_id: int,
        lease_token: str,
        last_run_at: str,
        next_run_at: str,
        occurrence_key: str,
        chunks: list[dict[str, Any]],
        source_job_name: str,
        source_job_type: str,
        expected_schedule_revision: int,
        now: datetime | None = None,
        *,
        run_history_event: dict[str, Any] | None = None,
        expected_occurrence_key: str | None = None,
        scheduled_note_publications: list[dict[str, Any]] | None = None,
    ) -> bool:
        """Enqueue one claimed occurrence without overwriting a newer schedule.

        The outbox keeps the claimed definition's identity even when the job is
        reconfigured while its handler is running.
        """
        if not lease_token or not occurrence_key or not source_job_name or not source_job_type:
            raise ValueError("job lease token, occurrence key, and source identity must not be empty")
        if not chunks or len(chunks) > MAX_SCHEDULED_DELIVERY_CHUNKS:
            raise ValueError("scheduled delivery occurrence must contain chunks")
        normalized_run_event = None
        if run_history_event is not None:
            normalized_run_event = _scheduled_job_run_event(run_history_event)
            if normalized_run_event["occurrence_key"] != occurrence_key:
                raise ValueError("scheduled delivery and run-history occurrence identities differ")
            if normalized_run_event["job_type"] != source_job_type:
                raise ValueError("scheduled delivery and run-history types differ")
        if expected_occurrence_key is not None:
            if occurrence_key.startswith("morning:"):
                delivery_identity_matches = (
                    source_job_type == MORNING_BRIEF_SCHEDULED_JOB_TYPE
                    and re.fullmatch(r"morning:[0-9a-f]{32}", occurrence_key) is not None
                )
            else:
                delivery_identity_matches = occurrence_key == f"scheduled:{expected_occurrence_key}"
            if not delivery_identity_matches:
                raise ValueError("scheduled delivery occurrence does not match the claimed occurrence")

        normalized_note_plans = self._validate_scheduled_note_publication_plans(
            scheduled_note_publications
        )
        for plan in normalized_note_plans:
            if (
                expected_occurrence_key is None
                or plan["occurrence_key"] != expected_occurrence_key
                or plan["source_job_id"] != job_id
                or plan["job_name"] != source_job_name
                or plan["job_type"] != source_job_type
                or (
                    plan["delivery_occurrence_key"] is not None
                    and plan["delivery_occurrence_key"] != occurrence_key
                )
            ):
                raise ValueError("scheduled note publication does not match the claimed occurrence")

        normalized_chunks: list[tuple[str, str, str, str, int, int]] = []
        for chunk in chunks:
            if not isinstance(chunk, dict):
                raise TypeError("scheduled delivery chunks must be mappings")
            try:
                normalized_chunks.append(
                    self._validate_scheduled_delivery_input(
                        chunk["delivery_key"],
                        occurrence_key,
                        chunk["payload"],
                        chunk["payload_sha256"],
                        chunk["chunk_index"],
                        chunk["chunk_count"],
                    )
                )
            except KeyError as exc:
                raise ValueError("scheduled delivery chunk is missing a required field") from exc

        chunk_counts = {chunk[5] for chunk in normalized_chunks}
        chunk_indexes = {chunk[4] for chunk in normalized_chunks}
        delivery_keys = {chunk[0] for chunk in normalized_chunks}
        if len(chunk_counts) != 1:
            raise ValueError("scheduled delivery chunk counts do not match")
        expected_chunk_count = next(iter(chunk_counts))
        if (
            len(normalized_chunks) != expected_chunk_count
            or chunk_indexes != set(range(expected_chunk_count))
            or len(delivery_keys) != expected_chunk_count
        ):
            raise ValueError("scheduled delivery occurrence chunk set is incomplete")

        ledger_now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            checked_at = now if now is not None else datetime.now()
            checked_at_iso = checked_at.isoformat(timespec="microseconds")
            job = conn.execute(
                """
                SELECT id, name, job_type, metadata, active_occurrence_key,
                       active_occurrence_schedule_revision, schedule_identity_revision,
                       active_occurrence_job_type,
                       active_occurrence_schedule_identity_revision
                FROM scheduled_jobs
                WHERE id = ?
                  AND lease_token = ?
                  AND lease_expires_at > ?
                """,
                (job_id, lease_token, checked_at_iso),
            ).fetchone()
            if job is None:
                return False
            if expected_occurrence_key is not None and (
                type(job["active_occurrence_key"]) is not str
                or not secrets.compare_digest(str(job["active_occurrence_key"]), expected_occurrence_key)
                or job["active_occurrence_schedule_revision"] != expected_schedule_revision
            ):
                return False
            identity_matches = (
                type(job["schedule_identity_revision"]) is int
                and job["schedule_identity_revision"] >= 0
                and type(job["active_occurrence_schedule_identity_revision"]) is int
                and job["active_occurrence_schedule_identity_revision"] >= 0
                and job["schedule_identity_revision"]
                == job["active_occurrence_schedule_identity_revision"]
            )
            if (
                type(job["active_occurrence_job_type"]) is not str
                or not secrets.compare_digest(
                    str(job["active_occurrence_job_type"]), source_job_type
                )
            ):
                return False
            if normalized_run_event is not None and (
                normalized_run_event["schedule_identity_revision"]
                != job["active_occurrence_schedule_identity_revision"]
            ):
                return False
            metadata_json = str(job["metadata"] or "{}")
            if normalized_run_event is not None:
                metadata_json = json.dumps(
                    _job_metadata_with_run_event(metadata_json, normalized_run_event),
                    sort_keys=True,
                )

            for (
                delivery_key,
                normalized_occurrence_key,
                payload,
                payload_sha256,
                chunk_index,
                chunk_count,
            ) in normalized_chunks:
                self._prepare_scheduled_delivery_on_connection(
                    conn,
                    delivery_key=delivery_key,
                    occurrence_key=normalized_occurrence_key,
                    chunk_index=chunk_index,
                    chunk_count=chunk_count,
                    job_id=int(job["id"]),
                        job_name=source_job_name,
                        job_type=source_job_type,
                    payload=payload,
                    payload_sha256=payload_sha256,
                    now=ledger_now,
                )

            for plan in normalized_note_plans:
                self._prepare_scheduled_note_publication_on_connection(
                    conn,
                    plan,
                    now=ledger_now,
                )

            completed = conn.execute(
                """
                UPDATE scheduled_jobs
                SET last_run_at = ?,
                    next_run_at = CASE
                        WHEN typeof(schedule_identity_revision) = 'integer'
                         AND schedule_identity_revision >= 0
                         AND typeof(active_occurrence_schedule_identity_revision) = 'integer'
                         AND active_occurrence_schedule_identity_revision >= 0
                         AND schedule_identity_revision = active_occurrence_schedule_identity_revision THEN ?
                        ELSE next_run_at
                    END,
                    active_occurrence_key = NULL,
                    active_occurrence_schedule_revision = NULL,
                    active_occurrence_next_run_at = NULL,
                    active_occurrence_started_at = NULL,
                    active_occurrence_job_type = NULL,
                    active_occurrence_schedule_identity_revision = NULL,
                    lease_token = NULL,
                    lease_expires_at = NULL,
                    metadata = ?,
                    updated_at = ?
                WHERE id = ?
                  AND lease_token = ?
                  AND lease_expires_at > ?
                """,
                (
                    last_run_at,
                    next_run_at,
                    metadata_json,
                    ledger_now,
                    job_id,
                    lease_token,
                    checked_at_iso,
                ),
            )
            if completed.rowcount != 1:
                raise RuntimeError("scheduled job lease completion was lost")
            return True

    @staticmethod
    def _scheduled_note_attempt_token(value: object) -> str:
        if (
            type(value) is not str
            or not value
            or len(value) > MAX_SCHEDULED_NOTE_IDENTITY_CHARS
            or any(ord(char) < 33 or ord(char) > 126 for char in value)
        ):
            raise ValueError("scheduled note publication attempt token is invalid")
        return value

    @staticmethod
    def _scheduled_note_error_code(value: object, *, fallback: str) -> str:
        if value in (None, ""):
            return fallback
        if (
            type(value) is not str
            or len(value) > MAX_SCHEDULED_NOTE_ERROR_CODE_CHARS
            or SCHEDULED_NOTE_ERROR_CODE_RE.fullmatch(value) is None
        ):
            raise ValueError("scheduled note publication error code is invalid")
        return value

    @staticmethod
    def _scheduled_note_path_display(value: object) -> str:
        if type(value) is not str or not value or len(value) > MAX_SCHEDULED_NOTE_PATH_DISPLAY_CHARS:
            raise ValueError("scheduled note publication path display is invalid")
        if (
            value != value.strip()
            or value.startswith(("/", "~"))
            or "\\" in value
            or "\x00" in value
            or any(part in {"", ".", ".."} for part in value.split("/"))
            or any(ord(char) < 32 for char in value)
        ):
            raise ValueError("scheduled note publication path display is invalid")
        return value

    @staticmethod
    def _terminalize_linked_scheduled_deliveries_on_connection(
        conn: sqlite3.Connection,
        delivery_occurrence_key: str | None,
        *,
        now: str,
    ) -> int:
        if delivery_occurrence_key is None:
            return 0
        return max(
            int(
                conn.execute(
                    """
                    UPDATE scheduled_deliveries
                    SET state = CASE WHEN state = 'sending' THEN 'uncertain' ELSE 'failed' END,
                        payload = NULL,
                        next_attempt_at = NULL,
                        attempt_token = NULL,
                        claimed_at = NULL,
                        sending_at = NULL,
                        finished_at = ?,
                        error_code = 'blocked_by_note_publication_failure',
                        telegram_message_id = NULL,
                        updated_at = ?
                    WHERE occurrence_key = ?
                      AND state IN ('prepared', 'claimed', 'sending', 'rejected')
                    """,
                    (now, now, delivery_occurrence_key),
                ).rowcount
            ),
            0,
        )

    def get_scheduled_note_publication(self, publication_key: str) -> sqlite3.Row | None:
        if (
            type(publication_key) is not str
            or SCHEDULED_NOTE_PUBLICATION_KEY_RE.fullmatch(publication_key) is None
        ):
            raise ValueError("scheduled note publication key is invalid")
        with self.connect() as conn:
            return conn.execute(
                "SELECT * FROM scheduled_note_publications WHERE publication_key = ?",
                (publication_key,),
            ).fetchone()

    def list_scheduled_note_publications_for_occurrence(
        self,
        occurrence_key: str,
    ) -> list[sqlite3.Row]:
        if (
            type(occurrence_key) is not str
            or SCHEDULED_NOTE_OCCURRENCE_KEY_RE.fullmatch(occurrence_key) is None
        ):
            raise ValueError("scheduled note occurrence key is invalid")
        with self.connect() as conn:
            return list(
                conn.execute(
                    """
                    SELECT * FROM scheduled_note_publications
                    WHERE occurrence_key = ?
                    ORDER BY effect_index ASC
                    """,
                    (occurrence_key,),
                )
            )

    def list_scheduled_note_history_reconciliations(
        self,
        limit: int = 100,
    ) -> list[sqlite3.Row]:
        """List terminal note truth that has not reached keyed run history."""
        if type(limit) is not int:
            raise TypeError("scheduled note reconciliation limit must be an integer")
        bounded_limit = max(0, min(limit, 500))
        if bounded_limit == 0:
            return []
        with self.connect() as conn:
            return list(
                conn.execute(
                    """
                    WITH occurrence_truth AS (
                        SELECT occurrence_key, job_id, delivery_occurrence_key,
                               CASE
                                   WHEN SUM(CASE WHEN state = 'failed' THEN 1 ELSE 0 END) > 0
                                       THEN 'failed'
                                   WHEN SUM(CASE WHEN state = 'published' THEN 1 ELSE 0 END) = COUNT(*)
                                       THEN 'published'
                                   ELSE 'pending'
                               END AS state,
                               MAX(updated_at) AS latest_update
                        FROM scheduled_note_publications
                        WHERE job_id IS NOT NULL
                        GROUP BY occurrence_key, job_id, delivery_occurrence_key
                    )
                    SELECT truth.job_id, truth.occurrence_key,
                           truth.delivery_occurrence_key, truth.state
                    FROM occurrence_truth AS truth
                    JOIN scheduled_jobs AS job ON job.id = truth.job_id
                    JOIN json_each(
                        CASE WHEN json_valid(job.metadata) THEN job.metadata ELSE '{}' END,
                        '$.run_history'
                    ) AS event
                    WHERE (
                            truth.state = 'failed'
                            OR (
                                truth.state = 'published'
                                AND truth.delivery_occurrence_key IS NULL
                            )
                          )
                      AND json_extract(event.value, '$.occurrence_key') = COALESCE(
                          truth.delivery_occurrence_key,
                          truth.occurrence_key
                      )
                      AND json_extract(event.value, '$.status') != CASE
                          WHEN truth.state = 'published' THEN 'ok'
                          ELSE 'failed'
                      END
                    ORDER BY truth.latest_update ASC, truth.occurrence_key ASC
                    LIMIT ?
                    """,
                    (bounded_limit,),
                )
            )

    def list_ready_scheduled_note_publications(
        self,
        limit: int = 50,
    ) -> list[sqlite3.Row]:
        if type(limit) is not int:
            raise TypeError("scheduled note publication limit must be an integer")
        bounded_limit = max(0, min(limit, MAX_READY_SCHEDULED_NOTE_PUBLICATIONS))
        if bounded_limit == 0:
            return []
        with self.connect() as conn:
            return list(
                conn.execute(
                    """
                    SELECT publication.*
                    FROM scheduled_note_publications AS publication
                    WHERE publication.state = 'prepared'
                      AND (
                          publication.allow_disabled = 1
                          OR EXISTS (
                              SELECT 1 FROM scheduled_jobs AS source_job
                              WHERE source_job.id = publication.job_id
                                AND source_job.enabled = 1
                          )
                      )
                    ORDER BY publication.updated_at ASC,
                             publication.occurrence_key ASC,
                             publication.effect_index ASC
                    LIMIT ?
                    """,
                    (bounded_limit,),
                )
            )

    def claim_scheduled_note_publication(
        self,
        publication_key: str,
        attempt_token: str,
    ) -> sqlite3.Row | None:
        if (
            type(publication_key) is not str
            or SCHEDULED_NOTE_PUBLICATION_KEY_RE.fullmatch(publication_key) is None
        ):
            raise ValueError("scheduled note publication key is invalid")
        attempt_token = self._scheduled_note_attempt_token(attempt_token)
        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            candidate = conn.execute(
                """
                SELECT * FROM scheduled_note_publications
                WHERE publication_key = ?
                  AND state = 'prepared'
                  AND (
                      allow_disabled = 1
                      OR EXISTS (
                          SELECT 1 FROM scheduled_jobs AS source_job
                          WHERE source_job.id = scheduled_note_publications.job_id
                            AND source_job.enabled = 1
                      )
                  )
                """,
                (publication_key,),
            ).fetchone()
            if candidate is None:
                return None
            payload = candidate["payload"]
            payload_sha256 = candidate["payload_sha256"]
            payload_valid = (
                type(payload) is str
                and 0 < len(payload) <= MAX_SCHEDULED_NOTE_PAYLOAD_CHARS
                and type(payload_sha256) is str
                and SCHEDULED_NOTE_PUBLICATION_KEY_RE.fullmatch(payload_sha256) is not None
                and secrets.compare_digest(
                    payload_sha256,
                    hashlib.sha256(payload.encode("utf-8")).hexdigest(),
                )
            )
            if candidate["effect_started_at"] is None and (
                not payload_valid
                or int(candidate["attempt_count"])
                >= MAX_SCHEDULED_NOTE_PUBLICATION_ATTEMPTS
            ):
                error_code = (
                    "payload_integrity_failed" if not payload_valid else "retry_limit_reached"
                )
                conn.execute(
                    """
                    UPDATE scheduled_note_publications
                    SET state = 'failed', payload = NULL, attempt_token = NULL,
                        claimed_at = NULL, finished_at = ?, error_code = ?, updated_at = ?
                    WHERE publication_key = ? AND state = 'prepared'
                    """,
                    (now, error_code, now, publication_key),
                )
                self._terminalize_linked_scheduled_deliveries_on_connection(
                    conn,
                    candidate["delivery_occurrence_key"],
                    now=now,
                )
                return None
            claimed = conn.execute(
                """
                UPDATE scheduled_note_publications
                SET state = 'claimed', attempt_token = ?,
                    attempt_count = attempt_count + 1,
                    claimed_at = ?,
                    finished_at = NULL, error_code = NULL,
                    path_display = NULL, content_sha256 = NULL, updated_at = ?
                WHERE publication_key = ?
                  AND state = 'prepared'
                  AND (
                      allow_disabled = 1
                      OR EXISTS (
                          SELECT 1 FROM scheduled_jobs AS source_job
                          WHERE source_job.id = scheduled_note_publications.job_id
                            AND source_job.enabled = 1
                      )
                  )
                """,
                (attempt_token, now, now, publication_key),
            )
            if claimed.rowcount != 1:
                return None
            return conn.execute(
                """
                SELECT * FROM scheduled_note_publications
                WHERE publication_key = ? AND state = 'claimed' AND attempt_token = ?
                """,
                (publication_key, attempt_token),
            ).fetchone()

    def begin_scheduled_note_publication_effect(
        self,
        publication_key: str,
        token: str,
    ) -> bool:
        """Fence the exact claimed row at the filesystem effect boundary."""
        if (
            type(publication_key) is not str
            or SCHEDULED_NOTE_PUBLICATION_KEY_RE.fullmatch(publication_key) is None
        ):
            return False
        try:
            token = self._scheduled_note_attempt_token(token)
        except ValueError:
            return False
        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                """
                SELECT payload, payload_sha256, effect_started_at, job_type,
                       delivery_occurrence_key, source_manifest_kind,
                       source_manifest_digest
                FROM scheduled_note_publications
                WHERE publication_key = ?
                  AND state = 'claimed'
                  AND attempt_token = ?
                  AND (
                      allow_disabled = 1
                      OR EXISTS (
                          SELECT 1 FROM scheduled_jobs AS source_job
                          WHERE source_job.id = scheduled_note_publications.job_id
                            AND source_job.enabled = 1
                      )
                  )
                """,
                (publication_key, token),
            ).fetchone()
            if (
                row is None
                or type(row["payload"]) is not str
                or type(row["payload_sha256"]) is not str
                or not secrets.compare_digest(
                    str(row["payload_sha256"]),
                    hashlib.sha256(str(row["payload"]).encode("utf-8")).hexdigest(),
                )
            ):
                return False
            if row["job_type"] == "goal_nudge":
                source_is_current = self._goal_nudge_source_manifest_is_current_on_connection(
                    conn,
                    row["source_manifest_kind"],
                    row["source_manifest_digest"],
                )
                if not source_is_current:
                    failed = conn.execute(
                        """
                        UPDATE scheduled_note_publications
                        SET state = 'failed', payload = NULL, attempt_token = NULL,
                            claimed_at = NULL, effect_started_at = NULL,
                            finished_at = ?, error_code = 'source_manifest_stale',
                            updated_at = ?
                        WHERE publication_key = ?
                          AND state = 'claimed'
                          AND attempt_token = ?
                        """,
                        (now, now, publication_key, token),
                    )
                    if failed.rowcount == 1:
                        self._terminalize_linked_scheduled_deliveries_on_connection(
                            conn,
                            row["delivery_occurrence_key"],
                            now=now,
                        )
                    return False
            updated = conn.execute(
                """
                UPDATE scheduled_note_publications
                SET effect_started_at = COALESCE(effect_started_at, ?),
                    allow_disabled = 1,
                    updated_at = ?
                WHERE publication_key = ?
                  AND state = 'claimed'
                  AND attempt_token = ?
                """,
                (now, now, publication_key, token),
            )
            return updated.rowcount == 1

    def scheduled_note_publication_claim_is_live(
        self,
        publication_key: str,
        token: str,
    ) -> bool:
        if (
            type(publication_key) is not str
            or SCHEDULED_NOTE_PUBLICATION_KEY_RE.fullmatch(publication_key) is None
        ):
            return False
        try:
            token = self._scheduled_note_attempt_token(token)
        except ValueError:
            return False
        with self.connect() as conn:
            row = conn.execute(
                """
                SELECT attempt_token, payload, payload_sha256
                FROM scheduled_note_publications
                WHERE publication_key = ?
                  AND state = 'claimed'
                  AND (
                      allow_disabled = 1
                      OR EXISTS (
                          SELECT 1 FROM scheduled_jobs AS source_job
                          WHERE source_job.id = scheduled_note_publications.job_id
                            AND source_job.enabled = 1
                      )
                  )
                """,
                (publication_key,),
            ).fetchone()
        if (
            row is None
            or type(row["attempt_token"]) is not str
            or not secrets.compare_digest(str(row["attempt_token"]), token)
            or type(row["payload"]) is not str
            or type(row["payload_sha256"]) is not str
        ):
            return False
        return secrets.compare_digest(
            str(row["payload_sha256"]),
            hashlib.sha256(str(row["payload"]).encode("utf-8")).hexdigest(),
        )

    def finish_scheduled_note_publication(
        self,
        publication_key: str,
        token: str,
        state: str,
        *,
        path_display: str = "",
        content_sha256: str = "",
        error_code: str = "",
    ) -> bool:
        if (
            type(publication_key) is not str
            or SCHEDULED_NOTE_PUBLICATION_KEY_RE.fullmatch(publication_key) is None
        ):
            raise ValueError("scheduled note publication key is invalid")
        token = self._scheduled_note_attempt_token(token)
        if state not in {"published", "failed", "retryable", "prepared"}:
            raise ValueError("scheduled note publication finish state is invalid")
        if state == "published":
            path_display = self._scheduled_note_path_display(path_display)
            if (
                type(content_sha256) is not str
                or SCHEDULED_NOTE_PUBLICATION_KEY_RE.fullmatch(content_sha256) is None
            ):
                raise ValueError("scheduled note publication content hash is invalid")
            if error_code:
                raise ValueError("published scheduled notes cannot have an error code")
            safe_error_code = None
        else:
            if path_display or content_sha256:
                raise ValueError("failed scheduled notes cannot retain publication evidence")
            safe_error_code = self._scheduled_note_error_code(
                error_code,
                fallback="publication_failed",
            )

        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                """
                SELECT attempt_count, delivery_occurrence_key, job_id, allow_disabled,
                       payload_sha256, effect_started_at
                FROM scheduled_note_publications
                WHERE publication_key = ? AND state = 'claimed' AND attempt_token = ?
                """,
                (publication_key, token),
            ).fetchone()
            if row is None:
                return False
            if state == "published" and type(row["effect_started_at"]) is not str:
                return False
            if state == "published" and not secrets.compare_digest(
                str(row["payload_sha256"]), content_sha256
            ):
                raise ValueError("scheduled note publication content hash mismatch")
            effective_state = state
            if state == "failed" and row["effect_started_at"] is not None:
                # A committed filesystem effect cannot be declared failed: a
                # stale owner may still complete the exact write. Preserve the
                # row for marker replay under a replacement claim.
                effective_state = "prepared"
                safe_error_code = "publication_outcome_uncertain"
            if state in {"retryable", "prepared"}:
                job_exists = row["job_id"] is not None and conn.execute(
                    "SELECT 1 FROM scheduled_jobs WHERE id = ?",
                    (row["job_id"],),
                ).fetchone() is not None
                if (
                    (
                        not job_exists
                        and int(row["allow_disabled"]) != 1
                        and row["effect_started_at"] is None
                    )
                    or (
                        int(row["attempt_count"])
                        >= MAX_SCHEDULED_NOTE_PUBLICATION_ATTEMPTS
                        and row["effect_started_at"] is None
                    )
                ):
                    effective_state = "failed"
                    safe_error_code = (
                        "job_deleted_before_retry" if not job_exists else "retry_limit_reached"
                    )
                else:
                    effective_state = "prepared"

            terminal = effective_state in {"published", "failed"}
            updated = conn.execute(
                """
                UPDATE scheduled_note_publications
                SET state = ?,
                    payload = CASE WHEN ? THEN NULL ELSE payload END,
                    attempt_token = NULL,
                    claimed_at = NULL,
                    effect_started_at = CASE WHEN ? THEN NULL ELSE effect_started_at END,
                    allow_disabled = CASE
                        WHEN NOT ? AND effect_started_at IS NOT NULL THEN 1
                        ELSE allow_disabled
                    END,
                    finished_at = CASE WHEN ? THEN ? ELSE NULL END,
                    error_code = ?,
                    path_display = ?,
                    content_sha256 = ?,
                    updated_at = ?
                WHERE publication_key = ? AND state = 'claimed' AND attempt_token = ?
                """,
                (
                    effective_state,
                    1 if terminal else 0,
                    1 if terminal else 0,
                    1 if terminal else 0,
                    1 if terminal else 0,
                    now,
                    None if effective_state == "published" else safe_error_code,
                    path_display if effective_state == "published" else None,
                    content_sha256 if effective_state == "published" else None,
                    now,
                    publication_key,
                    token,
                ),
            )
            if updated.rowcount != 1:
                return False
            if effective_state == "failed":
                self._terminalize_linked_scheduled_deliveries_on_connection(
                    conn,
                    row["delivery_occurrence_key"],
                    now=now,
                )
            return True

    def recover_stale_scheduled_note_publications(
        self,
        stale_before: str,
        limit: int = 100,
    ) -> dict[str, Any]:
        if _strict_utc_timestamp(stale_before) is None:
            raise ValueError("scheduled note stale boundary is invalid")
        if type(limit) is not int:
            raise TypeError("scheduled note recovery limit must be an integer")
        bounded_limit = max(0, min(limit, MAX_READY_SCHEDULED_NOTE_PUBLICATIONS))
        if bounded_limit == 0:
            return {"claimed_to_prepared": 0, "claimed_to_failed": 0}
        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            rows = list(
                conn.execute(
                    """
                    SELECT publication_key, attempt_count, delivery_occurrence_key, job_id,
                           allow_disabled, effect_started_at
                    FROM scheduled_note_publications
                    WHERE state = 'claimed'
                      AND (claimed_at IS NULL OR claimed_at <= ?)
                    ORDER BY claimed_at ASC, publication_key ASC
                    LIMIT ?
                    """,
                    (stale_before, bounded_limit),
                )
            )
            prepared = 0
            failed = 0
            for row in rows:
                job_exists = row["job_id"] is not None and conn.execute(
                    "SELECT 1 FROM scheduled_jobs WHERE id = ?",
                    (row["job_id"],),
                ).fetchone() is not None
                effect_committed = type(row["effect_started_at"]) is str
                terminal = not effect_committed and (
                    (
                        not job_exists
                        and int(row["allow_disabled"]) != 1
                    )
                    or int(row["attempt_count"])
                    >= MAX_SCHEDULED_NOTE_PUBLICATION_ATTEMPTS
                )
                if terminal:
                    error = "job_deleted_before_retry" if not job_exists else "retry_limit_reached"
                    conn.execute(
                        """
                        UPDATE scheduled_note_publications
                        SET state = 'failed', payload = NULL, attempt_token = NULL,
                            claimed_at = NULL, effect_started_at = NULL,
                            finished_at = ?, error_code = ?,
                            path_display = NULL, content_sha256 = NULL, updated_at = ?
                        WHERE publication_key = ? AND state = 'claimed'
                        """,
                        (now, error, now, row["publication_key"]),
                    )
                    self._terminalize_linked_scheduled_deliveries_on_connection(
                        conn,
                        row["delivery_occurrence_key"],
                        now=now,
                    )
                    failed += 1
                else:
                    conn.execute(
                        """
                        UPDATE scheduled_note_publications
                        SET state = 'prepared', attempt_token = NULL,
                            claimed_at = NULL,
                            allow_disabled = CASE
                                WHEN effect_started_at IS NOT NULL THEN 1
                                ELSE allow_disabled
                            END,
                            finished_at = NULL, error_code = NULL,
                            path_display = NULL, content_sha256 = NULL, updated_at = ?
                        WHERE publication_key = ? AND state = 'claimed'
                        """,
                        (now, row["publication_key"]),
                    )
                    prepared += 1
            return {
                "claimed_to_prepared": prepared,
                "claimed_to_failed": failed,
            }

    def claim_scheduled_delivery(
        self,
        delivery_key: str,
        attempt_token: str,
    ) -> sqlite3.Row | None:
        """Atomically claim a due row after all earlier chunks were accepted."""
        if not attempt_token:
            raise ValueError("scheduled delivery attempt token must not be empty")
        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            candidate = conn.execute(
                """
                SELECT candidate.*
                FROM scheduled_deliveries AS candidate
                WHERE candidate.delivery_key = ?
                  AND candidate.state IN ('prepared', 'rejected')
                  AND candidate.next_attempt_at IS NOT NULL
                  AND candidate.next_attempt_at <= ?
                  AND EXISTS (
                      SELECT 1 FROM scheduled_jobs AS source_job
                      WHERE source_job.id = candidate.job_id AND source_job.enabled = 1
                  )
                  AND NOT EXISTS (
                      SELECT 1 FROM scheduled_note_publications AS note
                      WHERE note.delivery_occurrence_key = candidate.occurrence_key
                        AND note.state != 'published'
                  )
                  AND (
                      SELECT COUNT(*)
                      FROM scheduled_deliveries AS earlier
                      WHERE earlier.occurrence_key = candidate.occurrence_key
                        AND earlier.chunk_index < candidate.chunk_index
                        AND earlier.state = 'accepted'
                  ) = candidate.chunk_index
                """,
                (delivery_key, now),
            ).fetchone()
            if candidate is None:
                return None
            payload = candidate["payload"]
            payload_sha256 = candidate["payload_sha256"]
            payload_valid = (
                isinstance(payload, str)
                and isinstance(payload_sha256, str)
                and payload_sha256 == hashlib.sha256(payload.encode("utf-8")).hexdigest()
            )
            if not payload_valid:
                conn.execute(
                    """
                    UPDATE scheduled_deliveries
                    SET state = 'failed', payload = NULL, next_attempt_at = NULL,
                        attempt_token = NULL, claimed_at = NULL, sending_at = NULL,
                        finished_at = ?, error_code = 'payload_integrity_failed', updated_at = ?
                    WHERE delivery_key = ? AND state IN ('prepared', 'rejected')
                    """,
                    (now, now, delivery_key),
                )
                conn.execute(
                    """
                    UPDATE scheduled_deliveries
                    SET state = 'failed', payload = NULL, next_attempt_at = NULL,
                        attempt_token = NULL, claimed_at = NULL, sending_at = NULL,
                        finished_at = ?, error_code = 'blocked_by_terminal_predecessor', updated_at = ?
                    WHERE occurrence_key = ?
                      AND chunk_index > ?
                      AND state IN ('prepared', 'claimed', 'rejected')
                    """,
                    (now, now, candidate["occurrence_key"], int(candidate["chunk_index"])),
                )
                return None
            cur = conn.execute(
                """
                UPDATE scheduled_deliveries AS candidate
                SET state = 'claimed',
                    attempt_token = ?,
                    claimed_at = ?,
                    sending_at = NULL,
                    finished_at = NULL,
                    error_code = NULL,
                    telegram_message_id = NULL,
                    updated_at = ?
                WHERE delivery_key = ?
                  AND state IN ('prepared', 'rejected')
                  AND next_attempt_at IS NOT NULL
                  AND next_attempt_at <= ?
                  AND EXISTS (
                      SELECT 1 FROM scheduled_jobs AS source_job
                      WHERE source_job.id = candidate.job_id AND source_job.enabled = 1
                  )
                  AND NOT EXISTS (
                      SELECT 1 FROM scheduled_note_publications AS note
                      WHERE note.delivery_occurrence_key = candidate.occurrence_key
                        AND note.state != 'published'
                  )
                  AND (
                      SELECT COUNT(*)
                      FROM scheduled_deliveries AS earlier
                      WHERE earlier.occurrence_key = candidate.occurrence_key
                        AND earlier.chunk_index < candidate.chunk_index
                        AND earlier.state = 'accepted'
                  ) = candidate.chunk_index
                """,
                (attempt_token, now, now, delivery_key, now),
            )
            if cur.rowcount != 1:
                return None
            return conn.execute(
                """
                SELECT * FROM scheduled_deliveries
                WHERE delivery_key = ? AND state = 'claimed' AND attempt_token = ?
                """,
                (delivery_key, attempt_token),
            ).fetchone()

    def begin_scheduled_delivery_send(self, delivery_key: str, attempt_token: str) -> bool:
        """Fence the claim immediately before the Telegram network call."""
        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            candidate = conn.execute(
                """
                SELECT delivery.occurrence_key, delivery.chunk_index,
                       delivery.job_type AS delivery_job_type,
                       note.job_type AS note_job_type,
                       note.source_manifest_kind, note.source_manifest_digest
                FROM scheduled_deliveries AS delivery
                LEFT JOIN scheduled_note_publications AS note
                  ON note.delivery_occurrence_key = delivery.occurrence_key
                WHERE delivery.delivery_key = ?
                  AND delivery.state = 'claimed'
                  AND delivery.attempt_token = ?
                  AND (note.publication_key IS NULL OR note.state = 'published')
                """,
                (delivery_key, attempt_token),
            ).fetchone()
            if candidate is None:
                return False
            if candidate["delivery_job_type"] == "goal_nudge":
                # A published linked note is the durable first effect for this
                # immutable occurrence. Retries must finish that exact payload
                # rather than abandon an already-visible prefix.
                source_is_bound = (
                    candidate["note_job_type"] == "goal_nudge"
                    and candidate["source_manifest_kind"]
                    == GOAL_NUDGE_SOURCE_MANIFEST_KIND
                    and type(candidate["source_manifest_digest"]) is str
                    and SCHEDULED_NOTE_PUBLICATION_KEY_RE.fullmatch(
                        candidate["source_manifest_digest"]
                    )
                    is not None
                )
                if not source_is_bound:
                    failed = conn.execute(
                        """
                        UPDATE scheduled_deliveries
                        SET state = 'failed', payload = NULL, next_attempt_at = NULL,
                            attempt_token = NULL, claimed_at = NULL, sending_at = NULL,
                            finished_at = ?, error_code = 'source_manifest_stale',
                            updated_at = ?
                        WHERE delivery_key = ?
                          AND state = 'claimed'
                          AND attempt_token = ?
                        """,
                        (now, now, delivery_key, attempt_token),
                    )
                    if failed.rowcount == 1:
                        conn.execute(
                            """
                            UPDATE scheduled_deliveries
                            SET state = 'failed', payload = NULL, next_attempt_at = NULL,
                                attempt_token = NULL, claimed_at = NULL, sending_at = NULL,
                                finished_at = ?,
                                error_code = 'blocked_by_terminal_predecessor',
                                updated_at = ?
                            WHERE occurrence_key = ?
                              AND chunk_index > ?
                              AND state IN ('prepared', 'claimed', 'rejected')
                            """,
                            (
                                now,
                                now,
                                candidate["occurrence_key"],
                                int(candidate["chunk_index"]),
                            ),
                        )
                    return False
            cur = conn.execute(
                """
                UPDATE scheduled_deliveries
                SET state = 'sending',
                    attempt_count = attempt_count + 1,
                    sending_at = ?,
                    updated_at = ?
                WHERE delivery_key = ?
                  AND state = 'claimed'
                  AND attempt_token = ?
                  AND EXISTS (
                      SELECT 1 FROM scheduled_jobs AS source_job
                      WHERE source_job.id = scheduled_deliveries.job_id
                        AND source_job.enabled = 1
                  )
                  AND NOT EXISTS (
                      SELECT 1 FROM scheduled_note_publications AS note
                      WHERE note.delivery_occurrence_key = scheduled_deliveries.occurrence_key
                        AND note.state != 'published'
                  )
                """,
                (now, now, delivery_key, attempt_token),
            )
            return cur.rowcount == 1

    def release_scheduled_delivery_claim(
        self,
        delivery_key: str,
        attempt_token: str,
    ) -> bool:
        """Return an exact pre-I/O claim to prepared without spending an attempt."""
        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            cur = conn.execute(
                """
                UPDATE scheduled_deliveries
                SET state = 'prepared',
                    attempt_token = NULL,
                    claimed_at = NULL,
                    sending_at = NULL,
                    finished_at = NULL,
                    error_code = NULL,
                    telegram_message_id = NULL,
                    updated_at = ?
                WHERE delivery_key = ?
                  AND state = 'claimed'
                  AND attempt_token = ?
                  AND sending_at IS NULL
                """,
                (now, delivery_key, attempt_token),
            )
            return cur.rowcount == 1

    def finish_scheduled_delivery(
        self,
        delivery_key: str,
        attempt_token: str,
        terminal_state: str,
        error_code: str | None = None,
        retry_after_seconds: int | float | None = None,
        telegram_message_id: int | None = None,
    ) -> bool:
        """Finish a token-fenced sending attempt with explicit certainty."""
        if terminal_state not in SCHEDULED_DELIVERY_TERMINAL_STATES:
            raise ValueError("invalid scheduled delivery terminal state")
        if telegram_message_id is not None and terminal_state != "accepted":
            raise ValueError("only accepted deliveries may store a Telegram receipt")

        now = utc_now()
        safe_error_code = None if error_code is None else str(error_code)[:128]
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                """
                SELECT occurrence_key, chunk_index, attempt_count, job_id
                FROM scheduled_deliveries
                WHERE delivery_key = ? AND state = 'sending' AND attempt_token = ?
                """,
                (delivery_key, attempt_token),
            ).fetchone()
            if row is None:
                return False
            effective_state = terminal_state
            if terminal_state == "rejected":
                if row["job_id"] is None:
                    effective_state = "failed"
                    safe_error_code = "job_deleted_before_retry"
                elif int(row["attempt_count"]) >= MAX_SCHEDULED_DELIVERY_ATTEMPTS:
                    effective_state = "failed"
                    safe_error_code = safe_error_code or "retry_limit_reached"
            next_attempt_at: str | None = None
            if effective_state == "rejected":
                if retry_after_seconds is None:
                    retry_seconds = 0
                else:
                    try:
                        retry_seconds = int(retry_after_seconds)
                    except (TypeError, ValueError, OverflowError) as exc:
                        raise ValueError("invalid scheduled delivery retry delay") from exc
                retry_seconds = max(0, min(retry_seconds, MAX_SCHEDULED_DELIVERY_RETRY_SECONDS))
                next_attempt_at = (
                    datetime.fromisoformat(now.removesuffix("Z")) + timedelta(seconds=retry_seconds)
                ).replace(microsecond=0).isoformat() + "Z"
            cur = conn.execute(
                """
                UPDATE scheduled_deliveries
                SET state = ?,
                    payload = CASE WHEN ? IN ('accepted', 'uncertain', 'failed') THEN NULL ELSE payload END,
                    next_attempt_at = ?,
                    finished_at = ?,
                    error_code = ?,
                    telegram_message_id = ?,
                    updated_at = ?
                WHERE delivery_key = ?
                  AND state = 'sending'
                  AND attempt_token = ?
                """,
                (
                    effective_state,
                    effective_state,
                    next_attempt_at,
                    now,
                    safe_error_code,
                    telegram_message_id,
                    now,
                    delivery_key,
                    attempt_token,
                ),
            )
            if cur.rowcount != 1:
                return False
            if effective_state in {"uncertain", "failed"}:
                conn.execute(
                    """
                    UPDATE scheduled_deliveries
                    SET state = 'failed', payload = NULL, next_attempt_at = NULL,
                        attempt_token = NULL, claimed_at = NULL, sending_at = NULL,
                        finished_at = ?, error_code = 'blocked_by_terminal_predecessor', updated_at = ?
                    WHERE occurrence_key = ?
                      AND chunk_index > ?
                      AND state IN ('prepared', 'claimed', 'rejected')
                    """,
                    (now, now, row["occurrence_key"], int(row["chunk_index"])),
                )
            return True

    def recover_stale_scheduled_deliveries(self, stale_before: str) -> dict[str, Any]:
        """Recover pre-I/O claims and quarantine ambiguous in-flight sends."""
        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            uncertain_occurrence_keys = [
                str(row["occurrence_key"])
                for row in conn.execute(
                    """
                    SELECT DISTINCT occurrence_key
                    FROM scheduled_deliveries
                    WHERE state = 'sending'
                      AND (sending_at IS NULL OR sending_at <= ?)
                    ORDER BY occurrence_key
                    """,
                    (stale_before,),
                )
            ]
            claimed = conn.execute(
                """
                UPDATE scheduled_deliveries
                SET state = 'prepared',
                    attempt_token = NULL,
                    next_attempt_at = ?,
                    claimed_at = NULL,
                    error_code = NULL,
                    updated_at = ?
                WHERE state = 'claimed'
                  AND (claimed_at IS NULL OR claimed_at <= ?)
                """,
                (now, now, stale_before),
            ).rowcount
            sending = conn.execute(
                """
                UPDATE scheduled_deliveries
                SET state = 'uncertain',
                    payload = NULL,
                    next_attempt_at = NULL,
                    finished_at = ?,
                    error_code = 'stale_sending_recovered',
                    updated_at = ?
                WHERE state = 'sending'
                  AND (sending_at IS NULL OR sending_at <= ?)
                """,
                (now, now, stale_before),
            ).rowcount
            quarantined_suffix = conn.execute(
                """
                UPDATE scheduled_deliveries AS candidate
                SET state = 'failed', payload = NULL, next_attempt_at = NULL,
                    attempt_token = NULL, claimed_at = NULL, sending_at = NULL,
                    finished_at = ?, error_code = 'blocked_by_uncertain_predecessor', updated_at = ?
                WHERE candidate.state IN ('prepared', 'claimed', 'rejected')
                  AND EXISTS (
                      SELECT 1 FROM scheduled_deliveries AS earlier
                      WHERE earlier.occurrence_key = candidate.occurrence_key
                        AND earlier.chunk_index < candidate.chunk_index
                        AND earlier.state = 'uncertain'
                  )
                """,
                (now, now),
            ).rowcount
            return {
                "claimed_to_prepared": claimed,
                "sending_to_uncertain": sending,
                "suffix_to_failed": quarantined_suffix,
                "uncertain_occurrence_keys": uncertain_occurrence_keys,
            }

    def list_ready_scheduled_deliveries(self, now: str, limit: int = 50) -> list[sqlite3.Row]:
        """List due rows in chunk order without returning blocked later chunks."""
        bounded_limit = max(0, min(int(limit), MAX_READY_SCHEDULED_DELIVERIES))
        if bounded_limit == 0:
            return []
        with self.connect() as conn:
            return list(
                conn.execute(
                    """
                    SELECT candidate.*
                    FROM scheduled_deliveries AS candidate
                    WHERE candidate.state IN ('prepared', 'rejected')
                      AND candidate.next_attempt_at IS NOT NULL
                      AND candidate.next_attempt_at <= ?
                      AND EXISTS (
                          SELECT 1 FROM scheduled_jobs AS source_job
                          WHERE source_job.id = candidate.job_id AND source_job.enabled = 1
                      )
                      AND NOT EXISTS (
                          SELECT 1 FROM scheduled_note_publications AS note
                          WHERE note.delivery_occurrence_key = candidate.occurrence_key
                            AND note.state != 'published'
                      )
                      AND (
                          SELECT COUNT(*)
                          FROM scheduled_deliveries AS earlier
                          WHERE earlier.occurrence_key = candidate.occurrence_key
                            AND earlier.chunk_index < candidate.chunk_index
                            AND earlier.state = 'accepted'
                      ) = candidate.chunk_index
                    ORDER BY candidate.next_attempt_at ASC,
                             candidate.occurrence_key ASC,
                             candidate.chunk_index ASC
                    LIMIT ?
                    """,
                    (now, bounded_limit),
                )
            )

    def get_scheduled_delivery(self, delivery_key: str) -> sqlite3.Row | None:
        with self.connect() as conn:
            return conn.execute(
                "SELECT * FROM scheduled_deliveries WHERE delivery_key = ?",
                (delivery_key,),
            ).fetchone()

    def list_scheduled_deliveries_for_occurrence(
        self,
        occurrence_key: str,
    ) -> list[sqlite3.Row]:
        """Return the original durable chunks for an occurrence in send order."""
        with self.connect() as conn:
            return list(
                conn.execute(
                    """
                    SELECT * FROM scheduled_deliveries
                    WHERE occurrence_key = ?
                    ORDER BY chunk_index ASC
                    """,
                    (occurrence_key,),
                )
            )

    def list_scheduled_delivery_history_reconciliations(
        self,
        limit: int = 100,
    ) -> list[sqlite3.Row]:
        """List bounded delivery outcomes that disagree with keyed run history."""
        bounded_limit = max(0, min(int(limit), 500))
        if bounded_limit == 0:
            return []
        with self.connect() as conn:
            return list(
                conn.execute(
                    """
                    WITH raw_occurrence_truth AS (
                        SELECT occurrence_key, job_id,
                               CASE
                                   WHEN SUM(CASE WHEN state = 'uncertain' THEN 1 ELSE 0 END) > 0
                                       THEN 'uncertain'
                                   WHEN SUM(CASE WHEN state = 'failed' THEN 1 ELSE 0 END) > 0
                                       THEN 'failed'
                                   WHEN SUM(CASE WHEN state = 'rejected' THEN 1 ELSE 0 END) > 0
                                       THEN 'rejected'
                                   WHEN SUM(CASE WHEN state = 'accepted' THEN 1 ELSE 0 END) = COUNT(*)
                                    AND COUNT(*) = MAX(chunk_count)
                                    AND MIN(chunk_count) = MAX(chunk_count)
                                    AND MIN(chunk_index) = 0
                                    AND MAX(chunk_index) = MAX(chunk_count) - 1
                                    AND COUNT(DISTINCT chunk_index) = COUNT(*)
                                    AND MIN(source_job_id) = MAX(source_job_id)
                                    AND MIN(job_type) = MAX(job_type)
                                       THEN 'accepted'
                                   ELSE 'pending'
                               END AS delivery_state,
                               MIN(source_job_id) AS source_job_id,
                               MIN(job_type) AS source_job_type,
                               MIN(job_name) AS source_job_name,
                               MAX(updated_at) AS latest_update
                        FROM scheduled_deliveries
                        GROUP BY occurrence_key, job_id
                    ), occurrence_truth AS (
                        SELECT raw.*,
                               CASE
                                   WHEN raw.job_id IS NOT NULL THEN raw.job_id
                                   WHEN raw.source_job_type = 'morning_brief_telegram'
                                    AND raw.source_job_name = 'Morning Brief' COLLATE NOCASE
                                    AND raw.occurrence_key LIKE 'morning:%'
                                    AND (
                                        SELECT COUNT(*) FROM scheduled_jobs AS morning
                                        WHERE morning.job_type = 'morning_brief_telegram'
                                          AND morning.name = 'Morning Brief' COLLATE NOCASE
                                    ) = 1
                                       THEN (
                                           SELECT MIN(morning.id) FROM scheduled_jobs AS morning
                                           WHERE morning.job_type = 'morning_brief_telegram'
                                             AND morning.name = 'Morning Brief' COLLATE NOCASE
                                       )
                                   ELSE NULL
                               END AS history_job_id
                        FROM raw_occurrence_truth AS raw
                    ), history_events AS (
                        SELECT job.id AS job_id, event.value AS event_value
                        FROM scheduled_jobs AS job
                        JOIN json_each(
                            CASE WHEN json_valid(job.metadata) THEN job.metadata ELSE '{}' END,
                            '$.run_history'
                        ) AS event
                        UNION ALL
                        SELECT job.id AS job_id, event.value AS event_value
                        FROM scheduled_jobs AS job
                        JOIN json_each(
                            CASE WHEN json_valid(job.metadata) THEN job.metadata ELSE '{}' END,
                            '$.run_history_legacy'
                        ) AS event
                    )
                    SELECT truth.occurrence_key, truth.delivery_state
                    FROM occurrence_truth AS truth
                    JOIN history_events AS event ON event.job_id = truth.history_job_id
                    WHERE truth.delivery_state IN ('accepted', 'uncertain', 'failed', 'rejected')
                      AND (
                          truth.source_job_id = truth.history_job_id
                          OR (
                              truth.job_id IS NULL
                              AND truth.source_job_type = 'morning_brief_telegram'
                              AND truth.source_job_name = 'Morning Brief' COLLATE NOCASE
                              AND truth.occurrence_key LIKE 'morning:%'
                          )
                      )
                      AND json_extract(event.event_value, '$.occurrence_key') = truth.occurrence_key
                      AND (
                          json_type(event.event_value, '$.job_type') IS NULL
                          OR json_extract(event.event_value, '$.job_type') = truth.source_job_type
                      )
                      AND json_extract(event.event_value, '$.status') != CASE
                          WHEN truth.delivery_state = 'accepted' THEN 'ok'
                          ELSE 'failed'
                      END
                    ORDER BY truth.latest_update, truth.occurrence_key
                    LIMIT ?
                    """,
                    (bounded_limit,),
                )
            )

    def scheduled_delivery_state_counts(self) -> dict[str, int]:
        """Return fixed-cardinality, saturating counts without payload data."""
        counts = {state: 0 for state in SCHEDULED_DELIVERY_STATES}
        with self.connect() as conn:
            rows = conn.execute(
                "SELECT state, COUNT(*) AS row_count FROM scheduled_deliveries GROUP BY state"
            )
            for row in rows:
                state = str(row["state"])
                if state in counts:
                    counts[state] = min(int(row["row_count"]), MAX_SCHEDULED_DELIVERY_STATE_COUNT)
        return counts

    def scheduled_delivery_operational_snapshot(self) -> dict[str, Any]:
        """Return content-free occurrence health for scheduler diagnostics."""
        counts = self.scheduled_delivery_state_counts()
        with self.connect() as conn:
            row = conn.execute(
                """
                SELECT
                    COUNT(DISTINCT occurrence_key) AS occurrences,
                    COUNT(DISTINCT CASE WHEN state IN ('prepared','claimed','sending','rejected') THEN occurrence_key END) AS active_occurrences,
                    COUNT(DISTINCT CASE WHEN state = 'uncertain' THEN occurrence_key END) AS uncertain_occurrences,
                    COUNT(DISTINCT CASE WHEN state = 'failed' THEN occurrence_key END) AS failed_occurrences,
                    SUM(CASE WHEN job_id IS NULL THEN 1 ELSE 0 END) AS orphaned_chunks,
                    SUM(CASE WHEN payload IS NOT NULL THEN 1 ELSE 0 END) AS content_bearing_chunks,
                    MIN(CASE WHEN state IN ('prepared','claimed','sending','rejected') THEN created_at END) AS oldest_active_at
                FROM scheduled_deliveries
                """
            ).fetchone()
        return {
            "state_counts": counts,
            "chunk_receipts": min(sum(counts.values()), MAX_SCHEDULED_DELIVERY_STATE_COUNT),
            "occurrences": min(int(row["occurrences"] or 0), MAX_SCHEDULED_DELIVERY_STATE_COUNT),
            "active_occurrences": min(int(row["active_occurrences"] or 0), MAX_SCHEDULED_DELIVERY_STATE_COUNT),
            "uncertain_occurrences": min(int(row["uncertain_occurrences"] or 0), MAX_SCHEDULED_DELIVERY_STATE_COUNT),
            "failed_occurrences": min(int(row["failed_occurrences"] or 0), MAX_SCHEDULED_DELIVERY_STATE_COUNT),
            "orphaned_chunks": min(int(row["orphaned_chunks"] or 0), MAX_SCHEDULED_DELIVERY_STATE_COUNT),
            "content_bearing_chunks": min(int(row["content_bearing_chunks"] or 0), MAX_SCHEDULED_DELIVERY_STATE_COUNT),
            "oldest_active_at": str(row["oldest_active_at"] or "")[:32],
            "counts_saturated": any(value >= MAX_SCHEDULED_DELIVERY_STATE_COUNT for value in counts.values()),
        }

    def prune_scheduled_deliveries(
        self,
        terminal_before: str,
        uncertain_before: str,
        limit: int = 100,
    ) -> int:
        """Delete only fully terminal, old occurrences in bounded batches."""
        bounded_limit = max(0, min(int(limit), 500))
        if bounded_limit == 0:
            return 0
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            rows = list(
                conn.execute(
                    """
                    SELECT occurrence_key
                    FROM scheduled_deliveries
                    GROUP BY occurrence_key
                    HAVING SUM(CASE WHEN state IN ('prepared','claimed','sending','rejected') THEN 1 ELSE 0 END) = 0
                       AND (
                            (SUM(CASE WHEN state = 'uncertain' THEN 1 ELSE 0 END) = 0 AND MAX(finished_at) <= ?)
                            OR
                            (SUM(CASE WHEN state = 'uncertain' THEN 1 ELSE 0 END) > 0 AND MAX(finished_at) <= ?)
                       )
                    ORDER BY MAX(finished_at) ASC, occurrence_key ASC
                    LIMIT ?
                    """,
                    (terminal_before, uncertain_before, bounded_limit),
                )
            )
            if not rows:
                return 0
            keys = [str(row["occurrence_key"]) for row in rows]
            placeholders = ",".join("?" for _ in keys)
            deleted = conn.execute(
                f"DELETE FROM scheduled_deliveries WHERE occurrence_key IN ({placeholders})",
                keys,
            ).rowcount
            return max(int(deleted), 0)

    def claim_job(
        self,
        job_id: int,
        lease_token: str,
        lease_seconds: float,
        *,
        due_before: str | None = None,
        now: datetime | None = None,
    ) -> sqlite3.Row | None:
        """Atomically claim one runnable job and return its current row."""
        due_clause = ""
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            checked_at = now if now is not None else datetime.now()
            checked_at_iso = checked_at.isoformat(timespec="microseconds")
            lease_expires_at = (checked_at + timedelta(seconds=lease_seconds)).isoformat(timespec="microseconds")
            candidate = conn.execute(
                """
                SELECT id, next_run_at, schedule_revision, schedule_identity_revision,
                       job_type,
                       active_occurrence_key, active_occurrence_schedule_revision,
                       active_occurrence_next_run_at, active_occurrence_started_at,
                       active_occurrence_job_type,
                       active_occurrence_schedule_identity_revision,
                       lease_token, lease_expires_at
                FROM scheduled_jobs
                WHERE id = ?
                """,
                (job_id,),
            ).fetchone()
            if candidate is None:
                return None
            active_occurrence_key = str(candidate["active_occurrence_key"] or "")
            active_schedule_revision = candidate["active_occurrence_schedule_revision"]
            active_next_run_at = candidate["active_occurrence_next_run_at"]
            active_started_at = candidate["active_occurrence_started_at"]
            active_job_type = candidate["active_occurrence_job_type"]
            active_schedule_identity_revision = candidate[
                "active_occurrence_schedule_identity_revision"
            ]
            schedule_identity_revision = candidate["schedule_identity_revision"]
            schedule_identity_is_valid = (
                isinstance(schedule_identity_revision, int)
                and not isinstance(schedule_identity_revision, bool)
                and schedule_identity_revision >= 0
            )
            has_no_active_evidence = all(
                candidate[field] is None
                for field in (
                    "active_occurrence_key",
                    "active_occurrence_schedule_revision",
                    "active_occurrence_next_run_at",
                    "active_occurrence_started_at",
                    "active_occurrence_job_type",
                    "active_occurrence_schedule_identity_revision",
                    "lease_token",
                    "lease_expires_at",
                )
            )
            if not schedule_identity_is_valid and has_no_active_evidence:
                schedule_identity_revision = 0
            key_is_valid = (
                re.fullmatch(r"scheduler-occurrence:v1:[0-9a-f]{64}", active_occurrence_key)
                is not None
            )
            origin_is_valid = not (
                isinstance(active_schedule_revision, bool)
                or not isinstance(active_schedule_revision, int)
                or type(active_next_run_at) is not str
                or not active_next_run_at
                or isinstance(active_schedule_identity_revision, bool)
                or not isinstance(active_schedule_identity_revision, int)
                or active_schedule_identity_revision < 0
            )
            if not origin_is_valid:
                # A syntactically valid pre-migration key cannot be rebound to
                # a possibly newer schedule. A sentinel revision lets the old
                # receipt retire without ever replacing the current due time.
                current_schedule_revision = candidate["schedule_revision"]
                active_schedule_revision = (
                    int(current_schedule_revision)
                    if not key_is_valid
                    and isinstance(current_schedule_revision, int)
                    and not isinstance(current_schedule_revision, bool)
                    and current_schedule_revision >= 0
                    else -1
                )
                active_next_run_at = str(candidate["next_run_at"])
                active_schedule_identity_revision = (
                    int(schedule_identity_revision)
                    if not key_is_valid
                    and isinstance(schedule_identity_revision, int)
                    and not isinstance(schedule_identity_revision, bool)
                    and schedule_identity_revision >= 0
                    else -1
                )
            if key_is_valid:
                missing_started_at = active_started_at in (None, "")
                missing_job_type = active_job_type in (None, "")
                if not missing_started_at:
                    try:
                        datetime.fromisoformat(str(active_started_at).replace("Z", "+00:00"))
                    except ValueError:
                        return None
                if not missing_job_type and (
                    type(active_job_type) is not str
                    or SCHEDULED_JOB_TYPE_RE.fullmatch(active_job_type) is None
                ):
                    return None
                if (
                    missing_started_at
                    or missing_job_type
                    or active_schedule_identity_revision == -1
                ):
                    # A pre-migration occurrence without immutable execution
                    # type/date/identity cannot be rebound to a later configuration.
                    # Retire it through the normal fenced path without effects.
                    if missing_started_at:
                        active_started_at = checked_at_iso
                    active_job_type = LEGACY_UNKNOWN_SCHEDULED_JOB_TYPE
            else:
                active_started_at = checked_at_iso
                active_job_type = candidate["job_type"]
                if (
                    type(active_job_type) is not str
                    or SCHEDULED_JOB_TYPE_RE.fullmatch(active_job_type) is None
                ):
                    return None
            if not key_is_valid:
                occurrence_material = json.dumps(
                    {
                        "job_id": int(candidate["id"]),
                        "next_run_at": active_next_run_at,
                        "schedule_identity_revision": active_schedule_identity_revision,
                        "schedule_revision": active_schedule_revision,
                    },
                    sort_keys=True,
                    separators=(",", ":"),
                )
                active_occurrence_key = (
                    "scheduler-occurrence:v1:"
                    + hashlib.sha256(occurrence_material.encode("utf-8")).hexdigest()
                )
            params: list[Any] = [
                lease_token,
                lease_expires_at,
                active_occurrence_key,
                active_schedule_revision,
                active_next_run_at,
                active_started_at,
                active_job_type,
                active_schedule_identity_revision,
                utc_now(),
                job_id,
                checked_at_iso,
            ]
            if due_before is not None:
                due_clause = " AND enabled = 1 AND next_run_at <= ?"
                params.append(due_before)
            cur = conn.execute(
                f"""
                UPDATE scheduled_jobs
                SET schedule_identity_revision = CASE
                        WHEN (typeof(schedule_identity_revision) != 'integer'
                              OR schedule_identity_revision < 0)
                         AND active_occurrence_key IS NULL
                         AND active_occurrence_schedule_revision IS NULL
                         AND active_occurrence_next_run_at IS NULL
                         AND active_occurrence_started_at IS NULL
                         AND active_occurrence_job_type IS NULL
                         AND active_occurrence_schedule_identity_revision IS NULL
                         AND lease_token IS NULL
                         AND lease_expires_at IS NULL THEN 0
                        ELSE schedule_identity_revision
                    END,
                    lease_token = ?, lease_expires_at = ?, active_occurrence_key = ?,
                    active_occurrence_schedule_revision = ?, active_occurrence_next_run_at = ?,
                    active_occurrence_started_at = ?,
                    active_occurrence_job_type = ?,
                    active_occurrence_schedule_identity_revision = ?,
                    updated_at = ?
                WHERE id = ?
                  AND (lease_expires_at IS NULL OR lease_expires_at <= ?)
                  {due_clause}
                """,
                params,
            )
            if cur.rowcount != 1:
                return None
            return conn.execute(
                "SELECT * FROM scheduled_jobs WHERE id = ? AND lease_token = ?",
                (job_id, lease_token),
            ).fetchone()

    def renew_job_claim(
        self,
        job_id: int,
        lease_token: str,
        lease_seconds: float,
        *,
        now: datetime | None = None,
    ) -> bool:
        """Extend a live claim without allowing an expired owner to revive it."""
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            checked_at = now if now is not None else datetime.now()
            checked_at_iso = checked_at.isoformat(timespec="microseconds")
            lease_expires_at = (checked_at + timedelta(seconds=lease_seconds)).isoformat(timespec="microseconds")
            cur = conn.execute(
                """
                UPDATE scheduled_jobs
                SET lease_expires_at = ?, updated_at = ?
                WHERE id = ?
                  AND lease_token = ?
                  AND lease_expires_at > ?
                """,
                (lease_expires_at, utc_now(), job_id, lease_token, checked_at_iso),
            )
            return cur.rowcount == 1

    def job_claim_is_live(
        self,
        job_id: int,
        lease_token: str,
        *,
        now: datetime | None = None,
    ) -> bool:
        """Check exact unexpired ownership without acquiring a writer transaction."""
        with self.connect() as conn:
            row = conn.execute(
                "SELECT lease_token, lease_expires_at FROM scheduled_jobs WHERE id = ?",
                (job_id,),
            ).fetchone()
        if (
            row is None
            or type(lease_token) is not str
            or not lease_token
            or type(row["lease_token"]) is not str
            or not secrets.compare_digest(str(row["lease_token"]), lease_token)
        ):
            return False
        try:
            expires_at = datetime.fromisoformat(str(row["lease_expires_at"]))
        except (TypeError, ValueError):
            return False
        checked_at = now if now is not None else (
            datetime.now(tz=expires_at.tzinfo) if expires_at.tzinfo else datetime.now()
        )
        if checked_at.tzinfo is None and expires_at.tzinfo is not None:
            checked_at = checked_at.replace(tzinfo=expires_at.tzinfo)
        elif checked_at.tzinfo is not None and expires_at.tzinfo is None:
            expires_at = expires_at.replace(tzinfo=checked_at.tzinfo)
        return expires_at > checked_at

    def release_job_claim(
        self,
        job_id: int,
        lease_token: str,
        *,
        now: datetime | None = None,
    ) -> bool:
        """Release a live claim without changing the job's schedule."""
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            checked_at = (now if now is not None else datetime.now()).isoformat(timespec="microseconds")
            cur = conn.execute(
                """
                UPDATE scheduled_jobs
                SET lease_token = NULL, lease_expires_at = NULL, updated_at = ?
                WHERE id = ?
                  AND lease_token = ?
                  AND lease_expires_at > ?
                """,
                (utc_now(), job_id, lease_token, checked_at),
            )
            return cur.rowcount == 1

    def mark_claimed_job_run(
        self,
        job_id: int,
        lease_token: str,
        last_run_at: str,
        next_run_at: str,
        expected_schedule_revision: int,
        *,
        complete_occurrence: bool = True,
        now: datetime | None = None,
        run_history_event: dict[str, Any] | None = None,
        expected_occurrence_key: str | None = None,
        source_job_type: str | None = None,
        scheduled_note_publications: list[dict[str, Any]] | None = None,
    ) -> bool:
        """Record a claimed run while preserving any newer schedule revision."""
        normalized_run_event = None
        if run_history_event is not None:
            normalized_run_event = _scheduled_job_run_event(run_history_event)
        if normalized_run_event is not None and expected_occurrence_key is not None:
            run_occurrence_key = normalized_run_event["occurrence_key"]
            if (
                run_occurrence_key != expected_occurrence_key
                and run_occurrence_key != f"scheduled:{expected_occurrence_key}"
                and not (
                    source_job_type == MORNING_BRIEF_SCHEDULED_JOB_TYPE
                    and re.fullmatch(r"morning:[0-9a-f]{32}", run_occurrence_key) is not None
                )
            ):
                raise ValueError("scheduled run history does not match the claimed occurrence")
        normalized_note_plans = self._validate_scheduled_note_publication_plans(
            scheduled_note_publications
        )
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            checked_at = (now if now is not None else datetime.now()).isoformat(timespec="microseconds")
            job = conn.execute(
                """
                SELECT id, name, metadata, job_type, active_occurrence_key,
                       active_occurrence_schedule_revision, schedule_identity_revision,
                       active_occurrence_job_type,
                       active_occurrence_schedule_identity_revision
                FROM scheduled_jobs
                WHERE id = ?
                  AND lease_token = ?
                  AND lease_expires_at > ?
                """,
                (job_id, lease_token, checked_at),
            ).fetchone()
            if job is None:
                return False
            if expected_occurrence_key is not None and (
                type(job["active_occurrence_key"]) is not str
                or not secrets.compare_digest(str(job["active_occurrence_key"]), expected_occurrence_key)
                or job["active_occurrence_schedule_revision"] != expected_schedule_revision
            ):
                return False
            identity_matches_now = (
                type(job["schedule_identity_revision"]) is int
                and job["schedule_identity_revision"] >= 0
                and type(job["active_occurrence_schedule_identity_revision"]) is int
                and job["active_occurrence_schedule_identity_revision"] >= 0
                and job["schedule_identity_revision"]
                == job["active_occurrence_schedule_identity_revision"]
            )
            if (
                source_job_type is not None
                and (
                    type(job["active_occurrence_job_type"]) is not str
                    or not secrets.compare_digest(
                        str(job["active_occurrence_job_type"]), source_job_type
                    )
                )
            ):
                return False
            authoritative_job_type = job["active_occurrence_job_type"]
            if type(authoritative_job_type) is not str or not authoritative_job_type:
                return False
            if normalized_run_event is not None and (
                normalized_run_event["job_type"] != authoritative_job_type
                or normalized_run_event["schedule_identity_revision"]
                != job["active_occurrence_schedule_identity_revision"]
            ):
                return False
            authoritative_occurrence_key = job["active_occurrence_key"]
            for plan in normalized_note_plans:
                if (
                    type(authoritative_occurrence_key) is not str
                    or plan["occurrence_key"] != authoritative_occurrence_key
                    or plan["source_job_id"] != int(job["id"])
                    or plan["job_name"] != str(job["name"])
                    or plan["job_type"] != authoritative_job_type
                ):
                    raise ValueError(
                        "scheduled note publication does not match the claimed occurrence"
                    )
            metadata_json = str(job["metadata"] or "{}")
            if normalized_run_event is not None:
                metadata_json = json.dumps(
                    _job_metadata_with_run_event(metadata_json, normalized_run_event),
                    sort_keys=True,
                )
            identity_matches = (
                "typeof(schedule_identity_revision) = 'integer' "
                "AND schedule_identity_revision >= 0 "
                "AND typeof(active_occurrence_schedule_identity_revision) = 'integer' "
                "AND active_occurrence_schedule_identity_revision >= 0 "
                "AND schedule_identity_revision = active_occurrence_schedule_identity_revision"
            )
            if complete_occurrence:
                occurrence_assignment = (
                    "active_occurrence_key = NULL, active_occurrence_schedule_revision = NULL, "
                    "active_occurrence_next_run_at = NULL, "
                    "active_occurrence_started_at = NULL, "
                    "active_occurrence_job_type = NULL, "
                    "active_occurrence_schedule_identity_revision = NULL,"
                )
            else:
                occurrence_assignment = (
                    f"active_occurrence_key = CASE WHEN {identity_matches} "
                    "THEN active_occurrence_key ELSE NULL END, "
                    f"active_occurrence_schedule_revision = CASE WHEN {identity_matches} "
                    "THEN active_occurrence_schedule_revision ELSE NULL END, "
                    f"active_occurrence_next_run_at = CASE WHEN {identity_matches} "
                    "THEN active_occurrence_next_run_at ELSE NULL END, "
                    f"active_occurrence_started_at = CASE WHEN {identity_matches} "
                    "THEN active_occurrence_started_at ELSE NULL END, "
                    f"active_occurrence_job_type = CASE WHEN {identity_matches} "
                    "THEN active_occurrence_job_type ELSE NULL END, "
                    f"active_occurrence_schedule_identity_revision = CASE WHEN {identity_matches} "
                    "THEN active_occurrence_schedule_identity_revision ELSE NULL END,"
                )
            cur = conn.execute(
                f"""
                UPDATE scheduled_jobs
                SET last_run_at = ?,
                    next_run_at = CASE
                        WHEN {identity_matches} THEN ?
                        ELSE next_run_at
                    END,
                    {occurrence_assignment}
                    lease_token = NULL,
                    lease_expires_at = NULL,
                    metadata = ?,
                    updated_at = ?
                WHERE id = ?
                  AND lease_token = ?
                  AND lease_expires_at > ?
                """,
                (
                    last_run_at,
                    next_run_at,
                    metadata_json,
                    utc_now(),
                    job_id,
                    lease_token,
                    checked_at,
                ),
            )
            if cur.rowcount != 1:
                return False
            ledger_now = utc_now()
            for plan in normalized_note_plans:
                self._prepare_scheduled_note_publication_on_connection(
                    conn,
                    plan,
                    now=ledger_now,
                )
            return True

    def mark_job_run(self, job_id: int, last_run_at: str, next_run_at: str) -> bool:
        """Apply an operator schedule update without invalidating a live lease."""
        with self.connect() as conn:
            cur = conn.execute(
                f"""
                UPDATE scheduled_jobs
                SET last_run_at = ?, next_run_at = ?,
                    schedule_revision = schedule_revision + 1,
                    schedule_identity_revision = {_SCHEDULE_IDENTITY_MUTATION_SQL},
                    updated_at = ?
                WHERE id = ?
                """,
                (last_run_at, next_run_at, utc_now(), job_id),
            )
            return cur.rowcount == 1

    def update_job_metadata(self, job_id: int, metadata: dict[str, Any]) -> None:
        metadata_json = json.dumps(metadata or {}, sort_keys=True)
        with self.connect() as conn:
            conn.execute(
                "UPDATE scheduled_jobs SET metadata = ?, updated_at = ? WHERE id = ?",
                (metadata_json, utc_now(), job_id),
            )

    def converge_job_run_history(
        self,
        job_id: int,
        occurrence_key: str,
        status: str,
        *,
        updates: dict[str, Any] | None = None,
    ) -> bool:
        """Converge one existing occurrence receipt without appending a duplicate."""
        if (
            type(occurrence_key) is not str
            or SCHEDULED_JOB_RUN_OCCURRENCE_RE.fullmatch(occurrence_key) is None
        ):
            raise ValueError("scheduled job run occurrence key is invalid")
        if type(status) is not str or status not in {"ok", "skipped", "failed"}:
            raise ValueError("scheduled job terminal run status is invalid")
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                "SELECT metadata, last_run_at FROM scheduled_jobs WHERE id = ?",
                (job_id,),
            ).fetchone()
            if row is None:
                return False
            try:
                parsed = json.loads(row["metadata"] or "{}")
            except (TypeError, ValueError, json.JSONDecodeError):
                parsed = {}
            metadata = parsed if isinstance(parsed, dict) else {}
            schema_three = metadata.get("run_history_schema") == 3
            raw_history = metadata.get("run_history")
            raw_legacy = metadata.get("run_history_legacy")
            history: list[dict[str, Any]] = []
            legacy_history: list[dict[str, str]] = []
            target: dict[str, Any] | dict[str, str] | None = None
            seen: set[str] = set()
            if schema_three and isinstance(raw_history, list):
                for item in raw_history:
                    normalized = _legacy_scheduled_job_run_event(item)
                    if normalized is None:
                        continue
                    key = normalized["occurrence_key"]
                    if key in seen:
                        continue
                    seen.add(key)
                    if key == occurrence_key:
                        target = {**normalized, "status": status}
                        history.append(target)
                    else:
                        history.append(normalized)
            legacy_sources: list[object] = []
            if isinstance(raw_legacy, list):
                legacy_sources.extend(raw_legacy)
            if not schema_three and isinstance(raw_history, list):
                legacy_sources.extend(raw_history)
            legacy_seen: set[str] = set()
            for item in legacy_sources:
                normalized = _untyped_scheduled_job_run_event(item)
                if normalized is None:
                    continue
                key = normalized["occurrence_key"]
                if key in legacy_seen or key in seen:
                    continue
                legacy_seen.add(key)
                if target is None and key == occurrence_key:
                    target = {**normalized, "status": status}
                    legacy_history.append(target)
                else:
                    legacy_history.append(normalized)
            if target is None:
                return False
            metadata.update(updates or {})
            if schema_three:
                metadata["run_history"] = history[-MAX_SCHEDULED_JOB_RUN_HISTORY:]
                metadata["run_history_schema"] = 3
                if legacy_history:
                    metadata["run_history_legacy_schema"] = 2
                    metadata["run_history_legacy"] = legacy_history[-MAX_SCHEDULED_JOB_RUN_HISTORY:]
                else:
                    metadata.pop("run_history_legacy_schema", None)
                    metadata.pop("run_history_legacy", None)
            else:
                metadata["run_history"] = legacy_history[-MAX_SCHEDULED_JOB_RUN_HISTORY:]
                metadata.pop("run_history_legacy_schema", None)
                metadata.pop("run_history_legacy", None)
            if row["last_run_at"] == target["ran_at"]:
                metadata["last_run_status"] = status
                metadata["last_run_status_at"] = target["ran_at"]
            cur = conn.execute(
                "UPDATE scheduled_jobs SET metadata = ?, updated_at = ? WHERE id = ?",
                (json.dumps(metadata, sort_keys=True), utc_now(), job_id),
            )
            return cur.rowcount == 1

    def append_job_run_history_event(
        self,
        job_id: int,
        event: dict[str, Any],
        *,
        expected_last_run_at: str,
    ) -> bool:
        """Append one typed occurrence receipt without losing parallel metadata updates."""
        normalized_event = _scheduled_job_run_event(event)
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                "SELECT metadata, last_run_at FROM scheduled_jobs WHERE id = ?",
                (job_id,),
            ).fetchone()
            if row is None or row["last_run_at"] != expected_last_run_at:
                return False
            metadata = _job_metadata_with_run_event(row["metadata"], normalized_event)
            cur = conn.execute(
                "UPDATE scheduled_jobs SET metadata = ?, updated_at = ? WHERE id = ?",
                (json.dumps(metadata, sort_keys=True), utc_now(), job_id),
            )
            return cur.rowcount == 1

    def merge_job_metadata(
        self,
        job_id: int,
        updates: dict[str, Any] | None = None,
        *,
        append: dict[str, tuple[Any, int]] | None = None,
        expected_last_run_at: str | None = None,
        expected_next_run_at: str | None = None,
    ) -> bool:
        """Atomically merge metadata and append bounded list values for one job."""
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                "SELECT metadata, last_run_at, next_run_at FROM scheduled_jobs WHERE id = ?",
                (job_id,),
            ).fetchone()
            if row is None:
                return False
            if expected_last_run_at is not None and row["last_run_at"] != expected_last_run_at:
                return False
            if expected_next_run_at is not None and row["next_run_at"] != expected_next_run_at:
                return False
            try:
                parsed = json.loads(row["metadata"] or "{}")
            except (TypeError, ValueError, json.JSONDecodeError):
                parsed = {}
            metadata = parsed if isinstance(parsed, dict) else {}
            metadata.update(updates or {})
            for key, (value, limit) in (append or {}).items():
                current = metadata.get(key)
                values = list(current) if isinstance(current, list) else []
                values.append(value)
                metadata[key] = values[-max(int(limit), 1) :]
            cur = conn.execute(
                "UPDATE scheduled_jobs SET metadata = ?, updated_at = ? WHERE id = ?",
                (json.dumps(metadata, sort_keys=True), utc_now(), job_id),
            )
            return cur.rowcount == 1

    def save_browser_page(self, url: str, title: str, text: str) -> int:
        with self.connect() as conn:
            conn.execute("DELETE FROM browser_pages WHERE url = ?", (url,))
            cur = conn.execute(
                "INSERT INTO browser_pages(url, title, text, fetched_at) VALUES (?, ?, ?, ?)",
                (url, title, text, utc_now()),
            )
            return int(cur.lastrowid)

    def recent_browser_pages(self, limit: int = 10) -> list[sqlite3.Row]:
        with self.connect() as conn:
            return list(conn.execute("SELECT * FROM browser_pages ORDER BY fetched_at DESC LIMIT ?", (limit,)))

    def get_browser_page(self, page_id: int | None = None) -> sqlite3.Row | None:
        with self.connect() as conn:
            if page_id is not None:
                return conn.execute("SELECT * FROM browser_pages WHERE id = ?", (page_id,)).fetchone()
            return conn.execute("SELECT * FROM browser_pages ORDER BY fetched_at DESC LIMIT 1").fetchone()

    def set_job_enabled(
        self,
        name: str,
        enabled: bool,
        *,
        metadata_updates: dict[str, Any] | None = None,
        remove_metadata_keys: Iterable[str] = (),
        expected_schedule_revision: int | None = None,
        metadata_on_state_change_only: bool = False,
        cancel_active_claim: bool = False,
    ) -> bool:
        remove_keys = tuple(str(key) for key in remove_metadata_keys)
        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            rows = list(
                conn.execute(
                    "SELECT id, enabled, schedule_revision, metadata FROM scheduled_jobs WHERE lower(name) = lower(?)",
                    (name,),
                )
            )
            updated = 0
            target_enabled = 1 if enabled else 0
            for row in rows:
                if (
                    expected_schedule_revision is not None
                    and row["schedule_revision"] != expected_schedule_revision
                ):
                    continue
                if metadata_on_state_change_only and row["enabled"] == target_enabled:
                    updated += 1
                    continue
                metadata_json = row["metadata"]
                if metadata_updates is not None or remove_keys:
                    try:
                        parsed = json.loads(metadata_json or "{}")
                    except (TypeError, ValueError, json.JSONDecodeError):
                        parsed = {}
                    metadata = parsed if isinstance(parsed, dict) else {}
                    for key in remove_keys:
                        metadata.pop(key, None)
                    metadata.update(metadata_updates or {})
                    metadata_json = json.dumps(metadata, sort_keys=True)
                state_changed = row["enabled"] != target_enabled or metadata_json != row["metadata"]
                conn.execute(
                    """
                    UPDATE scheduled_jobs
                    SET enabled = ?,
                        metadata = ?,
                        schedule_revision = schedule_revision + ?,
                        lease_token = CASE WHEN ? THEN NULL ELSE lease_token END,
                        lease_expires_at = CASE WHEN ? THEN NULL ELSE lease_expires_at END,
                        updated_at = ?
                    WHERE id = ?
                    """,
                    (
                        target_enabled,
                        metadata_json,
                        1 if state_changed else 0,
                        1 if cancel_active_claim else 0,
                        1 if cancel_active_claim else 0,
                        now,
                        row["id"],
                    ),
                )
                updated += 1
            return updated > 0

    def delete_job(self, name: str) -> bool:
        now = utc_now()
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            if conn.execute(
                "SELECT 1 FROM scheduled_jobs WHERE lower(name) = lower(?) LIMIT 1",
                (name,),
            ).fetchone() is None:
                return False
            conn.execute(
                """
                UPDATE scheduled_note_publications
                SET state = 'failed',
                    payload = NULL,
                    attempt_token = NULL,
                    claimed_at = NULL,
                    effect_started_at = NULL,
                    finished_at = ?,
                    error_code = 'job_deleted_before_publish',
                    path_display = NULL,
                    content_sha256 = NULL,
                    updated_at = ?
                WHERE job_id IN (
                    SELECT id FROM scheduled_jobs WHERE lower(name) = lower(?)
                )
                  AND state IN ('prepared', 'claimed')
                  AND effect_started_at IS NULL
                """,
                (now, now, name),
            )
            conn.execute(
                """
                UPDATE scheduled_note_publications
                SET allow_disabled = 1, updated_at = ?
                WHERE job_id IN (
                    SELECT id FROM scheduled_jobs WHERE lower(name) = lower(?)
                )
                  AND state IN ('prepared', 'claimed')
                  AND effect_started_at IS NOT NULL
                """,
                (now, name),
            )
            conn.execute(
                """
                UPDATE scheduled_deliveries
                SET state = 'failed',
                    payload = NULL,
                    next_attempt_at = NULL,
                    attempt_token = NULL,
                    claimed_at = NULL,
                    sending_at = NULL,
                    finished_at = ?,
                    error_code = 'job_deleted_before_send',
                    telegram_message_id = NULL,
                    updated_at = ?
                WHERE job_id IN (
                    SELECT id FROM scheduled_jobs WHERE lower(name) = lower(?)
                )
                  AND state IN ('prepared', 'claimed', 'rejected')
                """,
                (now, now, name),
            )
            cur = conn.execute(
                "DELETE FROM scheduled_jobs WHERE lower(name) = lower(?)",
                (name,),
            )
            return cur.rowcount > 0

    @staticmethod
    def _goal_projection_steps(
        conn: sqlite3.Connection,
        goal_id: int,
    ) -> tuple[sqlite3.Row, ...]:
        return tuple(
            conn.execute(
                "SELECT * FROM goal_steps WHERE goal_id = ? ORDER BY id",
                (goal_id,),
            )
        )

    @staticmethod
    def _goal_projection_target(
        conn: sqlite3.Connection,
        goal_row: sqlite3.Row,
        *,
        steps: tuple[sqlite3.Row, ...] | None = None,
    ) -> GoalProjectionTarget:
        goal_id = _goal_projection_positive_int(goal_row["id"], field="goal id")
        revision = _goal_projection_positive_int(
            goal_row["revision"], field="goal revision"
        )
        if steps is None:
            steps = MemoryStore._goal_projection_steps(conn, goal_id)
        return GoalProjectionTarget(
            goal_id=goal_id,
            revision=revision,
            source_digest=goal_projection_source_digest(
                goal_id,
                revision,
                goal_row["title"],
                goal_row["purpose"],
                goal_row["horizon"],
                goal_row["status"],
                goal_row["created_at"],
                goal_row["updated_at"],
                steps,
            ),
        )

    @staticmethod
    def _upsert_goal_projection_job(
        conn: sqlite3.Connection,
        goal_row: sqlite3.Row,
        *,
        now: str,
    ) -> GoalProjectionTarget:
        target = MemoryStore._goal_projection_target(conn, goal_row)
        store_identity = MemoryStore._memory_projection_store_identity(conn)
        existing = conn.execute(
            "SELECT * FROM goal_projection_jobs WHERE goal_id = ?",
            (target.goal_id,),
        ).fetchone()
        if existing is not None:
            if existing["store_identity"] != store_identity:
                raise RuntimeError("goal projection job belongs to another store")
            if int(existing["goal_revision"]) > target.revision:
                raise RuntimeError("goal projection job is newer than its source")
            if (
                int(existing["goal_revision"]) == target.revision
                and existing["source_digest"] == target.source_digest
            ):
                return target
            prior_content_digest = (
                existing["content_digest"]
                if existing["state"] == "completed"
                else existing["prior_content_digest"]
            )
            prepared_content_digests = (
                "[]"
                if existing["state"] == "completed"
                else _goal_projection_digest_history_json(
                    _goal_projection_digest_history(
                        existing["prepared_content_digests"]
                    )
                )
            )
            created_at = (
                str(existing["created_at"])
                if existing["state"] == "pending"
                else now
            )
        else:
            prior_content_digest = None
            prepared_content_digests = "[]"
            created_at = now
        upserted = conn.execute(
            """
            INSERT INTO goal_projection_jobs(
                goal_id, store_identity, state, goal_revision, source_digest,
                path_display, content_digest, prepared_content_digest,
                prepared_content_digests, prior_content_digest, last_error_code,
                created_at, updated_at, completed_at
            ) VALUES (?, ?, 'pending', ?, ?, NULL, NULL, NULL, ?, ?, NULL, ?, ?, NULL)
            ON CONFLICT(goal_id) DO UPDATE SET
                store_identity = excluded.store_identity,
                state = 'pending',
                goal_revision = excluded.goal_revision,
                source_digest = excluded.source_digest,
                path_display = NULL,
                content_digest = NULL,
                prepared_content_digest = NULL,
                prepared_content_digests = excluded.prepared_content_digests,
                prior_content_digest = excluded.prior_content_digest,
                last_error_code = NULL,
                created_at = excluded.created_at,
                updated_at = excluded.updated_at,
                completed_at = NULL
            """,
            (
                target.goal_id,
                store_identity,
                target.revision,
                target.source_digest,
                prepared_content_digests,
                prior_content_digest,
                created_at,
                now,
            ),
        )
        if upserted.rowcount != 1:
            raise RuntimeError("goal projection job could not be reserved")
        return target

    @staticmethod
    def _coerce_goal_projection_target(
        target: GoalProjectionTarget,
    ) -> GoalProjectionTarget:
        if not isinstance(target, GoalProjectionTarget):
            raise ValueError("invalid goal projection target")
        return GoalProjectionTarget(
            goal_id=_goal_projection_positive_int(target.goal_id, field="goal id"),
            revision=_goal_projection_positive_int(
                target.revision, field="goal revision"
            ),
            source_digest=_goal_projection_digest(
                target.source_digest, field="source digest"
            ),
        )

    def create_goal(self, record: GoalRecord) -> int:
        with _goal_source_authority_fence(self.db_path), self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            now = utc_now()
            cur = conn.execute(
                """
                INSERT INTO goals(
                    title, purpose, horizon, status, revision, created_at, updated_at
                ) VALUES (?, ?, ?, ?, 1, ?, ?)
                """,
                (record.title, record.purpose, record.horizon, record.status, now, now),
            )
            goal_id = int(cur.lastrowid)
            goal = conn.execute(
                "SELECT * FROM goals WHERE id = ?", (goal_id,)
            ).fetchone()
            if goal is None:
                raise RuntimeError("created goal row is unavailable")
            self._upsert_goal_projection_job(conn, goal, now=now)
            return goal_id

    def list_goals(self, status: str | None = None, limit: int = 50) -> list[sqlite3.Row]:
        with self.connect() as conn:
            if status:
                return list(
                    conn.execute(
                        "SELECT * FROM goals WHERE lower(status) = lower(?) ORDER BY updated_at DESC LIMIT ?",
                        (status, limit),
                    )
                )
            return list(conn.execute("SELECT * FROM goals ORDER BY updated_at DESC LIMIT ?", (limit,)))

    @staticmethod
    def _goal_nudge_snapshot_on_connection(
        conn: sqlite3.Connection,
        limit: int,
        stale_days: int = 7,
    ) -> GoalNudgeSnapshot:
        if type(limit) is not int or not 1 <= limit <= MAX_GOAL_NUDGE_GOALS:
            raise ValueError("goal nudge snapshot limit is invalid")
        if type(stale_days) is not int or not 1 <= stale_days <= 365:
            raise ValueError("goal nudge stale-day window is invalid")
        captured_at = utc_now()
        try:
            reference_time = datetime.fromisoformat(captured_at.removesuffix("Z"))
        except ValueError as exc:
            raise RuntimeError("goal nudge capture time is invalid") from exc
        cutoff = reference_time - timedelta(days=stale_days)
        goal_rows = tuple(
            conn.execute(
                """
                SELECT id,
                       substr(title, 1, ?) AS title,
                       substr(status, 1, 32) AS status,
                       revision,
                       substr(updated_at, 1, 96) AS updated_at,
                       CASE WHEN length(title) > ? OR length(status) > 32
                                  OR length(updated_at) > 96 THEN 1 ELSE 0 END AS _clipped
                FROM goals
                WHERE lower(status) = 'active'
                ORDER BY updated_at DESC, id DESC
                LIMIT ?
                """,
                (
                    MAX_GOAL_NUDGE_TITLE_CHARS,
                    MAX_GOAL_NUDGE_TITLE_CHARS,
                    limit + 1,
                ),
            )
        )
        goals = goal_rows[:limit]
        step_rows = tuple(
            conn.execute(
                """
                WITH selected_goals AS (
                    SELECT id
                    FROM goals
                    WHERE lower(status) = 'active'
                    ORDER BY updated_at DESC, id DESC
                    LIMIT ?
                ), ranked_steps AS (
                    SELECT goal_steps.id,
                           goal_steps.goal_id,
                           substr(goal_steps.body, 1, ?) AS body,
                           substr(goal_steps.status, 1, 32) AS status,
                           substr(goal_steps.updated_at, 1, 96) AS updated_at,
                           CASE WHEN length(goal_steps.body) > ?
                                      OR length(goal_steps.status) > 32
                                      OR length(goal_steps.updated_at) > 96
                                THEN 1 ELSE 0 END AS _clipped,
                           ROW_NUMBER() OVER (
                               PARTITION BY goal_steps.goal_id
                               ORDER BY goal_steps.id ASC
                           ) AS rank_within_goal
                    FROM goal_steps
                    JOIN selected_goals ON selected_goals.id = goal_steps.goal_id
                    WHERE lower(goal_steps.status) != 'done'
                )
                SELECT id, goal_id, body, status, updated_at, _clipped
                FROM ranked_steps
                WHERE rank_within_goal = 1
                ORDER BY goal_id ASC
                """,
                (
                    limit,
                    MAX_GOAL_NUDGE_STEP_BODY_CHARS,
                    MAX_GOAL_NUDGE_STEP_BODY_CHARS,
                ),
            )
        )
        goal_ids: set[int] = set()
        stale_goal_ids: list[int] = []
        manifest_goals: list[dict[str, Any]] = []
        for row in goals:
            if (
                type(row["id"]) is not int
                or row["id"] < 1
                or row["id"] in goal_ids
                or type(row["revision"]) is not int
                or row["revision"] < 1
            ):
                raise RuntimeError("goal nudge source rows are invalid")
            goal_ids.add(int(row["id"]))
            try:
                updated_at = datetime.fromisoformat(
                    str(row["updated_at"] or "").removesuffix("Z")
                )
            except ValueError as exc:
                raise RuntimeError("goal nudge source time is invalid") from exc
            stale = updated_at < cutoff
            if stale:
                stale_goal_ids.append(int(row["id"]))
            manifest_goals.append(
                {
                    "id": int(row["id"]),
                    "title": str(row["title"] or ""),
                    "status": str(row["status"] or ""),
                    "revision": int(row["revision"]),
                    "updated_at": str(row["updated_at"] or ""),
                    "stale": stale,
                    "clipped": bool(row["_clipped"]),
                }
            )
        seen_step_goals: set[int] = set()
        manifest_steps: list[dict[str, Any]] = []
        for row in step_rows:
            if (
                type(row["id"]) is not int
                or row["id"] < 1
                or type(row["goal_id"]) is not int
                or row["goal_id"] not in goal_ids
                or row["goal_id"] in seen_step_goals
            ):
                raise RuntimeError("goal nudge step source rows are invalid")
            seen_step_goals.add(int(row["goal_id"]))
            manifest_steps.append(
                {
                    "id": int(row["id"]),
                    "goal_id": int(row["goal_id"]),
                    "body": str(row["body"] or ""),
                    "status": str(row["status"] or ""),
                    "updated_at": str(row["updated_at"] or ""),
                    "clipped": bool(row["_clipped"]),
                }
            )
        truncated = len(goal_rows) > limit
        clipped = any(bool(row["_clipped"]) for row in goals + step_rows)
        material = json.dumps(
            {
                "version": 1,
                "limit": limit,
                "stale_days": stale_days,
                "truncated": truncated,
                "goals": manifest_goals,
                "open_steps": manifest_steps,
            },
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        )
        return GoalNudgeSnapshot(
            captured_at=captured_at,
            goals=goals,
            open_steps=step_rows,
            source_manifest_kind=GOAL_NUDGE_SOURCE_MANIFEST_KIND,
            source_manifest_digest=hashlib.sha256(material.encode("utf-8")).hexdigest(),
            stale_goal_ids=tuple(stale_goal_ids),
            truncated=truncated,
            clipped=clipped,
        )

    def read_goal_nudge_snapshot(
        self,
        limit: int = MAX_GOAL_NUDGE_GOALS,
        stale_days: int = 7,
    ) -> GoalNudgeSnapshot:
        """Capture the bounded goal and next-step source in one read transaction."""
        with self.connect() as conn:
            conn.execute("PRAGMA query_only = ON")
            conn.execute("BEGIN")
            return self._goal_nudge_snapshot_on_connection(conn, limit, stale_days)

    @staticmethod
    def _goal_nudge_source_manifest_is_current_on_connection(
        conn: sqlite3.Connection,
        source_manifest_kind: object,
        source_manifest_digest: object,
    ) -> bool:
        if (
            source_manifest_kind != GOAL_NUDGE_SOURCE_MANIFEST_KIND
            or type(source_manifest_digest) is not str
            or SCHEDULED_NOTE_PUBLICATION_KEY_RE.fullmatch(source_manifest_digest) is None
        ):
            return False
        snapshot = MemoryStore._goal_nudge_snapshot_on_connection(
            conn,
            MAX_GOAL_NUDGE_GOALS,
        )
        return secrets.compare_digest(
            source_manifest_digest,
            snapshot.source_manifest_digest,
        )

    @contextmanager
    def goal_nudge_publication_snapshot(
        self,
        limit: int = MAX_GOAL_NUDGE_GOALS,
        stale_days: int = 7,
    ) -> Generator[GoalNudgeSnapshot, None, None]:
        """Hold goal mutations until one directly requested nudge is durable."""
        with _goal_source_authority_fence(self.db_path):
            with self.connect() as conn:
                conn.execute("PRAGMA query_only = ON")
                conn.execute("BEGIN")
                snapshot = self._goal_nudge_snapshot_on_connection(
                    conn, limit, stale_days
                )
            yield snapshot

    @contextmanager
    def goal_source_effect_fence(self) -> Generator[None, None, None]:
        """Keep source-bound note or network effects coherent with goal mutations."""
        with _goal_source_authority_fence(self.db_path):
            yield

    @staticmethod
    def _daily_plan_snapshot_on_connection(
        conn: sqlite3.Connection,
    ) -> DailyPlanSnapshot:
        tasks = tuple(
            conn.execute(
                """
                SELECT id,
                       substr(body, 1, ?) AS body,
                       substr(due, 1, ?) AS due,
                       substr(priority, 1, ?) AS priority,
                       CASE WHEN length(body) > ? OR length(due) > ?
                                      OR length(priority) > ? THEN 1 ELSE 0 END AS _clipped
                FROM tasks
                WHERE lower(status) = 'open'
                ORDER BY
                    CASE lower(priority)
                        WHEN 'high' THEN 0
                        WHEN 'normal' THEN 1
                        WHEN 'low' THEN 2
                        ELSE 3
                    END,
                    CASE WHEN due = '' THEN 1 ELSE 0 END,
                    due ASC,
                    id ASC
                LIMIT ?
                """,
                (
                    MAX_DAILY_PLAN_TEXT_CHARS,
                    MAX_DAILY_PLAN_TIME_CHARS,
                    MAX_DAILY_PLAN_LABEL_CHARS,
                    MAX_DAILY_PLAN_TEXT_CHARS,
                    MAX_DAILY_PLAN_TIME_CHARS,
                    MAX_DAILY_PLAN_LABEL_CHARS,
                    MAX_DAILY_PLAN_TASKS,
                ),
            )
        )
        goal_limit = MAX_DAILY_PLAN_FOCUS_ITEMS - len(tasks)
        goals = tuple(
            conn.execute(
                """
                SELECT id,
                       substr(title, 1, ?) AS title,
                       CASE WHEN length(title) > ? THEN 1 ELSE 0 END AS _clipped
                FROM goals
                WHERE lower(status) = 'active'
                ORDER BY updated_at DESC, id DESC
                LIMIT ?
                """,
                (
                    MAX_DAILY_PLAN_TEXT_CHARS,
                    MAX_DAILY_PLAN_TEXT_CHARS,
                    goal_limit,
                ),
            )
        )
        goal_ids = tuple(int(goal["id"]) for goal in goals)
        if goal_ids:
            placeholders = ", ".join("?" for _ in goal_ids)
            open_steps = tuple(
                conn.execute(
                    f"""
                    WITH ranked_steps AS (
                        SELECT id,
                               goal_id,
                               substr(body, 1, ?) AS body,
                               CASE WHEN length(body) > ? THEN 1 ELSE 0 END AS _clipped,
                               ROW_NUMBER() OVER (
                                   PARTITION BY goal_id
                                   ORDER BY id ASC
                               ) AS rank_within_goal
                        FROM goal_steps
                        WHERE lower(status) != 'done'
                          AND goal_id IN ({placeholders})
                    )
                    SELECT id, goal_id, body, _clipped
                    FROM ranked_steps
                    WHERE rank_within_goal = 1
                    ORDER BY goal_id ASC
                    """,
                    (
                        MAX_DAILY_PLAN_TEXT_CHARS,
                        MAX_DAILY_PLAN_TEXT_CHARS,
                        *goal_ids,
                    ),
                )
            )
        else:
            open_steps = ()
        approvals = tuple(
            conn.execute(
                """
                SELECT id,
                       substr(tool_name, 1, ?) AS tool_name,
                       substr(user_input, 1, ?) AS user_input,
                       CASE WHEN length(tool_name) > ? OR length(user_input) > ?
                            THEN 1 ELSE 0 END AS _clipped
                FROM pending_approvals
                WHERE lower(status) = 'pending'
                ORDER BY id DESC
                LIMIT ?
                """,
                (
                    MAX_DAILY_PLAN_LABEL_CHARS,
                    MAX_DAILY_PLAN_TEXT_CHARS,
                    MAX_DAILY_PLAN_LABEL_CHARS,
                    MAX_DAILY_PLAN_TEXT_CHARS,
                    MAX_DAILY_PLAN_APPROVALS,
                ),
            )
        )
        jobs = tuple(
            conn.execute(
                """
                SELECT id,
                       substr(name, 1, ?) AS name,
                       substr(job_type, 1, ?) AS job_type,
                       enabled,
                       substr(next_run_at, 1, ?) AS next_run_at,
                       CASE WHEN length(name) > ? OR length(job_type) > ?
                                      OR length(next_run_at) > ? THEN 1 ELSE 0 END AS _clipped
                FROM scheduled_jobs
                ORDER BY next_run_at ASC, id ASC
                LIMIT ?
                """,
                (
                    MAX_DAILY_PLAN_LABEL_CHARS,
                    MAX_DAILY_PLAN_LABEL_CHARS,
                    MAX_DAILY_PLAN_TIME_CHARS,
                    MAX_DAILY_PLAN_LABEL_CHARS,
                    MAX_DAILY_PLAN_LABEL_CHARS,
                    MAX_DAILY_PLAN_TIME_CHARS,
                    MAX_DAILY_PLAN_JOBS,
                ),
            )
        )
        clipped_sources = tuple(
            name
            for name, rows in (
                ("tasks", tasks),
                ("goals", goals),
                ("goal_steps", open_steps),
                ("approvals", approvals),
                ("jobs", jobs),
            )
            if any(bool(row["_clipped"]) for row in rows)
        )
        return DailyPlanSnapshot(
            captured_at=utc_now(),
            tasks=tasks,
            goals=goals,
            open_steps=open_steps,
            approvals=approvals,
            jobs=jobs,
            clipped_sources=clipped_sources,
        )

    def read_daily_plan_snapshot(self) -> DailyPlanSnapshot:
        """Capture all rendered daily-plan sources in one read transaction."""
        with self.connect() as conn:
            conn.execute("PRAGMA query_only = ON")
            conn.execute("BEGIN")
            return self._daily_plan_snapshot_on_connection(conn)

    @contextmanager
    def daily_plan_publication_snapshot(
        self,
    ) -> Generator[DailyPlanSnapshot, None, None]:
        """Keep SQLite writers behind one daily-plan publication snapshot."""
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            yield self._daily_plan_snapshot_on_connection(conn)

    @staticmethod
    def _daily_brief_snapshot_on_connection(
        conn: sqlite3.Connection,
    ) -> DailyBriefSnapshot:
        memory_rows = tuple(
            conn.execute(
                """
                SELECT substr(memory.category, 1, ?) AS category,
                       substr(memory.title, 1, ?) AS title,
                       substr(memory.body, 1, ?) AS body,
                       -- Body uses the renderer's established 120-character excerpt;
                       -- only additional snapshot clipping belongs in Source Limits.
                       CASE WHEN length(memory.category) > ?
                                  OR length(memory.title) > ? THEN 1 ELSE 0 END AS _clipped
                FROM memories AS memory
                WHERE NOT EXISTS (
                    SELECT 1 FROM ingested_sources AS source
                    WHERE source.memory_id = memory.id
                      AND source.source_type = 'profile_note'
                )
                ORDER BY memory.created_at DESC, memory.id DESC
                LIMIT ?
                """,
                (
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_MEMORY_BODY_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_MEMORIES + 1,
                ),
            )
        )
        memories = memory_rows[:MAX_DAILY_BRIEF_MEMORIES]
        skill_rows = tuple(
            conn.execute(
                """
                SELECT substr(name, 1, ?) AS name,
                       substr(trigger, 1, ?) AS trigger,
                       CASE WHEN length(name) > ? OR length(trigger) > ?
                            THEN 1 ELSE 0 END AS _clipped
                FROM skills
                WHERE review_status = 'active'
                ORDER BY updated_at DESC, id DESC
                LIMIT ?
                """,
                (
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_TEXT_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_TEXT_CHARS,
                    MAX_DAILY_BRIEF_SKILLS + 1,
                ),
            )
        )
        skills = skill_rows[:MAX_DAILY_BRIEF_SKILLS]
        goal_rows = tuple(
            conn.execute(
                """
                SELECT id,
                       substr(title, 1, ?) AS title,
                       CASE WHEN length(title) > ? THEN 1 ELSE 0 END AS _clipped
                FROM goals
                WHERE lower(status) = 'active'
                ORDER BY updated_at DESC, id DESC
                LIMIT ?
                """,
                (
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_GOALS + 1,
                ),
            )
        )
        goals = goal_rows[:MAX_DAILY_BRIEF_GOALS]
        goal_ids = tuple(int(goal["id"]) for goal in goals)
        if goal_ids:
            placeholders = ", ".join("?" for _ in goal_ids)
            open_steps = tuple(
                conn.execute(
                    f"""
                    WITH ranked_steps AS (
                        SELECT id,
                               goal_id,
                               substr(body, 1, ?) AS body,
                               CASE WHEN length(body) > ? THEN 1 ELSE 0 END AS _clipped,
                               ROW_NUMBER() OVER (
                                   PARTITION BY goal_id
                                   ORDER BY id ASC
                               ) AS rank_within_goal
                        FROM goal_steps
                        WHERE lower(status) != 'done'
                          AND goal_id IN ({placeholders})
                    )
                    SELECT id, goal_id, body, _clipped
                    FROM ranked_steps
                    WHERE rank_within_goal = 1
                    ORDER BY goal_id ASC
                    """,
                    (
                        MAX_DAILY_BRIEF_TEXT_CHARS,
                        MAX_DAILY_BRIEF_TEXT_CHARS,
                        *goal_ids,
                    ),
                )
            )
        else:
            open_steps = ()
        task_rows = tuple(
            conn.execute(
                """
                SELECT id,
                       substr(body, 1, ?) AS body,
                       substr(due, 1, ?) AS due,
                       substr(priority, 1, ?) AS priority,
                       CASE WHEN length(body) > ? OR length(due) > ?
                                  OR length(priority) > ? THEN 1 ELSE 0 END AS _clipped
                FROM tasks
                WHERE lower(status) = 'open'
                ORDER BY
                    CASE lower(priority)
                        WHEN 'high' THEN 0
                        WHEN 'normal' THEN 1
                        WHEN 'low' THEN 2
                        ELSE 3
                    END,
                    CASE WHEN due = '' THEN 1 ELSE 0 END,
                    due ASC,
                    id ASC
                LIMIT ?
                """,
                (
                    MAX_DAILY_BRIEF_TEXT_CHARS,
                    MAX_DAILY_BRIEF_TIME_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_TEXT_CHARS,
                    MAX_DAILY_BRIEF_TIME_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_TASKS + 1,
                ),
            )
        )
        tasks = task_rows[:MAX_DAILY_BRIEF_TASKS]
        approval_rows = tuple(
            conn.execute(
                """
                SELECT id,
                       substr(tool_name, 1, ?) AS tool_name,
                       substr(user_input, 1, ?) AS user_input,
                       CASE WHEN length(tool_name) > ? OR length(user_input) > ?
                            THEN 1 ELSE 0 END AS _clipped
                FROM pending_approvals
                WHERE lower(status) = 'pending'
                ORDER BY id DESC
                LIMIT ?
                """,
                (
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_TEXT_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_TEXT_CHARS,
                    MAX_DAILY_BRIEF_APPROVALS + 1,
                ),
            )
        )
        approvals = approval_rows[:MAX_DAILY_BRIEF_APPROVALS]
        decision_rows = tuple(
            conn.execute(
                """
                SELECT id,
                       substr(title, 1, ?) AS title,
                       substr(rationale, 1, ?) AS rationale,
                       CASE WHEN length(title) > ? OR length(rationale) > ?
                            THEN 1 ELSE 0 END AS _clipped
                FROM decisions
                WHERE lower(status) = 'active'
                ORDER BY id DESC
                LIMIT ?
                """,
                (
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_TEXT_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_TEXT_CHARS,
                    MAX_DAILY_BRIEF_DECISIONS + 1,
                ),
            )
        )
        decisions = decision_rows[:MAX_DAILY_BRIEF_DECISIONS]
        people_rows = tuple(
            conn.execute(
                """
                SELECT id,
                       substr(name, 1, ?) AS name,
                       substr(relation, 1, ?) AS relation,
                       substr(last_contact_at, 1, ?) AS last_contact_at,
                       CASE WHEN length(name) > ? OR length(relation) > ?
                                  OR length(last_contact_at) > ? THEN 1 ELSE 0 END AS _clipped
                FROM people
                ORDER BY updated_at DESC, id DESC
                LIMIT ?
                """,
                (
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_TIME_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_TIME_CHARS,
                    MAX_DAILY_BRIEF_PEOPLE + 1,
                ),
            )
        )
        people = people_rows[:MAX_DAILY_BRIEF_PEOPLE]
        preference_rows = tuple(
            conn.execute(
                """
                SELECT substr(category, 1, ?) AS category,
                       substr(key, 1, ?) AS key,
                       substr(value, 1, ?) AS value,
                       CASE WHEN length(category) > ? OR length(key) > ?
                                  OR length(value) > ? THEN 1 ELSE 0 END AS _clipped
                FROM preferences
                WHERE lower(status) = 'active'
                ORDER BY category ASC, key ASC, id ASC
                LIMIT ?
                """,
                (
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_TEXT_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_LABEL_CHARS,
                    MAX_DAILY_BRIEF_TEXT_CHARS,
                    MAX_DAILY_BRIEF_PREFERENCES + 1,
                ),
            )
        )
        preferences = preference_rows[:MAX_DAILY_BRIEF_PREFERENCES]
        bounded_sources = (
            ("memories", memory_rows, memories),
            ("skills", skill_rows, skills),
            ("goals", goal_rows, goals),
            ("tasks", task_rows, tasks),
            ("approvals", approval_rows, approvals),
            ("decisions", decision_rows, decisions),
            ("people", people_rows, people),
            ("preferences", preference_rows, preferences),
        )
        truncated_sources = tuple(
            name for name, rows, bounded in bounded_sources if len(rows) > len(bounded)
        )
        clipped_sources = tuple(
            name
            for name, rows in (
                ("memories", memories),
                ("skills", skills),
                ("goals", goals),
                ("goal_steps", open_steps),
                ("tasks", tasks),
                ("approvals", approvals),
                ("decisions", decisions),
                ("people", people),
                ("preferences", preferences),
            )
            if any(bool(row["_clipped"]) for row in rows)
        )
        return DailyBriefSnapshot(
            captured_at=utc_now(),
            memories=memories,
            skills=skills,
            goals=goals,
            open_steps=open_steps,
            tasks=tasks,
            approvals=approvals,
            decisions=decisions,
            people=people,
            preferences=preferences,
            truncated_sources=truncated_sources,
            clipped_sources=clipped_sources,
        )

    def read_daily_brief_snapshot(self) -> DailyBriefSnapshot:
        """Capture every rendered proactive-brief source in one read transaction."""
        with self.connect() as conn:
            conn.execute("PRAGMA query_only = ON")
            conn.execute("BEGIN")
            return self._daily_brief_snapshot_on_connection(conn)

    @contextmanager
    def daily_brief_publication_snapshot(
        self,
    ) -> Generator[DailyBriefSnapshot, None, None]:
        """Keep SQLite writers behind one direct daily-brief publication."""
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            yield self._daily_brief_snapshot_on_connection(conn)

    def read_self_knowledge_snapshot(self) -> SelfKnowledgeSnapshot:
        """Capture bounded current personal state in one read transaction.

        Only fields needed for a local personal-context preview leave this
        boundary. Person notes/interactions, task provenance, and completion
        history are deliberately excluded.
        """
        with self.connect() as conn:
            conn.execute("PRAGMA query_only = ON")
            conn.execute("BEGIN")
            captured_at = utc_now()
            goal_rows = tuple(
                conn.execute(
                    """
                    SELECT id,
                           substr(title, 1, 512) AS title,
                           substr(purpose, 1, 1024) AS purpose,
                           substr(horizon, 1, 160) AS horizon,
                           substr(status, 1, 32) AS status,
                           substr(updated_at, 1, 96) AS updated_at,
                           CASE WHEN length(title) > 512 OR length(purpose) > 1024
                                     OR length(horizon) > 160 OR length(status) > 32
                                     OR length(updated_at) > 96 THEN 1 ELSE 0 END AS _clipped
                    FROM goals
                    WHERE lower(status) = 'active'
                    ORDER BY updated_at DESC, id DESC
                    LIMIT ?
                    """,
                    (MAX_SELF_KNOWLEDGE_GOALS + 1,),
                )
            )
            goal_step_rows = tuple(
                conn.execute(
                    """
                    WITH selected_goals AS (
                        SELECT id
                        FROM goals
                        WHERE lower(status) = 'active'
                        ORDER BY updated_at DESC, id DESC
                        LIMIT ?
                    ), ranked_steps AS (
                        SELECT goal_steps.id, goal_steps.goal_id,
                               substr(goal_steps.body, 1, 1024) AS body,
                               substr(goal_steps.status, 1, 32) AS status,
                               substr(goal_steps.updated_at, 1, 96) AS updated_at,
                               CASE WHEN length(goal_steps.body) > 1024
                                         OR length(goal_steps.status) > 32
                                         OR length(goal_steps.updated_at) > 96
                                    THEN 1 ELSE 0 END AS _clipped,
                               ROW_NUMBER() OVER (
                                   PARTITION BY goal_steps.goal_id
                                   ORDER BY goal_steps.id ASC
                               ) AS rank_within_goal
                        FROM goal_steps
                        JOIN selected_goals ON selected_goals.id = goal_steps.goal_id
                        WHERE lower(goal_steps.status) = 'open'
                    )
                    SELECT id, goal_id, body, status, updated_at, _clipped
                    FROM ranked_steps
                    WHERE rank_within_goal <= ?
                    ORDER BY goal_id DESC, id ASC
                    """,
                    (
                        MAX_SELF_KNOWLEDGE_GOALS,
                        MAX_SELF_KNOWLEDGE_STEPS_PER_GOAL + 1,
                    ),
                )
            )
            task_rows = tuple(
                conn.execute(
                    """
                    SELECT id,
                           substr(body, 1, 1024) AS body,
                           substr(due, 1, 160) AS due,
                           substr(priority, 1, 32) AS priority,
                           substr(status, 1, 32) AS status,
                           substr(updated_at, 1, 96) AS updated_at,
                           CASE WHEN length(body) > 1024 OR length(due) > 160
                                     OR length(priority) > 32 OR length(status) > 32
                                     OR length(updated_at) > 96 THEN 1 ELSE 0 END AS _clipped
                    FROM tasks
                    WHERE lower(status) = 'open'
                    ORDER BY
                        CASE lower(priority)
                            WHEN 'high' THEN 0
                            WHEN 'normal' THEN 1
                            WHEN 'low' THEN 2
                            ELSE 3
                        END,
                        CASE WHEN due = '' THEN 1 ELSE 0 END,
                        due ASC,
                        id ASC
                    LIMIT ?
                    """,
                    (MAX_SELF_KNOWLEDGE_TASKS + 1,),
                )
            )
            decision_rows = tuple(
                conn.execute(
                    """
                    SELECT id,
                           substr(title, 1, 512) AS title,
                           substr(rationale, 1, 1024) AS rationale,
                           substr(impact, 1, 1024) AS impact,
                           substr(status, 1, 32) AS status,
                           revision,
                           substr(updated_at, 1, 96) AS updated_at,
                           CASE WHEN length(title) > 512 OR length(rationale) > 1024
                                     OR length(impact) > 1024 OR length(status) > 32
                                     OR length(updated_at) > 96 THEN 1 ELSE 0 END AS _clipped
                    FROM decisions
                    WHERE lower(status) = 'active'
                    ORDER BY id DESC
                    LIMIT ?
                    """,
                    (MAX_SELF_KNOWLEDGE_DECISIONS + 1,),
                )
            )
            people_rows = tuple(
                conn.execute(
                    """
                    SELECT id,
                           substr(name, 1, 512) AS name,
                           substr(relation, 1, 512) AS relation,
                           CASE WHEN last_contact_at IS NULL THEN NULL
                                ELSE substr(last_contact_at, 1, 160) END AS last_contact_at,
                           revision,
                           substr(updated_at, 1, 96) AS updated_at,
                           CASE WHEN length(name) > 512 OR length(relation) > 512
                                     OR length(COALESCE(last_contact_at, '')) > 160
                                     OR length(updated_at) > 96 THEN 1 ELSE 0 END AS _clipped
                    FROM people
                    ORDER BY id DESC
                    LIMIT ?
                    """,
                    (MAX_SELF_KNOWLEDGE_PEOPLE + 1,),
                )
            )
            goals = goal_rows[:MAX_SELF_KNOWLEDGE_GOALS]
            tasks = task_rows[:MAX_SELF_KNOWLEDGE_TASKS]
            decisions = decision_rows[:MAX_SELF_KNOWLEDGE_DECISIONS]
            people = people_rows[:MAX_SELF_KNOWLEDGE_PEOPLE]
            goal_steps_list: list[sqlite3.Row] = []
            goal_step_counts: dict[int, int] = {}
            goal_steps_truncated = False
            for row in goal_step_rows:
                goal_id = int(row["goal_id"])
                seen = goal_step_counts.get(goal_id, 0)
                if seen >= MAX_SELF_KNOWLEDGE_STEPS_PER_GOAL:
                    goal_steps_truncated = True
                    continue
                goal_step_counts[goal_id] = seen + 1
                goal_steps_list.append(row)
            truncated_sources = tuple(
                name
                for name, truncated in (
                    ("goals", len(goal_rows) > MAX_SELF_KNOWLEDGE_GOALS),
                    ("goal_steps", goal_steps_truncated),
                    ("tasks", len(task_rows) > MAX_SELF_KNOWLEDGE_TASKS),
                    ("decisions", len(decision_rows) > MAX_SELF_KNOWLEDGE_DECISIONS),
                    ("people", len(people_rows) > MAX_SELF_KNOWLEDGE_PEOPLE),
                )
                if truncated
            )
            clipped_sources = tuple(
                name
                for name, rows in (
                    ("goals", goals),
                    ("goal_steps", tuple(goal_steps_list)),
                    ("tasks", tasks),
                    ("decisions", decisions),
                    ("people", people),
                )
                if any(type(row["_clipped"]) is int and row["_clipped"] == 1 for row in rows)
            )
            return SelfKnowledgeSnapshot(
                captured_at=captured_at,
                goals=goals,
                goal_steps=tuple(goal_steps_list),
                tasks=tasks,
                decisions=decisions,
                people=people,
                truncated_sources=truncated_sources,
                clipped_sources=clipped_sources,
            )

    def get_goal(self, goal_id: int) -> sqlite3.Row | None:
        with self.connect() as conn:
            return conn.execute("SELECT * FROM goals WHERE id = ?", (goal_id,)).fetchone()

    def add_goal_step(self, goal_id: int, body: str) -> int | None:
        with _goal_source_authority_fence(self.db_path), self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            now = utc_now()
            goal = conn.execute("SELECT * FROM goals WHERE id = ?", (goal_id,)).fetchone()
            if goal is None:
                return None
            step_count = conn.execute(
                "SELECT COUNT(*) AS step_count FROM goal_steps WHERE goal_id = ?",
                (goal_id,),
            ).fetchone()
            if step_count is None or int(step_count["step_count"]) >= MAX_GOAL_PROJECTION_STEPS:
                raise RuntimeError("goal step projection limit is exceeded")
            cur = conn.execute(
                """
                INSERT INTO goal_steps(goal_id, body, status, created_at, updated_at)
                VALUES (?, ?, 'open', ?, ?)
                """,
                (goal_id, body, now, now),
            )
            advanced = conn.execute(
                """
                UPDATE goals
                SET revision = revision + 1, updated_at = ?
                WHERE id = ? AND typeof(revision) = 'integer'
                  AND revision BETWEEN 1 AND 9223372036854775806
                """,
                (now, goal_id),
            )
            if advanced.rowcount != 1:
                raise RuntimeError("goal revision could not be advanced")
            updated_goal = conn.execute(
                "SELECT * FROM goals WHERE id = ?", (goal_id,)
            ).fetchone()
            if updated_goal is None:
                raise RuntimeError("updated goal row is unavailable")
            self._upsert_goal_projection_job(conn, updated_goal, now=now)
            return int(cur.lastrowid)

    def list_goal_steps(self, goal_id: int) -> list[sqlite3.Row]:
        with self.connect() as conn:
            return list(
                conn.execute(
                    "SELECT * FROM goal_steps WHERE goal_id = ? ORDER BY id ASC",
                    (goal_id,),
                )
            )

    def get_goal_step(self, step_id: int) -> sqlite3.Row | None:
        with self.connect() as conn:
            return conn.execute("SELECT * FROM goal_steps WHERE id = ?", (step_id,)).fetchone()

    @contextmanager
    def goal_mirror_snapshot(
        self, goal_id: int
    ) -> Generator[tuple[sqlite3.Row | None, list[sqlite3.Row]], None, None]:
        """Hold the SQLite write fence until one goal mirror is published."""
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            goal = conn.execute("SELECT * FROM goals WHERE id = ?", (goal_id,)).fetchone()
            steps = (
                list(
                    conn.execute(
                        "SELECT * FROM goal_steps WHERE goal_id = ? ORDER BY id ASC",
                        (goal_id,),
                    )
                )
                if goal is not None
                else []
            )
            yield goal, steps

    @staticmethod
    def _complete_goal_projection_in_connection(
        conn: sqlite3.Connection,
        target: GoalProjectionTarget,
        store_identity: str,
        path_display: str,
        content_digest: str,
    ) -> bool:
        now = utc_now()
        updated = conn.execute(
            """
            UPDATE goal_projection_jobs
            SET state = 'completed', path_display = ?, content_digest = ?,
                prepared_content_digest = NULL, prepared_content_digests = '[]',
                last_error_code = NULL,
                updated_at = ?, completed_at = ?
            WHERE goal_id = ? AND store_identity = ? AND state = 'pending'
              AND goal_revision = ? AND source_digest = ?
              AND prepared_content_digest = ?
            """,
            (
                path_display,
                content_digest,
                now,
                now,
                target.goal_id,
                store_identity,
                target.revision,
                target.source_digest,
                content_digest,
            ),
        )
        return updated.rowcount == 1

    @contextmanager
    def goal_projection_publication(
        self,
        target: GoalProjectionTarget,
        prepared_content_digest: str,
        publication_evidence: list[tuple[str, str]],
    ) -> Generator[
        tuple[sqlite3.Row | None, tuple[sqlite3.Row, ...]],
        None,
        None,
    ]:
        """Hold the source fence through file publication and ledger completion."""
        target = self._coerce_goal_projection_target(target)
        prepared_content_digest = _goal_projection_digest(
            prepared_content_digest, field="prepared content digest"
        )
        if type(publication_evidence) is not list or publication_evidence:
            raise ValueError("goal projection publication evidence must start empty")
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            store_identity = self._memory_projection_store_identity(conn)
            job = conn.execute(
                """
                SELECT prepared_content_digests FROM goal_projection_jobs
                WHERE goal_id = ? AND store_identity = ? AND state = 'pending'
                  AND goal_revision = ? AND source_digest = ?
                  AND prepared_content_digest = ?
                """,
                (
                    target.goal_id,
                    store_identity,
                    target.revision,
                    target.source_digest,
                    prepared_content_digest,
                ),
            ).fetchone()
            goal = conn.execute(
                "SELECT * FROM goals WHERE id = ? AND revision = ?",
                (target.goal_id, target.revision),
            ).fetchone()
            steps = (
                self._goal_projection_steps(conn, target.goal_id)
                if goal is not None
                else ()
            )
            if (
                job is None
                or goal is None
                or self._goal_projection_target(conn, goal, steps=steps) != target
            ):
                goal = None
                steps = ()
            elif prepared_content_digest not in _goal_projection_digest_history(
                job["prepared_content_digests"]
            ):
                goal = None
                steps = ()
            yield goal, steps
            if not publication_evidence:
                return
            if goal is None or len(publication_evidence) != 1:
                raise RuntimeError("goal projection publication evidence is invalid")
            path_display, content_digest = publication_evidence[0]
            path_display = _goal_projection_path_display(path_display)
            content_digest = _goal_projection_digest(
                content_digest, field="content digest"
            )
            if not secrets.compare_digest(content_digest, prepared_content_digest):
                raise RuntimeError("goal projection prepared evidence changed")
            if not self._complete_goal_projection_in_connection(
                conn,
                target,
                store_identity,
                path_display,
                content_digest,
            ):
                raise RuntimeError("goal projection completion failed")

    def set_goal_status(self, goal_id: int, status: str) -> bool:
        return self.set_goal_status_result(goal_id, status).found

    def set_goal_status_result(self, goal_id: int, status: str) -> GoalTargetMutationResult:
        with _goal_source_authority_fence(self.db_path), self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            goal = conn.execute("SELECT * FROM goals WHERE id = ?", (goal_id,)).fetchone()
            if goal is None:
                return GoalTargetMutationResult(None, False, False)
            if str(goal["status"]) == status:
                return GoalTargetMutationResult(goal, True, False)
            now = utc_now()
            cur = conn.execute(
                """
                UPDATE goals
                SET status = ?, revision = revision + 1, updated_at = ?
                WHERE id = ? AND typeof(revision) = 'integer'
                  AND revision BETWEEN 1 AND 9223372036854775806
                """,
                (status, now, goal_id),
            )
            if cur.rowcount != 1:
                raise RuntimeError("goal revision could not be advanced")
            updated = conn.execute("SELECT * FROM goals WHERE id = ?", (goal_id,)).fetchone()
            if updated is None:
                raise RuntimeError("updated goal row is unavailable")
            self._upsert_goal_projection_job(conn, updated, now=now)
            return GoalTargetMutationResult(updated, True, True)

    def complete_goal_step(self, step_id: int) -> sqlite3.Row | None:
        return self.complete_goal_step_result(step_id).row

    def complete_goal_step_result(self, step_id: int) -> GoalTargetMutationResult:
        with _goal_source_authority_fence(self.db_path), self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            step = conn.execute("SELECT * FROM goal_steps WHERE id = ?", (step_id,)).fetchone()
            if step is None:
                return GoalTargetMutationResult(None, False, False)
            if str(step["status"]) == "done":
                return GoalTargetMutationResult(step, True, False)
            now = utc_now()
            cur = conn.execute(
                """
                UPDATE goal_steps
                SET status = 'done', completed_at = ?, updated_at = ?
                WHERE id = ?
                """,
                (now, now, step_id),
            )
            if cur.rowcount != 1:
                return GoalTargetMutationResult(None, False, False)
            advanced = conn.execute(
                """
                UPDATE goals
                SET revision = revision + 1, updated_at = ?
                WHERE id = ? AND typeof(revision) = 'integer'
                  AND revision BETWEEN 1 AND 9223372036854775806
                """,
                (now, step["goal_id"]),
            )
            if advanced.rowcount != 1:
                raise RuntimeError("goal revision could not be advanced")
            goal = conn.execute(
                "SELECT * FROM goals WHERE id = ?", (step["goal_id"],)
            ).fetchone()
            if goal is None:
                raise RuntimeError("updated goal row is unavailable")
            self._upsert_goal_projection_job(conn, goal, now=now)
            updated = conn.execute("SELECT * FROM goal_steps WHERE id = ?", (step_id,)).fetchone()
            return GoalTargetMutationResult(updated, True, True)

    def get_goal_projection_job(self, goal_id: int) -> sqlite3.Row | None:
        goal_id = _goal_projection_positive_int(goal_id, field="goal id")
        with self.connect() as conn:
            store_identity = self._memory_projection_store_identity(conn)
            return conn.execute(
                "SELECT * FROM goal_projection_jobs "
                "WHERE goal_id = ? AND store_identity = ?",
                (goal_id, store_identity),
            ).fetchone()

    def ensure_current_goal_projection_job(
        self,
        goal_id: int,
    ) -> GoalProjectionTarget | None:
        goal_id = _goal_projection_positive_int(goal_id, field="goal id")
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            goal = conn.execute(
                "SELECT * FROM goals WHERE id = ?", (goal_id,)
            ).fetchone()
            if goal is None:
                return None
            return self._upsert_goal_projection_job(conn, goal, now=utc_now())

    def ensure_missing_goal_projection_jobs(self, limit: int = 50) -> int:
        if type(limit) is not int or limit < 1:
            raise ValueError("goal projection job limit must be a positive integer")
        limit = min(limit, MAX_GOAL_PROJECTION_JOBS)
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            store_identity = self._memory_projection_store_identity(conn)
            goals = list(
                conn.execute(
                    """
                    SELECT goals.*
                    FROM goals
                    LEFT JOIN goal_projection_jobs AS job
                      ON job.goal_id = goals.id AND job.store_identity = ?
                    WHERE job.goal_id IS NULL
                    ORDER BY goals.id
                    LIMIT ?
                    """,
                    (store_identity, limit),
                )
            )
            now = utc_now()
            for goal in goals:
                self._upsert_goal_projection_job(conn, goal, now=now)
            return len(goals)

    def get_current_goal_projection_snapshot(
        self,
        target: GoalProjectionTarget,
    ) -> tuple[sqlite3.Row, tuple[sqlite3.Row, ...]] | None:
        target = self._coerce_goal_projection_target(target)
        with self.connect() as conn:
            conn.execute("BEGIN")
            store_identity = self._memory_projection_store_identity(conn)
            job = conn.execute(
                """
                SELECT * FROM goal_projection_jobs
                WHERE goal_id = ? AND store_identity = ?
                  AND goal_revision = ? AND source_digest = ?
                """,
                (
                    target.goal_id,
                    store_identity,
                    target.revision,
                    target.source_digest,
                ),
            ).fetchone()
            if job is None:
                return None
            goal = conn.execute(
                "SELECT * FROM goals WHERE id = ? AND revision = ?",
                (target.goal_id, target.revision),
            ).fetchone()
            if goal is None:
                return None
            steps = self._goal_projection_steps(conn, target.goal_id)
            if self._goal_projection_target(conn, goal, steps=steps) != target:
                return None
            return goal, steps

    def get_completed_goal_projection_snapshot(
        self,
        target: GoalProjectionTarget,
    ) -> tuple[sqlite3.Row, sqlite3.Row, tuple[sqlite3.Row, ...]] | None:
        """Read completed evidence and its exact source snapshot atomically."""
        target = self._coerce_goal_projection_target(target)
        with self.connect() as conn:
            conn.execute("BEGIN")
            store_identity = self._memory_projection_store_identity(conn)
            job = conn.execute(
                """
                SELECT * FROM goal_projection_jobs
                WHERE goal_id = ? AND store_identity = ? AND state = 'completed'
                  AND goal_revision = ? AND source_digest = ?
                """,
                (
                    target.goal_id,
                    store_identity,
                    target.revision,
                    target.source_digest,
                ),
            ).fetchone()
            if job is None:
                return None
            goal = conn.execute(
                "SELECT * FROM goals WHERE id = ? AND revision = ?",
                (target.goal_id, target.revision),
            ).fetchone()
            if goal is None:
                return None
            steps = self._goal_projection_steps(conn, target.goal_id)
            if self._goal_projection_target(conn, goal, steps=steps) != target:
                return None
            return job, goal, steps

    def prepare_goal_projection(
        self,
        target: GoalProjectionTarget,
        content_digest: str,
    ) -> bool:
        target = self._coerce_goal_projection_target(target)
        content_digest = _goal_projection_digest(
            content_digest, field="prepared content digest"
        )
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            store_identity = self._memory_projection_store_identity(conn)
            goal = conn.execute(
                "SELECT * FROM goals WHERE id = ? AND revision = ?",
                (target.goal_id, target.revision),
            ).fetchone()
            if goal is None:
                return False
            steps = self._goal_projection_steps(conn, target.goal_id)
            if self._goal_projection_target(conn, goal, steps=steps) != target:
                return False
            job = conn.execute(
                """
                SELECT prepared_content_digests FROM goal_projection_jobs
                WHERE goal_id = ? AND store_identity = ? AND state = 'pending'
                  AND goal_revision = ? AND source_digest = ?
                """,
                (
                    target.goal_id,
                    store_identity,
                    target.revision,
                    target.source_digest,
                ),
            ).fetchone()
            if job is None:
                return False
            history = list(
                _goal_projection_digest_history(job["prepared_content_digests"])
            )
            if content_digest not in history:
                if len(history) >= MAX_GOAL_PROJECTION_PREPARED_DIGESTS:
                    raise RuntimeError("goal projection prepared history is full")
                history.append(content_digest)
            history_json = _goal_projection_digest_history_json(history)
            updated = conn.execute(
                """
                UPDATE goal_projection_jobs
                SET prepared_content_digest = ?, prepared_content_digests = ?,
                    last_error_code = NULL, updated_at = ?
                WHERE goal_id = ? AND store_identity = ? AND state = 'pending'
                  AND goal_revision = ? AND source_digest = ?
                """,
                (
                    content_digest,
                    history_json,
                    utc_now(),
                    target.goal_id,
                    store_identity,
                    target.revision,
                    target.source_digest,
                ),
            )
            return updated.rowcount == 1

    def goal_projection_prior_content_digests(
        self,
        target: GoalProjectionTarget,
    ) -> tuple[str, ...] | None:
        target = self._coerce_goal_projection_target(target)
        with self.connect() as conn:
            store_identity = self._memory_projection_store_identity(conn)
            job = conn.execute(
                """
                SELECT prior_content_digest, prepared_content_digests
                FROM goal_projection_jobs
                WHERE goal_id = ? AND store_identity = ? AND state = 'pending'
                  AND goal_revision = ? AND source_digest = ?
                """,
                (
                    target.goal_id,
                    store_identity,
                    target.revision,
                    target.source_digest,
                ),
            ).fetchone()
            if job is None:
                return None
            history = list(
                _goal_projection_digest_history(job["prepared_content_digests"])
            )
            prior = job["prior_content_digest"]
            if prior is not None:
                prior = _goal_projection_digest(prior, field="prior content digest")
                if prior not in history:
                    history.insert(0, prior)
            return tuple(history)

    def narrow_goal_projection_prepared_history(
        self,
        target: GoalProjectionTarget,
        existing_content_digest: str | None,
    ) -> bool:
        target = self._coerce_goal_projection_target(target)
        if existing_content_digest is not None:
            existing_content_digest = _goal_projection_digest(
                existing_content_digest, field="existing content digest"
            )
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            store_identity = self._memory_projection_store_identity(conn)
            job = conn.execute(
                """
                SELECT prior_content_digest, prepared_content_digest,
                       prepared_content_digests
                FROM goal_projection_jobs
                WHERE goal_id = ? AND store_identity = ? AND state = 'pending'
                  AND goal_revision = ? AND source_digest = ?
                """,
                (
                    target.goal_id,
                    store_identity,
                    target.revision,
                    target.source_digest,
                ),
            ).fetchone()
            if job is None:
                return False
            history = _goal_projection_digest_history(
                job["prepared_content_digests"]
            )
            prior = job["prior_content_digest"]
            if prior is not None:
                prior = _goal_projection_digest(prior, field="prior content digest")
            if existing_content_digest is None or existing_content_digest == prior:
                narrowed: tuple[str, ...] = ()
            elif existing_content_digest in history:
                narrowed = (existing_content_digest,)
            else:
                return False
            current_prepared = job["prepared_content_digest"]
            if current_prepared not in narrowed:
                current_prepared = None
            updated = conn.execute(
                """
                UPDATE goal_projection_jobs
                SET prepared_content_digest = ?, prepared_content_digests = ?,
                    updated_at = ?
                WHERE goal_id = ? AND store_identity = ? AND state = 'pending'
                  AND goal_revision = ? AND source_digest = ?
                """,
                (
                    current_prepared,
                    _goal_projection_digest_history_json(narrowed),
                    utc_now(),
                    target.goal_id,
                    store_identity,
                    target.revision,
                    target.source_digest,
                ),
            )
            return updated.rowcount == 1

    def prepare_goal_projection_after_observed_content(
        self,
        target: GoalProjectionTarget,
        existing_content_digest: str | None,
        content_digest: str,
    ) -> bool:
        """Atomically narrow ambiguous custody and prepare one candidate."""
        target = self._coerce_goal_projection_target(target)
        if existing_content_digest is not None:
            existing_content_digest = _goal_projection_digest(
                existing_content_digest, field="existing content digest"
            )
        content_digest = _goal_projection_digest(
            content_digest, field="prepared content digest"
        )
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            store_identity = self._memory_projection_store_identity(conn)
            goal = conn.execute(
                "SELECT * FROM goals WHERE id = ? AND revision = ?",
                (target.goal_id, target.revision),
            ).fetchone()
            if goal is None:
                return False
            steps = self._goal_projection_steps(conn, target.goal_id)
            if self._goal_projection_target(conn, goal, steps=steps) != target:
                return False
            job = conn.execute(
                """
                SELECT prior_content_digest, prepared_content_digests
                FROM goal_projection_jobs
                WHERE goal_id = ? AND store_identity = ? AND state = 'pending'
                  AND goal_revision = ? AND source_digest = ?
                """,
                (
                    target.goal_id,
                    store_identity,
                    target.revision,
                    target.source_digest,
                ),
            ).fetchone()
            if job is None:
                return False
            history = _goal_projection_digest_history(
                job["prepared_content_digests"]
            )
            prior = job["prior_content_digest"]
            if prior is not None:
                prior = _goal_projection_digest(prior, field="prior content digest")
            if existing_content_digest is None or existing_content_digest == prior:
                narrowed: list[str] = []
            elif existing_content_digest in history:
                narrowed = [existing_content_digest]
            else:
                return False
            if content_digest not in narrowed:
                if len(narrowed) >= MAX_GOAL_PROJECTION_PREPARED_DIGESTS:
                    raise RuntimeError("goal projection prepared history is full")
                narrowed.append(content_digest)
            updated = conn.execute(
                """
                UPDATE goal_projection_jobs
                SET prepared_content_digest = ?, prepared_content_digests = ?,
                    last_error_code = NULL, updated_at = ?
                WHERE goal_id = ? AND store_identity = ? AND state = 'pending'
                  AND goal_revision = ? AND source_digest = ?
                """,
                (
                    content_digest,
                    _goal_projection_digest_history_json(narrowed),
                    utc_now(),
                    target.goal_id,
                    store_identity,
                    target.revision,
                    target.source_digest,
                ),
            )
            return updated.rowcount == 1

    def list_pending_goal_projection_jobs(
        self,
        limit: int = 50,
    ) -> list[sqlite3.Row]:
        if type(limit) is not int or limit < 1:
            raise ValueError("goal projection job limit must be a positive integer")
        limit = min(limit, MAX_GOAL_PROJECTION_JOBS)
        with self.connect() as conn:
            store_identity = self._memory_projection_store_identity(conn)
            jobs = list(
                conn.execute(
                    "SELECT * FROM goal_projection_jobs "
                    "WHERE state = 'pending' AND store_identity = ? "
                    "AND last_error_code IS NULL "
                    "ORDER BY updated_at, goal_id LIMIT ?",
                    (store_identity, limit),
                )
            )
            remaining = limit - len(jobs)
            if remaining:
                jobs.extend(
                    conn.execute(
                        "SELECT * FROM goal_projection_jobs "
                        "WHERE state = 'pending' AND store_identity = ? "
                        "AND last_error_code IS NOT NULL "
                        "ORDER BY updated_at, goal_id LIMIT ?",
                        (store_identity, remaining),
                    )
                )
            return jobs

    def list_completed_goal_projection_jobs_for_audit(
        self,
        limit: int = 50,
    ) -> list[sqlite3.Row]:
        if type(limit) is not int or limit < 1:
            raise ValueError("goal projection audit limit must be a positive integer")
        limit = min(limit, MAX_GOAL_PROJECTION_JOBS)
        with self.connect() as conn:
            store_identity = self._memory_projection_store_identity(conn)
            return list(
                conn.execute(
                    "SELECT * FROM goal_projection_jobs "
                    "WHERE state = 'completed' AND store_identity = ? "
                    "ORDER BY CASE WHEN updated_at GLOB "
                    "'[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]"
                    "T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' "
                    "THEN 1 ELSE 0 END, updated_at, goal_id LIMIT ?",
                    (store_identity, limit),
                )
            )

    def count_pending_goal_projection_jobs(self) -> int:
        with self.connect() as conn:
            store_identity = self._memory_projection_store_identity(conn)
            row = conn.execute(
                """
                SELECT COUNT(*) AS pending_count
                FROM goals
                LEFT JOIN goal_projection_jobs AS job
                  ON job.goal_id = goals.id AND job.store_identity = ?
                WHERE job.goal_id IS NULL OR job.state = 'pending'
                """,
                (store_identity,),
            ).fetchone()
        return int(row["pending_count"]) if row is not None else 0

