    def count_pending_decision_projection_jobs(self) -> int:
        with self.connect() as conn:
            store_identity = self._memory_projection_store_identity(conn)
            return int(
                conn.execute(
                    """
                    SELECT COUNT(*) FROM decisions
                    LEFT JOIN decision_projection_jobs AS job
                      ON job.decision_id = decisions.id AND job.store_identity = ?
                    WHERE job.decision_id IS NULL
                       OR job.state = 'pending'
                    """,
                    (store_identity,),
                ).fetchone()[0]
            )

    def mark_decision_projection_error(
        self, target: DecisionProjectionTarget, error_code: str
    ) -> bool:
        error_code = _person_projection_error_code(error_code)
        with self.connect() as conn:
            updated = conn.execute(
                """
                UPDATE decision_projection_jobs SET last_error_code = ?, updated_at = ?
                WHERE decision_id = ? AND decision_revision = ? AND source_digest = ?
                  AND state = 'pending'
                """,
                (error_code, utc_now(), target.decision_id, target.revision, target.source_digest),
            )
            return updated.rowcount == 1

    def complete_decision_projection(
        self, target: DecisionProjectionTarget, path_display: str, content_digest: str
    ) -> bool:
        path_display = _person_projection_path_display(path_display)
        content_digest = _person_projection_digest(content_digest, field="content digest")
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                "SELECT * FROM decisions WHERE id = ? AND revision = ?",
                (target.decision_id, target.revision),
            ).fetchone()
            if row is None or self._decision_projection_target(conn, row) != target:
                return False
            now = utc_now()
            updated = conn.execute(
                """
                UPDATE decision_projection_jobs
                SET state = 'completed', path_display = ?, content_digest = ?,
                    last_error_code = NULL, updated_at = ?, completed_at = ?
                WHERE decision_id = ? AND decision_revision = ? AND source_digest = ?
                  AND state = 'pending'
                """,
                (
                    path_display,
                    content_digest,
                    now,
                    now,
                    target.decision_id,
                    target.revision,
                    target.source_digest,
                ),
            )
            return updated.rowcount == 1

    def reopen_completed_decision_projection(
        self, target: DecisionProjectionTarget, expected_content_digest: str
    ) -> bool:
        expected_content_digest = _person_projection_digest(
            expected_content_digest, field="content digest"
        )
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                "SELECT * FROM decisions WHERE id = ? AND revision = ?",
                (target.decision_id, target.revision),
            ).fetchone()
            if row is None or self._decision_projection_target(conn, row) != target:
                return False
            updated = conn.execute(
                """
                UPDATE decision_projection_jobs
                SET state = 'pending', path_display = NULL, content_digest = NULL,
                    prior_content_digest = ?, last_error_code = 'completed_projection_invalid',
                    updated_at = ?, completed_at = NULL
                WHERE decision_id = ? AND decision_revision = ? AND source_digest = ?
                  AND state = 'completed' AND content_digest = ?
                """,
                (
                    expected_content_digest,
                    utc_now(),
                    target.decision_id,
                    target.revision,
                    target.source_digest,
                    expected_content_digest,
                ),
            )
            return updated.rowcount == 1

    def mark_decision_projection_audited(
        self, target: DecisionProjectionTarget, expected_content_digest: str
    ) -> bool:
        expected_content_digest = _person_projection_digest(
            expected_content_digest, field="content digest"
        )
        with self.connect() as conn:
            updated = conn.execute(
                "UPDATE decision_projection_jobs SET updated_at = ? "
                "WHERE decision_id = ? AND decision_revision = ? AND source_digest = ? "
                "AND state = 'completed' AND content_digest = ?",
                (
                    utc_now(),
                    target.decision_id,
                    target.revision,
                    target.source_digest,
                    expected_content_digest,
                ),
            )
            return updated.rowcount == 1

    def decision_mutation_projection_completion(
        self,
        decision_id: int,
        memory_id: int,
        decision_target: DecisionProjectionTarget,
        memory_target: MemoryProjectionTarget,
    ) -> tuple[bool, bool]:
        with self.connect() as conn:
            conn.execute("BEGIN")
            store_identity = self._memory_projection_store_identity(conn)
            decision = conn.execute(
                "SELECT * FROM decisions WHERE id = ?", (decision_id,)
            ).fetchone()
            link = conn.execute(
                "SELECT memory_id FROM decision_memory_links WHERE decision_id = ?",
                (decision_id,),
            ).fetchone()
            decision_job = conn.execute(
                "SELECT state, decision_revision, source_digest FROM decision_projection_jobs "
                "WHERE decision_id = ? AND store_identity = ?",
                (decision_id, store_identity),
            ).fetchone()
            memory = conn.execute(
                "SELECT * FROM memories WHERE id = ?", (memory_id,)
            ).fetchone()
            memory_job = conn.execute(
                "SELECT state, operation, memory_revision, source_digest "
                "FROM memory_projection_jobs "
                "WHERE memory_id = ? AND store_identity = ?",
                (memory_id, store_identity),
            ).fetchone()
            decision_current = (
                decision is not None
                and self._decision_projection_target(conn, decision) == decision_target
            )
            memory_current = False
            if memory is not None:
                memory_current = (
                    memory_target.memory_id == memory_id
                    and memory_target.operation == "publish"
                    and memory_target.revision == int(memory["revision"])
                    and memory_target.source_digest
                    == memory_projection_source_digest(
                        memory_id,
                        int(memory["revision"]),
                        memory["category"],
                        memory["title"],
                        memory["body"],
                        memory["source"],
                        memory["confidence"],
                        memory["created_at"],
                        "publish",
                    )
                )
            return (
                decision_current
                and link is not None
                and int(link["memory_id"]) == memory_id
                and decision_job is not None
                and decision_job["state"] == "completed"
                and int(decision_job["decision_revision"]) == decision_target.revision
                and decision_job["source_digest"] == decision_target.source_digest,
                memory_current
                and memory_job is not None
                and memory_job["state"] == "completed"
                and memory_job["operation"] == memory_target.operation
                and int(memory_job["memory_revision"]) == memory_target.revision
                and memory_job["source_digest"] == memory_target.source_digest,
            )

    def decision_mutation_source_integrity(
        self,
        decision_id: int,
        memory_id: int,
        decision_target: DecisionProjectionTarget,
        memory_target: MemoryProjectionTarget,
    ) -> bool:
        decision_id = _person_projection_positive_int(decision_id, field="decision id")
        memory_id = _memory_projection_positive_int(memory_id, field="memory id")
        if not isinstance(decision_target, DecisionProjectionTarget):
            raise ValueError("invalid decision projection target")
        if not isinstance(memory_target, MemoryProjectionTarget):
            raise ValueError("invalid memory projection target")
        with self.connect() as conn:
            conn.execute("BEGIN")
            decision = conn.execute(
                "SELECT * FROM decisions WHERE id = ?", (decision_id,)
            ).fetchone()
            memory = conn.execute(
                "SELECT * FROM memories WHERE id = ?", (memory_id,)
            ).fetchone()
            link = conn.execute(
                "SELECT memory_id FROM decision_memory_links WHERE decision_id = ?",
                (decision_id,),
            ).fetchone()
            if decision is None or memory is None or link is None:
                return False
            custody_conflict = bool(
                conn.execute(
                    """
                    SELECT
                        EXISTS(
                            SELECT 1 FROM decision_memory_links
                            WHERE memory_id = ? AND decision_id != ?
                        )
                        OR EXISTS(
                            SELECT 1 FROM preference_memory_links WHERE memory_id = ?
                        )
                        OR EXISTS(
                            SELECT 1 FROM person_memory_links WHERE memory_id = ?
                        )
                        OR EXISTS(
                            SELECT 1 FROM interaction_memory_links WHERE memory_id = ?
                        )
                        OR EXISTS(
                            SELECT 1 FROM organized_note_entries
                            WHERE memory_id = ? OR decision_memory_id = ?
                        )
                        OR EXISTS(
                            SELECT 1 FROM ingested_sources WHERE memory_id = ?
                        )
                        OR EXISTS(
                            SELECT 1 FROM bootstrap_memory_occurrences WHERE memory_id = ?
                        )
                        OR EXISTS(
                            SELECT 1 FROM memory_provenance WHERE memory_id = ?
                        )
                        OR EXISTS(
                            SELECT 1 FROM conversation_compaction_batches WHERE memory_id = ?
                        )
                    """,
                    (
                        memory_id,
                        decision_id,
                        memory_id,
                        memory_id,
                        memory_id,
                        memory_id,
                        memory_id,
                        memory_id,
                        memory_id,
                        memory_id,
                        memory_id,
                    ),
                ).fetchone()[0]
            )
            memory_current = bool(
                memory_target.memory_id == memory_id
                and memory_target.operation == "publish"
                and memory_target.revision == int(memory["revision"])
                and memory["category"] == "decisions"
                and memory["title"] == decision["title"]
                and memory["body"] == self._decision_memory_body(decision)
                and memory["source"] == "decision-log"
                and float(memory["confidence"]) == 1.0
                and memory_target.source_digest
                == memory_projection_source_digest(
                    memory_id,
                    int(memory["revision"]),
                    memory["category"],
                    memory["title"],
                    memory["body"],
                    memory["source"],
                    memory["confidence"],
                    memory["created_at"],
                    "publish",
                )
            )
            return bool(
                decision_target.decision_id == decision_id
                and self._decision_projection_target(conn, decision) == decision_target
                and int(link["memory_id"]) == memory_id
                and memory_current
                and not custody_conflict
            )

    def decision_projection_completion(self, target: DecisionProjectionTarget) -> bool:
        with self.connect() as conn:
            conn.execute("BEGIN")
            store_identity = self._memory_projection_store_identity(conn)
            row = conn.execute(
                "SELECT * FROM decisions WHERE id = ?", (target.decision_id,)
            ).fetchone()
            job = conn.execute(
                "SELECT state, decision_revision, source_digest "
                "FROM decision_projection_jobs "
                "WHERE decision_id = ? AND store_identity = ?",
                (target.decision_id, store_identity),
            ).fetchone()
            return bool(
                row is not None
                and self._decision_projection_target(conn, row) == target
                and job is not None
                and job["state"] == "completed"
                and int(job["decision_revision"]) == target.revision
                and job["source_digest"] == target.source_digest
            )

    def current_decision_projection_completion(self, decision_id: int) -> bool:
        decision_id = _person_projection_positive_int(decision_id, field="decision id")
        with self.connect() as conn:
            conn.execute("BEGIN")
            store_identity = self._memory_projection_store_identity(conn)
            row = conn.execute(
                "SELECT * FROM decisions WHERE id = ?", (decision_id,)
            ).fetchone()
            job = conn.execute(
                "SELECT state, decision_revision, source_digest "
                "FROM decision_projection_jobs "
                "WHERE decision_id = ? AND store_identity = ?",
                (decision_id, store_identity),
            ).fetchone()
            if row is None or job is None or job["state"] != "completed":
                return False
            target = self._decision_projection_target(conn, row)
            return bool(
                int(job["decision_revision"]) == target.revision
                and job["source_digest"] == target.source_digest
            )

    @staticmethod
    def _person_projection_interactions(
        conn: sqlite3.Connection,
        person_id: int,
    ) -> tuple[tuple[sqlite3.Row, ...], int, tuple[str, ...]]:
        watermark_row = conn.execute(
            "SELECT MAX(id) AS interaction_high_watermark "
            "FROM person_interactions WHERE person_id = ?",
            (person_id,),
        ).fetchone()
        high_watermark = _person_projection_nonnegative_int(
            0
            if watermark_row is None or watermark_row["interaction_high_watermark"] is None
            else watermark_row["interaction_high_watermark"],
            field="interaction high watermark",
        )
        rows = tuple(
            conn.execute(
                "SELECT * FROM person_interactions WHERE person_id = ? "
                "ORDER BY happened_at DESC, id DESC LIMIT ?",
                (person_id, MAX_PERSON_PROJECTION_INTERACTIONS),
            )
        )
        rendered: list[str] = []
        for row in rows:
            _person_projection_positive_int(row["id"], field="interaction id")
            if type(row["happened_at"]) is not str or type(row["summary"]) is not str:
                raise ValueError("person projection interaction fields must be strings")
            rendered.append(f"- {row['happened_at']}: {row['summary']}")
        if not rendered:
            rendered.append("- No interactions captured.")
        return rows, high_watermark, tuple(rendered)

    @staticmethod
    def _person_projection_target(
        conn: sqlite3.Connection,
        person_row: sqlite3.Row,
    ) -> tuple[PersonProjectionTarget, tuple[sqlite3.Row, ...]]:
        person_id = _person_projection_positive_int(person_row["id"], field="person id")
        revision = _person_projection_nonnegative_int(
            person_row["revision"], field="revision"
        )
        interactions, high_watermark, rendered = MemoryStore._person_projection_interactions(
            conn, person_id
        )
        source_digest = person_projection_source_digest(
            person_id,
            revision,
            person_row["name"],
            person_row["relation"],
            person_row["notes"],
            person_row["last_contact_at"],
            person_row["created_at"],
            person_row["updated_at"],
            high_watermark,
            rendered,
        )
        return (
            PersonProjectionTarget(
                person_id=person_id,
                revision=revision,
                interaction_high_watermark=high_watermark,
                source_digest=source_digest,
            ),
            interactions,
        )

    @staticmethod
    def _upsert_person_projection_job(
        conn: sqlite3.Connection,
        person_row: sqlite3.Row,
        *,
        now: str,
    ) -> PersonProjectionTarget:
        target, _ = MemoryStore._person_projection_target(conn, person_row)
        store_identity = MemoryStore._memory_projection_store_identity(conn)
        upserted = conn.execute(
            """
            INSERT INTO person_projection_jobs(
                person_id, store_identity, state, person_revision,
                interaction_high_watermark, source_digest, path_display,
                content_digest, last_error_code, created_at, updated_at, completed_at
            )
            VALUES (?, ?, 'pending', ?, ?, ?, NULL, NULL, NULL, ?, ?, NULL)
            ON CONFLICT(person_id) DO UPDATE SET
                state=CASE
                    WHEN person_projection_jobs.person_revision = excluded.person_revision
                     AND person_projection_jobs.interaction_high_watermark =
                         excluded.interaction_high_watermark
                     AND person_projection_jobs.source_digest = excluded.source_digest
                        THEN person_projection_jobs.state
                    ELSE 'pending'
                END,
                person_revision=excluded.person_revision,
                interaction_high_watermark=excluded.interaction_high_watermark,
                source_digest=excluded.source_digest,
                path_display=CASE
                    WHEN person_projection_jobs.person_revision = excluded.person_revision
                     AND person_projection_jobs.interaction_high_watermark =
                         excluded.interaction_high_watermark
                     AND person_projection_jobs.source_digest = excluded.source_digest
                        THEN person_projection_jobs.path_display
                    ELSE NULL
                END,
                content_digest=CASE
                    WHEN person_projection_jobs.person_revision = excluded.person_revision
                     AND person_projection_jobs.interaction_high_watermark =
                         excluded.interaction_high_watermark
                     AND person_projection_jobs.source_digest = excluded.source_digest
                        THEN person_projection_jobs.content_digest
                    ELSE NULL
                END,
                last_error_code=CASE
                    WHEN person_projection_jobs.person_revision = excluded.person_revision
                     AND person_projection_jobs.interaction_high_watermark =
                         excluded.interaction_high_watermark
                     AND person_projection_jobs.source_digest = excluded.source_digest
                        THEN person_projection_jobs.last_error_code
                    ELSE NULL
                END,
                created_at=CASE
                    WHEN person_projection_jobs.state = 'pending'
                        THEN person_projection_jobs.created_at
                    ELSE excluded.created_at
                END,
                updated_at=CASE
                    WHEN person_projection_jobs.person_revision = excluded.person_revision
                     AND person_projection_jobs.interaction_high_watermark =
                         excluded.interaction_high_watermark
                     AND person_projection_jobs.source_digest = excluded.source_digest
                        THEN person_projection_jobs.updated_at
                    ELSE excluded.updated_at
                END,
                completed_at=CASE
                    WHEN person_projection_jobs.person_revision = excluded.person_revision
                     AND person_projection_jobs.interaction_high_watermark =
                         excluded.interaction_high_watermark
                     AND person_projection_jobs.source_digest = excluded.source_digest
                        THEN person_projection_jobs.completed_at
                    ELSE NULL
                END
            WHERE person_projection_jobs.store_identity = excluded.store_identity
              AND (
                    excluded.person_revision > person_projection_jobs.person_revision
                    OR (
                        excluded.person_revision = person_projection_jobs.person_revision
                        AND excluded.interaction_high_watermark >=
                            person_projection_jobs.interaction_high_watermark
                    )
                  )
            """,
            (
                target.person_id,
                store_identity,
                target.revision,
                target.interaction_high_watermark,
                target.source_digest,
                now,
                now,
            ),
        )
        if upserted.rowcount != 1:
            raise RuntimeError("person projection job is newer or belongs to another store")
        return target

    @staticmethod
    def _coerce_person_projection_target(
        person_id: int | PersonProjectionTarget,
        expected_revision: int | None,
        expected_interaction_high_watermark: int | None,
        expected_source_digest: str | None,
    ) -> PersonProjectionTarget:
        if isinstance(person_id, PersonProjectionTarget):
            if any(
                value is not None
                for value in (
                    expected_revision,
                    expected_interaction_high_watermark,
                    expected_source_digest,
                )
            ):
                raise ValueError("person projection target must not be mixed with target fields")
            target = person_id
        else:
            if (
                expected_revision is None
                or expected_interaction_high_watermark is None
                or expected_source_digest is None
            ):
                raise ValueError("exact person projection target is required")
            target = PersonProjectionTarget(
                person_id=person_id,
                revision=expected_revision,
                interaction_high_watermark=expected_interaction_high_watermark,
                source_digest=expected_source_digest,
            )
        return PersonProjectionTarget(
            person_id=_person_projection_positive_int(target.person_id, field="person id"),
            revision=_person_projection_nonnegative_int(target.revision, field="revision"),
            interaction_high_watermark=_person_projection_nonnegative_int(
                target.interaction_high_watermark,
                field="interaction high watermark",
            ),
            source_digest=_person_projection_digest(
                target.source_digest, field="expected source digest"
            ),
        )

    def upsert_person(self, record: PersonRecord) -> int:
        now = utc_now()
        identity, identity_state, _ = self._person_identity_membership(record.name)
        if identity_state != "valid" or identity is None:
            raise ValueError("person name is invalid")
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            self._drain_person_identity_dirty(conn)
            owner = self._canonical_person_owner(conn, identity)
            if owner is not None:
                notes = str(owner["notes"] or "")
                if record.notes and notes != record.notes and not notes.endswith("\n" + record.notes):
                    notes = f"{notes}\n{record.notes}" if notes else record.notes
                relation = record.relation if record.relation else owner["relation"]
                changed = relation != owner["relation"] or notes != owner["notes"]
                updated = conn.execute(
                    """
                    UPDATE people
                    SET relation = ?, notes = ?,
                        revision = revision + 1,
                        updated_at = ?
                    WHERE id = ? AND typeof(revision) = 'integer'
                      AND revision BETWEEN 0 AND 9223372036854775806
                      AND (relation IS NOT ? OR notes IS NOT ?)
                    """,
                    (relation, notes, now, owner["id"], relation, notes),
                )
                if changed and updated.rowcount != 1:
                    raise RuntimeError("person revision could not be advanced")
                person_id = int(owner["id"])
                person_row = conn.execute(
                    "SELECT * FROM people WHERE id = ?", (person_id,)
                ).fetchone()
                if person_row is None:
                    raise RuntimeError("updated person row is unavailable")
                self._upsert_person_projection_job(conn, person_row, now=now)
                return person_id

            cur = conn.execute(
                """
                INSERT INTO people(name, relation, notes, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?)
                """,
                (record.name, record.relation, record.notes, now, now),
            )
            person_id = int(cur.lastrowid)
            self._insert_person_identity_membership(
                conn,
                person_id,
                record.name,
            )
            person_row = conn.execute(
                "SELECT * FROM people WHERE id = ?", (person_id,)
            ).fetchone()
            if person_row is None:
                raise RuntimeError("created person row is unavailable")
            self._upsert_person_projection_job(conn, person_row, now=now)
            return person_id

    def record_person_with_projections(self, record: PersonRecord) -> PersonMutationTarget:
        """Commit one person mutation, its memory, link, and projection custody together."""
        if any(type(value) is not str for value in (record.name, record.relation, record.notes)):
            raise ValueError("person fields must be strings")
        if (
            not record.name
            or not person_identity_part(record.name)
            or len(record.name) > MAX_PERSON_NAME_CHARS
            or len(record.relation) > MAX_PERSON_RELATION_CHARS
            or len(record.notes) > MAX_PERSON_NOTES_CHARS
        ):
            raise ValueError("person fields are invalid")
        try:
            record.name.encode("utf-8")
            record.relation.encode("utf-8")
            record.notes.encode("utf-8")
        except UnicodeEncodeError as exc:
            raise ValueError("person fields must contain valid Unicode") from exc

        now = utc_now()
        identity = person_identity_part(record.name)
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            self._drain_person_identity_dirty(conn)
            owner = self._canonical_person_owner(conn, identity)
            created_person = False
            if owner is not None:
                notes = str(owner["notes"] or "")
                if record.notes and notes != record.notes and not notes.endswith("\n" + record.notes):
                    notes = f"{notes}\n{record.notes}" if notes else record.notes
                relation = record.relation if record.relation else owner["relation"]
                changed = relation != owner["relation"] or notes != owner["notes"]
                updated = conn.execute(
                    """
                    UPDATE people
                    SET relation = ?, notes = ?, revision = revision + 1, updated_at = ?
                    WHERE id = ? AND typeof(revision) = 'integer'
                      AND revision BETWEEN 0 AND 9223372036854775806
                      AND (relation IS NOT ? OR notes IS NOT ?)
                    """,
                    (relation, notes, now, owner["id"], relation, notes),
                )
                if changed and updated.rowcount != 1:
                    raise RuntimeError("person revision could not be advanced")
                person_id = int(owner["id"])
            else:
                inserted = conn.execute(
                    """
                    INSERT INTO people(name, relation, notes, created_at, updated_at)
                    VALUES (?, ?, ?, ?, ?)
                    """,
                    (record.name, record.relation, record.notes, now, now),
                )
                person_id = int(inserted.lastrowid)
                self._insert_person_identity_membership(
                    conn,
                    person_id,
                    record.name,
                )
                created_person = True

            person_row = conn.execute(
                "SELECT * FROM people WHERE id = ?", (person_id,)
            ).fetchone()
            if person_row is None:
                raise RuntimeError("person row is unavailable")
            canonical_name = str(person_row["name"])
            person_target = self._upsert_person_projection_job(conn, person_row, now=now)

            canonical_relation = str(person_row["relation"] or "")
            canonical_notes = str(person_row["notes"] or "")
            memory_body = f"Relation: {canonical_relation or 'not captured'}"
            if canonical_notes:
                memory_body += f"\n\nNotes: {canonical_notes}"
            linked_memory = conn.execute(
                "SELECT memory_id FROM person_memory_links WHERE person_id = ?",
                (person_id,),
            ).fetchone()
            if linked_memory is None:
                legacy_candidates = [
                    row
                    for row in conn.execute(
                        """
                        SELECT memories.id, memories.title
                        FROM memories
                        LEFT JOIN person_memory_links AS profile_link
                          ON profile_link.memory_id = memories.id
                        LEFT JOIN interaction_memory_links AS interaction_link
                          ON interaction_link.memory_id = memories.id
                        WHERE memories.category = 'people'
                          AND memories.source = 'people-log'
                          AND profile_link.memory_id IS NULL
                          AND interaction_link.memory_id IS NULL
                        ORDER BY memories.id DESC
                        """
                    )
                    if person_identity_part(row["title"]) == identity
                ]
                if legacy_candidates:
                    memory_id = int(legacy_candidates[0]["id"])
                else:
                    inserted_memory = conn.execute(
                        """
                        INSERT INTO memories(
                            category, title, body, source, confidence, created_at, updated_at
                        ) VALUES ('people', ?, ?, 'people-log', 1.0, ?, ?)
                        """,
                        (canonical_name, memory_body, now, now),
                    )
                    memory_id = int(inserted_memory.lastrowid)
                conn.execute(
                    """
                    INSERT INTO person_memory_links(
                        memory_id, person_id, created_at, updated_at
                    ) VALUES (?, ?, ?, ?)
                    """,
                    (memory_id, person_id, now, now),
                )
                if legacy_candidates:
                    updated_memory = conn.execute(
                        """
                        UPDATE memories
                        SET category = 'people', title = ?, body = ?, source = 'people-log',
                            confidence = 1.0, revision = revision + 1, updated_at = ?
                        WHERE id = ? AND typeof(revision) = 'integer'
                          AND revision BETWEEN 1 AND 9223372036854775806
                        """,
                        (canonical_name, memory_body, now, memory_id),
                    )
                    if updated_memory.rowcount != 1:
                        raise RuntimeError("legacy person memory revision could not be advanced")
            else:
                memory_id = int(linked_memory["memory_id"])
                updated_memory = conn.execute(
                    """
                    UPDATE memories
                    SET category = 'people', title = ?, body = ?, source = 'people-log',
                        confidence = 1.0, revision = revision + 1, updated_at = ?
                    WHERE id = ? AND typeof(revision) = 'integer'
                      AND revision BETWEEN 1 AND 9223372036854775806
                    """,
                    (canonical_name, memory_body, now, memory_id),
                )
                if updated_memory.rowcount != 1:
                    raise RuntimeError("person memory revision could not be advanced")
            memory_row = conn.execute(
                "SELECT * FROM memories WHERE id = ?", (memory_id,)
            ).fetchone()
            if memory_row is None:
                raise RuntimeError("person memory row is unavailable")
            memory_target = self._upsert_memory_projection_job(
                conn,
                memory_row,
                operation="publish",
                now=now,
                legacy_row=None,
            )
            return PersonMutationTarget(
                person_id=person_id,
                memory_id=memory_id,
                person_name=canonical_name,
                created_person=created_person,
                person_projection_target=person_target,
                memory_projection_target=memory_target,
            )

    def person_mutation_projection_completion(
        self, person_id: int, memory_id: int
    ) -> tuple[bool, bool]:
        """Read both current projection states from one SQLite snapshot."""
        person_id = _person_projection_positive_int(person_id, field="person id")
        memory_id = _memory_projection_positive_int(memory_id, field="memory id")
        with self.connect() as conn:
            conn.execute("BEGIN")
            store_identity = self._memory_projection_store_identity(conn)
            person_job = conn.execute(
                "SELECT state FROM person_projection_jobs "
                "WHERE person_id = ? AND store_identity = ?",
                (person_id, store_identity),
            ).fetchone()
            memory_job = conn.execute(
                "SELECT state FROM memory_projection_jobs "
                "WHERE memory_id = ? AND store_identity = ?",
                (memory_id, store_identity),
            ).fetchone()
            return (
                person_job is not None and person_job["state"] == "completed",
                memory_job is not None and memory_job["state"] == "completed",
            )

    def list_people(self, limit: int = 50) -> list[sqlite3.Row]:
        with self.connect() as conn:
            return list(conn.execute("SELECT * FROM people ORDER BY updated_at DESC LIMIT ?", (limit,)))

    def get_person(self, person_id: int | None = None, name: str | None = None) -> sqlite3.Row | None:
        with self.connect() as conn:
            if person_id is not None:
                return conn.execute("SELECT * FROM people WHERE id = ?", (person_id,)).fetchone()
            if name:
                conn.execute("BEGIN")
                identity = person_identity_part(name)
                return self._read_person_owner(conn, identity)
            return None

    def get_person_if_identity_matches(
        self,
        person_id: int,
        identity_key: str,
    ) -> tuple[str, sqlite3.Row | None]:
        """Read a full person row only after id and canonical name agree."""
        person_id = _person_projection_positive_int(person_id, field="person id")
        if type(identity_key) is not str or not identity_key:
            raise ValueError("person identity is invalid")
        with self.connect() as conn:
            conn.execute("BEGIN")
            by_id = conn.execute(
                "SELECT id, name FROM people WHERE id = ?",
                (person_id,),
            ).fetchone()
            if by_id is None:
                return "not_found", None
            id_name = by_id["name"]
            if type(id_name) is not str:
                return "unreadable_person", None
            if person_identity_part(id_name) != identity_key:
                return "person_target_mismatch", None

            owner = self._read_person_identity_owner(conn, identity_key)
            if owner is None:
                return "stale_person_identity", None
            owner_id = owner["id"]
            owner_name = owner["name"]
            if type(owner_id) is not int or type(owner_name) is not str:
                return "unreadable_person", None
            if person_identity_part(owner_name) != identity_key:
                return "ambiguous_person_identity", None
            if owner_id != person_id:
                return "noncanonical_person_id", None

            person = conn.execute(
                "SELECT * FROM people WHERE id = ?",
                (person_id,),
            ).fetchone()
            if person is None:
                return "stale_person_identity", None
            final_name = person["name"]
            if type(final_name) is not str or person_identity_part(final_name) != identity_key:
                return "stale_person_identity", None
            return "resolved", person

    def count_person_identity_conflicts(self) -> int:
        """Return the number of valid rows shadowed by a lower-ID identity owner."""
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            self._drain_person_identity_dirty(conn)
            return int(
                conn.execute(
                    """
                    SELECT COUNT(*) - COUNT(DISTINCT identity_key)
                    FROM person_identity_memberships
                         INDEXED BY person_identity_memberships_owner_idx
                    WHERE state = 'valid'
                    """
                ).fetchone()[0]
            )

    def review_person_identity_memberships(
        self,
        after_person_id: int = 0,
        scan_limit: int = 50,
    ) -> dict[str, Any]:
        """Return a bounded, privacy-safe membership review page."""
        if type(after_person_id) is not int or after_person_id < 0:
            raise ValueError("person identity review cursor must be a nonnegative integer")
        if type(scan_limit) is not int:
            raise TypeError("person identity review scan limit must be an integer")
        scan_limit = max(1, min(scan_limit, MAX_PERSON_IDENTITY_REVIEW_SCAN))
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            self._drain_person_identity_dirty(conn)
            rows = list(
                conn.execute(
                    """
                    SELECT membership.person_id, membership.state,
                           membership.error_code,
                           CASE WHEN membership.state = 'valid' THEN (
                               SELECT COUNT(*)
                               FROM person_identity_memberships AS peer
                                    INDEXED BY person_identity_memberships_owner_idx
                               WHERE peer.identity_key = membership.identity_key
                                 AND peer.state = 'valid'
                           ) ELSE 0 END AS identity_count,
                           CASE
                               WHEN membership.state = 'quarantined'
                                   THEN membership.error_code
                               WHEN EXISTS (
                                   SELECT 1
                                   FROM person_identity_memberships AS prior
                                        INDEXED BY person_identity_memberships_owner_idx
                                   WHERE prior.identity_key = membership.identity_key
                                     AND prior.state = 'valid'
                                     AND prior.person_id < membership.person_id
                               ) THEN 'shadow'
                               ELSE 'owner'
                           END AS reason
                    FROM person_identity_memberships AS membership
                    WHERE membership.person_id > ?
                    ORDER BY membership.person_id
                    LIMIT ?
                    """,
                    (after_person_id, scan_limit + 1),
                )
            )
        complete = len(rows) <= scan_limit
        page = rows[:scan_limit]
        next_after_person_id = int(page[-1]["person_id"]) if page else after_person_id
        review_rows = tuple(
            {
                "person_id": int(row["person_id"]),
                "count": int(row["identity_count"]),
                "reason": str(row["reason"]),
            }
            for row in page
        )
        return {
            "rows": review_rows,
            "scanned": len(review_rows),
            "next_after_person_id": next_after_person_id,
            "complete": complete,
        }

    def log_person_interaction(self, person_id: int, summary: str, happened_at: str = "") -> int:
        now = utc_now()
        event_time = happened_at or now
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            self._drain_person_identity_dirty(conn)
            membership = conn.execute(
                """
                SELECT identity_key, state, normalizer_version
                FROM person_identity_memberships
                WHERE person_id = ?
                """,
                (person_id,),
            ).fetchone()
            if membership is None:
                raise sqlite3.IntegrityError("FOREIGN KEY constraint failed")
            if (
                membership["state"] != "valid"
                or membership["normalizer_version"] != PERSON_IDENTITY_NORMALIZER_VERSION
            ):
                raise ValueError("person id is not canonical")
            owner = self._canonical_person_owner(conn, str(membership["identity_key"]))
            if owner is None or int(owner["id"]) != person_id:
                raise ValueError("person id is not canonical")
            cur = conn.execute(
                """
                INSERT INTO person_interactions(person_id, summary, happened_at, created_at)
                VALUES (?, ?, ?, ?)
                """,
                (person_id, summary, event_time, now),
            )
            conn.execute(
                "UPDATE people SET last_contact_at = ?, revision = revision + 1, updated_at = ? WHERE id = ?",
                (event_time, now, person_id),
            )
            interaction_id = int(cur.lastrowid)
            person_row = conn.execute(
                "SELECT * FROM people WHERE id = ?", (person_id,)
            ).fetchone()
            if person_row is None:
                raise RuntimeError("updated person row is unavailable")
            self._upsert_person_projection_job(conn, person_row, now=now)
            return interaction_id

    def list_person_interactions(self, person_id: int, limit: int = 10) -> list[sqlite3.Row]:
        with self.connect() as conn:
            return list(
                conn.execute(
                    "SELECT * FROM person_interactions WHERE person_id = ? ORDER BY happened_at DESC, id DESC LIMIT ?",
                    (person_id, limit),
                )
            )

    def record_person_interaction_with_projections(
        self,
        *,
        person_id: int | None,
        name: str,
        summary: str,
        happened_at: str,
    ) -> InteractionMutationTarget:
        """Commit an interaction, its memory, links, and projection custody together."""
        if person_id is not None:
            person_id = _person_projection_positive_int(person_id, field="person id")
        if type(name) is not str:
            raise ValueError("person name must be a string")
        if type(summary) is not str:
            raise ValueError("person interaction summary must be a string")
        if type(happened_at) is not str:
            raise ValueError("person interaction timestamp must be a string")
        name = name.strip()
        summary = summary.strip()
        happened_at = happened_at.strip()
        if not name or not person_identity_part(name) or len(name) > MAX_PERSON_NAME_CHARS:
            raise ValueError("person name is invalid")
        if not summary or len(summary) > MAX_PERSON_INTERACTION_CHARS:
            raise ValueError("person interaction summary is invalid")
        if len(happened_at) > MAX_PERSON_HAPPENED_AT_CHARS:
            raise ValueError("person interaction timestamp is too long")
        try:
            name.encode("utf-8")
            summary.encode("utf-8")
            happened_at.encode("utf-8")
        except UnicodeEncodeError as exc:
            raise ValueError("person interaction fields must contain valid Unicode") from exc

        now = utc_now()
        event_time = happened_at or now
        identity = person_identity_part(name)
        with self.connect() as conn:
            conn.execute("BEGIN IMMEDIATE")
            self._drain_person_identity_dirty(conn)
            owner = self._canonical_person_owner(conn, identity)
            created_person = False
            if person_id is not None:
                selected = conn.execute(
                    "SELECT * FROM people WHERE id = ?", (person_id,)
                ).fetchone()
                if selected is None:
                    raise ValueError("person id does not exist")
                selected_membership = conn.execute(
                    """
                    SELECT identity_key, state
                    FROM person_identity_memberships
                    WHERE person_id = ?
                    """,
                    (person_id,),
                ).fetchone()
                if (
                    selected_membership is None
                    or selected_membership["state"] != "valid"
                    or selected_membership["identity_key"] != identity
                ):
                    raise ValueError("person id and name do not match")
                if owner is None or int(owner["id"]) != person_id:
                    raise ValueError("person id is not the canonical owner of that name")
            elif owner is not None:
                selected = owner
                person_id = int(selected["id"])
            else:
                inserted = conn.execute(
                    """
                    INSERT INTO people(name, relation, notes, created_at, updated_at)
                    VALUES (?, '', '', ?, ?)
                    """,
                    (name, now, now),
                )
                person_id = int(inserted.lastrowid)
                self._insert_person_identity_membership(
                    conn,
                    person_id,
                    name,
                )
                selected = conn.execute(
                    "SELECT * FROM people WHERE id = ?", (person_id,)
                ).fetchone()
                created_person = True
            if selected is None:
                raise RuntimeError("canonical person row is unavailable")
            canonical_name = str(selected["name"])

            inserted_interaction = conn.execute(
                """
                INSERT INTO person_interactions(person_id, summary, happened_at, created_at)
                VALUES (?, ?, ?, ?)
                """,
                (person_id, summary, event_time, now),
            )
            interaction_id = int(inserted_interaction.lastrowid)
            person_updated = conn.execute(
                """
                UPDATE people
                SET last_contact_at = ?, revision = revision + 1, updated_at = ?
                WHERE id = ? AND typeof(revision) = 'integer'
                  AND revision BETWEEN 0 AND 9223372036854775806
                """,
                (event_time, now, person_id),
            )
            if person_updated.rowcount != 1:
                raise RuntimeError("person revision could not be advanced")

            inserted_memory = conn.execute(
                """
                INSERT INTO memories(
                    category, title, body, source, confidence, created_at, updated_at
                )
                VALUES ('people', ?, ?, 'people-log', 1.0, ?, ?)
                """,
                (f"Interaction with {canonical_name}", summary, now, now),
            )
            memory_id = int(inserted_memory.lastrowid)
            memory_row = conn.execute(
                "SELECT * FROM memories WHERE id = ?", (memory_id,)
            ).fetchone()
            if memory_row is None:
                raise RuntimeError("interaction memory row is unavailable")
            memory_target = self._upsert_memory_projection_job(
                conn,
                memory_row,
                operation="publish",
                now=now,
                legacy_row=None,
            )
            conn.execute(
                """
                INSERT INTO interaction_memory_links(
                    interaction_id, memory_id, created_at, updated_at
                ) VALUES (?, ?, ?, ?)
                """,
                (interaction_id, memory_id, now, now),
            )
            person_row = conn.execute(
                "SELECT * FROM people WHERE id = ?", (person_id,)
            ).fetchone()
            if person_row is None:
                raise RuntimeError("updated person row is unavailable")
            person_target = self._upsert_person_projection_job(
                conn,
                person_row,
                now=now,
            )
            return InteractionMutationTarget(
                person_id=person_id,
                interaction_id=interaction_id,
                memory_id=memory_id,
                person_name=canonical_name,
                created_person=created_person,
                person_projection_target=person_target,
                memory_projection_target=memory_target,
            )

    def get_person_projection_job(self, person_id: int) -> sqlite3.Row | None:
        person_id = _person_projection_positive_int(person_id, field="person id")
        with self.connect() as conn:
            store_identity = self._memory_projection_store_identity(conn)
            return conn.execute(
                "SELECT * FROM person_projection_jobs "
                "WHERE person_id = ? AND store_identity = ?",
                (person_id, store_identity),
            ).fetchone()

